//! `LanguageParser` implementation for XAML, via `tree-sitter-xml` (XAML is
//! well-formed XML syntactically — there is no dedicated XAML grammar).
//!
//! Nothing here is known to `mct-core`, `mct-index`, or `mct-mcp-server` —
//! this crate is the entire integration surface for XAML support.
//!
//! An element's `x:Name` (checked first) or plain `Name` attribute names its
//! `Element` symbol, nested under its nearest such ancestor — same shape as
//! `mct-lang-html`/`mct-lang-xml`. Unlike generic XML, XAML *does* have a
//! well-defined cross-file convention: a routed-event attribute
//! (`Click="SaveBtn_Click"`, `Loaded="Window_Loaded"`, ...) names a method in
//! the paired code-behind file (`Foo.xaml` -> `Foo.xaml.cs`). Each such
//! attribute whose value looks like a bare identifier (not a `{Binding ...}`
//! expression) emits a `References` relation to that name, with a
//! `RelationTarget` naming the code-behind file and `csharp` as where it is
//! declared — the explicit evidence a cross-language relation needs to
//! resolve against what `mct-lang-csharp` indexed. `EVENT_ATTRIBUTE_NAMES` is a
//! bounded, explicit list (WPF/UWP/WinUI/MAUI/Avalonia routed events), not a
//! generic "any capitalized attribute" heuristic — deliberately, to avoid
//! false positives from style/layout properties.

use mct_core::{
    LanguageParser, Location, ParseError, ParsedFile, RelationKind, RelationTarget, SourceFile,
    SymbolId, SymbolKind, SymbolRecord, SymbolRelation, MAX_TRAVERSAL_DEPTH,
};
use mct_tree_sitter::{first_error, location};
use tree_sitter::{Node, Parser};

/// Common routed/CLR event attribute names across WPF, UWP/WinUI, MAUI, and
/// Avalonia. Not exhaustive by design — see the module doc.
const EVENT_ATTRIBUTE_NAMES: &[&str] = &[
    "Click",
    "DoubleTapped",
    "Tapped",
    "Checked",
    "Unchecked",
    "CheckedChanged",
    "IsCheckedChanged",
    "Toggled",
    "Loaded",
    "Unloaded",
    "Initialized",
    "SelectionChanged",
    "TextChanged",
    "GotFocus",
    "LostFocus",
    "GotKeyboardFocus",
    "LostKeyboardFocus",
    "MouseEnter",
    "MouseLeave",
    "MouseDown",
    "MouseUp",
    "MouseMove",
    "MouseWheel",
    "PreviewMouseDown",
    "PreviewMouseUp",
    "PreviewMouseMove",
    "KeyDown",
    "KeyUp",
    "PreviewKeyDown",
    "PreviewKeyUp",
    "Drop",
    "DragEnter",
    "DragLeave",
    "DragOver",
    "ValueChanged",
    "Closing",
    "Closed",
    "Opened",
    "Activated",
    "Deactivated",
    "CollectionChanged",
    "PropertyChanged",
];

pub struct XamlParser;

impl LanguageParser for XamlParser {
    fn language_id(&self) -> &'static str {
        "xaml"
    }

    fn file_extensions(&self) -> &'static [&'static str] {
        &["xaml"]
    }

    fn parse(&self, file: &SourceFile) -> Result<ParsedFile, ParseError> {
        let mut parser = Parser::new();
        #[allow(clippy::expect_used)]
        // SAFETY: `tree_sitter_xml::LANGUAGE_XML` is a statically linked
        // grammar compiled into this binary; `set_language` only fails on an
        // ABI mismatch between the grammar and this `tree-sitter` version,
        // which Cargo.lock pins at build time — it never depends on the
        // content of an indexed repo.
        parser
            .set_language(&tree_sitter_xml::LANGUAGE_XML.into())
            .expect("tree-sitter-xml grammar is statically valid");

        let tree = parser
            .parse(&file.contents, None)
            .ok_or_else(|| ParseError::Syntax {
                path: file.relative_path.clone(),
                line: 1,
                message: "tree-sitter produced no parse tree".to_string(),
            })?;

        let root = tree.root_node();
        if root.has_error() {
            let error_node = first_error(root).unwrap_or(root);
            return Err(ParseError::Syntax {
                path: file.relative_path.clone(),
                line: error_node.start_position().row as u32 + 1,
                message: "syntax error".to_string(),
            });
        }

        let module_name = module_name_for(&file.relative_path);
        let mut walker = Walker::new(&file.contents, &file.relative_path);
        let module_id =
            walker.push_symbol(module_name, SymbolKind::Module, module_location(root), None);
        walker.visit_children(root, module_id, None, 0);
        let import_targets = std::mem::take(&mut walker.import_targets);
        let mut parsed = walker.finish();
        // Every `References` relation is an event handler, declared in the
        // paired code-behind file (`Foo.xaml` -> `Foo.xaml.cs`): explicit
        // evidence for the one cross-language link this parser makes.
        let code_behind = format!("{}.cs", file.relative_path);
        parsed.relation_targets = (0..parsed.relations.len())
            .filter(|&relation| parsed.relations[relation].kind == RelationKind::References)
            .map(|relation| RelationTarget {
                relation,
                path: Some(code_behind.clone()),
                language: Some("csharp".to_string()),
                ..Default::default()
            })
            .chain(import_targets)
            .collect();
        Ok(parsed)
    }
}

fn module_name_for(relative_path: &str) -> String {
    relative_path
        .rsplit('/')
        .next()
        .unwrap_or(relative_path)
        .trim_end_matches(".xaml")
        .to_string()
}

/// The file-level module's location: the root node of a file ending in a
/// newline ends at column 0 of the row *after* the last line, which would
/// put the module one line past the end of the file.
fn module_location(root: Node) -> Location {
    let mut loc = location(root);
    let end = root.end_position();
    if end.column == 0 && end.row > root.start_position().row {
        loc.end_line = Some(end.row as u32);
    }
    loc
}

fn text<'a>(node: Node, source: &'a str) -> &'a str {
    node.utf8_text(source.as_bytes()).unwrap_or_default()
}

/// An `AttValue` node's raw text includes its surrounding quotes (`"Foo"` or
/// `'Foo'`) — this strips exactly one matching pair, if present.
fn unquote(raw: &str) -> &str {
    let bytes = raw.as_bytes();
    if bytes.len() >= 2 {
        let first = bytes[0];
        let last = bytes[bytes.len() - 1];
        if (first == b'"' || first == b'\'') && first == last {
            return &raw[1..raw.len() - 1];
        }
    }
    raw
}

/// A plain identifier: `Foo_Click`, not `{Binding SaveCommand}` or `1.0` or
/// text containing spaces — the shape a bare code-behind method name has.
fn looks_like_identifier(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

struct Walker<'a> {
    source: &'a str,
    symbols: Vec<SymbolRecord>,
    relations: Vec<SymbolRelation>,
    /// Evidence for the `Imports` relations of merged resource dictionaries.
    import_targets: Vec<RelationTarget>,
    /// This file's repository-relative path, the base of relative `Source`s.
    path: &'a str,
    next_id: SymbolId,
}

impl<'a> Walker<'a> {
    fn new(source: &'a str, path: &'a str) -> Self {
        Self {
            source,
            path,
            import_targets: Vec::new(),
            symbols: Vec::new(),
            relations: Vec::new(),
            next_id: 0,
        }
    }

    fn push_symbol(
        &mut self,
        name: String,
        kind: SymbolKind,
        location: Location,
        parent: Option<String>,
    ) -> SymbolId {
        let id = self.next_id;
        self.next_id += 1;
        self.symbols.push(SymbolRecord {
            id,
            name,
            kind,
            location,
            parent,
            level: None,
        });
        id
    }

    fn push_relation(
        &mut self,
        from: SymbolId,
        kind: RelationKind,
        to_name: String,
        loc: Location,
    ) {
        if to_name.is_empty() {
            return;
        }
        self.relations.push(SymbolRelation {
            from,
            kind,
            to_name,
            location: loc,
        });
    }

    fn visit_children(
        &mut self,
        node: Node,
        owner: SymbolId,
        parent_name: Option<&str>,
        depth: u32,
    ) {
        let mut cursor = node.walk();
        for child in node.named_children(&mut cursor) {
            self.visit(child, owner, parent_name, depth + 1);
        }
    }

    fn visit(&mut self, node: Node, owner: SymbolId, parent_name: Option<&str>, depth: u32) {
        if depth >= MAX_TRAVERSAL_DEPTH {
            return;
        }
        match node.kind() {
            "element" => {
                let tag = find_child(node, "STag").or_else(|| find_child(node, "EmptyElemTag"));
                let Some(tag) = tag else {
                    self.visit_children(node, owner, parent_name, depth + 1);
                    return;
                };
                let attrs = collect_attributes(tag, self.source);
                let key = attr(&attrs, "x:Name")
                    .or_else(|| attr(&attrs, "Name"))
                    .filter(|v| !v.is_empty());

                let (new_owner, new_parent) = match key {
                    Some(name) => {
                        // The whole element, through its end tag.
                        let sym_id = self.push_symbol(
                            name.to_string(),
                            SymbolKind::Element,
                            location(node),
                            parent_name.map(str::to_string),
                        );
                        (sym_id, Some(name.to_string()))
                    }
                    None => (owner, parent_name.map(str::to_string)),
                };

                // `<ResourceDictionary Source="Styles/Colors.xaml"/>` merges
                // another XAML file, named relative to this one.
                let tag_name = find_child(tag, "Name").map(|n| text(n, self.source));
                if tag_name.is_some_and(|n| {
                    n == "ResourceDictionary" || n.ends_with(":ResourceDictionary")
                }) {
                    if let Some((_, value, attr_node)) =
                        attrs.iter().find(|(n, _, _)| n == "Source")
                    {
                        self.push_dictionary_import(new_owner, value, location(*attr_node));
                    }
                }

                for (attr_name, value, attr_node) in &attrs {
                    if EVENT_ATTRIBUTE_NAMES.contains(&attr_name.as_str())
                        && looks_like_identifier(value)
                    {
                        self.push_relation(
                            new_owner,
                            RelationKind::References,
                            value.clone(),
                            location(*attr_node),
                        );
                    }
                }

                if let Some(content) = find_child(node, "content") {
                    self.visit_children(content, new_owner, new_parent.as_deref(), depth + 1);
                }
            }
            _ => self.visit_children(node, owner, parent_name, depth + 1),
        }
    }

    /// A merged resource dictionary depends on the `.xaml` file its relative
    /// `Source` names: an `Imports` relation to that file's `Module` symbol,
    /// pinned to its exact path. An absolute, `pack:` or `;component` URI
    /// names an assembly resource and records nothing.
    fn push_dictionary_import(&mut self, owner: SymbolId, source: &str, loc: Location) {
        if source.contains([':', ';', '{']) || source.starts_with('/') {
            return;
        }
        let Some(stem) = source
            .rsplit('/')
            .next()
            .and_then(|file| file.strip_suffix(".xaml"))
            .filter(|stem| !stem.is_empty())
        else {
            return;
        };
        let local = if source.starts_with("./") || source.starts_with("../") {
            source.to_string()
        } else {
            format!("./{source}")
        };
        let Some(resolved) = mct_core::resolve_reference_path(self.path, &local) else {
            return;
        };
        let relation = self.relations.len();
        self.push_relation(owner, RelationKind::Imports, stem.to_string(), loc);
        self.import_targets.push(RelationTarget {
            relation,
            path: Some(resolved),
            kind: Some(SymbolKind::Module),
            ..Default::default()
        });
    }

    fn finish(self) -> ParsedFile {
        ParsedFile {
            symbols: self.symbols,
            relations: self.relations,
            ..Default::default()
        }
    }
}

fn find_child<'a>(node: Node<'a>, kind: &str) -> Option<Node<'a>> {
    let mut cursor = node.walk();
    let found = node
        .named_children(&mut cursor)
        .find(|child| child.kind() == kind);
    found
}

/// `(exact-case attribute name, unquoted value, the attribute's own node)`
/// triples for an `STag`/`EmptyElemTag` — includes namespaced names
/// (`x:Name`) as one token, since that's how `tree-sitter-xml` tokenizes
/// them. The node is returned (not just the value) so a relation built from
/// it can be located at this specific attribute, not the whole tag — two
/// event attributes naming the same handler (`Click="Foo"
/// DoubleClick="Foo"`) would otherwise emit relations sharing one identical
/// location.
fn collect_attributes<'a>(tag: Node<'a>, source: &str) -> Vec<(String, String, Node<'a>)> {
    let mut out = Vec::new();
    let mut cursor = tag.walk();
    for attribute in tag.named_children(&mut cursor) {
        if attribute.kind() != "Attribute" {
            continue;
        }
        let name = find_child(attribute, "Name").map(|n| text(n, source).to_string());
        let value = find_child(attribute, "AttValue").map(|n| unquote(text(n, source)).to_string());
        if let (Some(name), Some(value)) = (name, value) {
            out.push((name, value, attribute));
        }
    }
    out
}

fn attr<'a>(attrs: &'a [(String, String, Node<'a>)], key: &str) -> Option<&'a str> {
    attrs
        .iter()
        .find(|(n, _, _)| n == key)
        .map(|(_, v, _)| v.as_str())
}

