#[test]
fn comma_separated_selectors_each_become_their_own_rule() {
    let parsed = parse(".a, .b { color: red; }");
    assert!(parsed
        .symbols
        .iter()
        .any(|s| s.name == ".a" && s.kind == SymbolKind::Rule));
