        .relations
        .iter()
        .filter(|r| r.kind == RelationKind::Imports)
        .map(|r| r.to_name.as_str())
        .collect();
    assert!(imports.contains(&"reset.css"), "{imports:?}");
}

#[test]
fn at_import_with_url_function_creates_an_import_relation() {
