#[test]
fn module_pseudo_symbol_owns_the_import_relation() {
    let parsed = parse("@import \"reset.css\";");
    let module = parsed
        .symbols
        .iter()
        .find(|s| s.kind == SymbolKind::Module)
        .unwrap();
    let import = parsed
        .relations
        .iter()
        .find(|r| r.kind == RelationKind::Imports)
        .unwrap();
