/// F02 / issue #97: a callee is listed as a related symbol only when its
/// definition is proven. Same-named methods in other languages (C# `Ok`, PHP
/// `get`, C++ `map`) are never it, `A::run` is never `B::run`, and a bare
/// `x.run()` is reported as ambiguous instead of picking one.
#[tokio::test]
async fn homonyms_are_never_presented_as_resolved_callees() {
    let root = std::env::temp_dir().join(format!("mct-qualified-pack-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(root.join("src")).unwrap();
    let files = [
        (
            "src/lib.rs",
            "pub struct A;\n\
             impl A {\n    pub fn run() {}\n}\n\
             pub struct B;\n\
             impl B {\n    pub fn run(&self) {}\n}\n\
             pub fn query(v: Vec<u8>, b: B) -> Result<u8, ()> {\n\
             \x20   A::run();\n\
             \x20   b.run();\n\
             \x20   let _ = v.get(0);\n\
             \x20   let _ = v.iter().map(|x| x);\n\
             \x20   Ok(1)\n\
             }\n",
        ),
        (
            "Errors.cs",
            "public class Result {\n    public static Result Ok(int v) => null;\n}\n",
        ),
        (
            "Repository.php",
            "<?php\nclass Repository {\n    public function get(int $id) { return $id; }\n}\n",
        ),
        (
            "service.cpp",
            "struct Box {\n    int map(int x) const { return x; }\n};\n",
        ),
    ];
    for (path, contents) in files {
        std::fs::write(root.join(path), contents).unwrap();
    }
    let server = build_server(&root).await;
    let text = pack(&server, json!({ "symbol": "query", "format": "text" })).await;
    let _ = std::fs::remove_dir_all(&root);
    println!("{text}");

    let related: Vec<&str> = text
        .lines()
        .skip_while(|l| !l.starts_with("Related symbols"))
        .skip(1)
        .take_while(|l| l.starts_with("  "))
        .collect();
    assert_eq!(
        related,
        vec!["  callee run  src/lib.rs:L3 method  | pub fn run() {}"],
        "{text}"
    );
    for foreign in ["Errors.cs", "Repository.php", "service.cpp"] {
        assert!(!text.contains(foreign), "{foreign} leaked in:\n{text}");
    }
    assert!(
        text.contains(
            "Uncertain relations — target not proven, none picked, not followed:\n  \
             callee run  ambiguous among 2: src/lib.rs:L3 method, src/lib.rs:L7 method\n"
        ),
        "{text}"
    );
    assert!(
        text.contains(
            "Unresolved (no indexed definition, no external evidence): Ok, get, iter, map"
        ),
        "{text}"
    );
}

//! Tool-preselection evaluation for issue #19 over the held-out set in
//! `fixtures/intent_eval.toon` (scoring defined in
//! `benchmarks/intent-selection.md`, committed before the rules existed).
//!
//! `rules_beat_the_full_catalog` runs in the normal suite with no model.
//! `embeddings_compared` needs the local embedding model:
//! `cargo test -p mct-mcp-server --features semantic --test intent_eval -- --ignored --nocapture`.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;
use std::time::{Duration, Instant};

use mct_index::{ExcludeSet, Index};
use mct_mcp_server::cache::CacheConfig;
use mct_mcp_server::intent::{self, Source, ToolVectors};
use mct_mcp_server::server::{MctServer, ServerOptions};
use mct_mcp_server::toon::decode_table;
use rmcp::model::Tool;

struct Case {
    id: String,
    query: String,
    /// Required groups; each group is a set of acceptable tools.
    need: Vec<Vec<String>>,
    forbid: Vec<String>,
}

fn cases() -> Vec<Case> {
    let table = decode_table(include_str!("fixtures/intent_eval.toon")).unwrap();
    assert_eq!(table.headers, ["id", "category", "query", "need", "forbid"]);
    table
        .rows
        .into_iter()
        .map(|row| {
            let split = |s: &str, sep: char| -> Vec<String> {
                s.split(sep)
                    .filter(|p| !p.is_empty())
                    .map(str::to_string)
                    .collect()
            };
            Case {
                id: row[0].clone(),
                query: row[2].clone(),
                need: split(&row[3], ';').iter().map(|g| split(g, '|')).collect(),
                forbid: split(row.get(4).map_or("", String::as_str), '|'),
            }
        })
        .collect()
}

fn catalog_and_languages() -> (Vec<Tool>, Vec<&'static str>) {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let registry = mct_mcp_server::registry::build_registry();
    let languages = registry.language_ids();
    let index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();
    (MctServer::new(index, registry).tool_catalog(), languages)
}

/// Same heuristic as `mct_eval::approx_tokens` / `tests/batch.rs`: a run of
/// alphanumerics/`_` is one token, every other non-whitespace char is one.
/// Approximate — no model tokenizer is a dependency of this workspace.
fn approx_tokens(s: &str) -> usize {
    let mut tokens = 0usize;
    let mut in_word = false;
    for c in s.chars() {
        if c.is_alphanumeric() || c == '_' {
            if !in_word {
                tokens += 1;
                in_word = true;
            }
        } else {
            in_word = false;
            if !c.is_whitespace() {
                tokens += 1;
            }
        }
    }
    tokens
}

/// What one selector delivers for one query.
struct Delivery {
    tools: Vec<String>,
    /// Whether `tools` is ordered best-first (top-1 is meaningful).
    ordered: bool,
    fallback: bool,
    intent_line: String,
}

#[derive(Default)]
struct Score {
    top1_hits: usize,
    top1_cases: usize,
    groups_hit: usize,
    groups: usize,
    precision_sum: f64,
    precision_cases: usize,
    no_selection_ok: usize,
    no_selection_cases: usize,
    forbidden: usize,
    fallbacks: usize,
    tokens: usize,
    bytes: usize,
    cases: usize,
    elapsed: Duration,
    misses: Vec<String>,
}

impl Score {
    fn top1(&self) -> Option<f64> {
        (self.top1_cases > 0).then(|| self.top1_hits as f64 / self.top1_cases as f64)
    }
    fn recall(&self) -> f64 {
        self.groups_hit as f64 / self.groups.max(1) as f64
    }
    fn precision(&self) -> f64 {
        self.precision_sum / self.precision_cases.max(1) as f64
    }
    fn row(&self, name: &str) -> String {
        let top1 = self
            .top1()
            .map_or("n/a".to_string(), |v| format!("{:.3}", v));
        format!(
            "  {name},{top1},{:.3},{:.3},{}/{},{},{},{},{},{:.3}",
            self.recall(),
            self.precision(),
            self.no_selection_ok,
            self.no_selection_cases,
            self.forbidden,
            self.fallbacks,
            self.tokens,
            self.bytes,
            self.elapsed.as_secs_f64() * 1000.0 / self.cases.max(1) as f64,
        )
    }
}

fn score(cases: &[Case], catalog: &[Tool], mut select: impl FnMut(&str) -> Delivery) -> Score {
    let mut s = Score::default();
    for case in cases {
        let started = Instant::now();
        let d = select(&case.query);
        s.elapsed += started.elapsed();
        s.cases += 1;

        let entries: Vec<&Tool> = d
            .tools
            .iter()
            .filter_map(|n| catalog.iter().find(|t| t.name == n.as_str()))
            .collect();
        let payload = format!(
            "{}\n{}\n{}",
            case.query,
            d.intent_line,
            serde_json::to_string(&entries).unwrap()
        );
        s.tokens += approx_tokens(&payload);
        s.bytes += payload.len();
        if d.fallback {
            s.fallbacks += 1;
        }
        if case.forbid.iter().any(|f| d.tools.contains(f)) {
            s.forbidden += 1;
        }
        if case.need.is_empty() {
            s.no_selection_cases += 1;
            if d.fallback {
                s.no_selection_ok += 1;
            } else {
                s.misses.push(format!("{}: guessed {:?}", case.id, d.tools));
            }
            continue;
        }
        let wanted = |t: &String| case.need.iter().any(|g| g.contains(t));
        for group in &case.need {
            s.groups += 1;
            if group.iter().any(|t| d.tools.contains(t)) {
                s.groups_hit += 1;
            } else {
                s.misses
                    .push(format!("{}: missing {:?} in {:?}", case.id, group, d.tools));
            }
        }
        let useful = d.tools.iter().filter(|t| wanted(t)).count();
        s.precision_sum += useful as f64 / d.tools.len().max(1) as f64;
        s.precision_cases += 1;
        if d.ordered {
            s.top1_cases += 1;
            if d.tools.first().is_some_and(wanted) {
                s.top1_hits += 1;
            } else {
                s.misses
                    .push(format!("{}: top-1 {:?}", case.id, d.tools.first()));
            }
        }
    }
    s
}

fn full_catalog(catalog: &[Tool]) -> impl FnMut(&str) -> Delivery + '_ {
    |_| Delivery {
        tools: catalog.iter().map(|t| t.name.to_string()).collect(),
        ordered: false,
        fallback: true,
        intent_line: String::new(),
    }
}

fn preselected<'a>(
    catalog: &'a [Tool],
    languages: &'a [&'static str],
    vectors: Option<&'a ToolVectors<'a>>,
) -> impl FnMut(&str) -> Delivery + 'a {
    move |q| {
        let p = intent::preselect(q, languages, catalog, vectors);
        Delivery {
            ordered: p.source != Source::Fallback,
            fallback: p.source == Source::Fallback,
            intent_line: p.intent.render(p.source),
            tools: p.tools,
        }
    }
}

const HEADER: &str =
    "selectors[{n}]{selector,top1,recall,precision,no_selection_ok,forbidden_delivered,fallbacks,approx_tokens,bytes,ms_per_query}:";

fn print_report(cases: &[Case], rows: &[(&str, &Score)]) {
    println!("{} held-out cases", cases.len());
    println!("{}", HEADER.replace("{n}", &rows.len().to_string()));
    for (name, s) in rows {
        println!("{}", s.row(name));
    }
    for (name, s) in rows {
        for miss in &s.misses {
            println!("  miss[{name}] {miss}");
        }
    }
}

#[tokio::test]
async fn rules_beat_the_full_catalog() {
    let cases = cases();
    let (catalog, languages) = catalog_and_languages();
    let baseline = score(&cases, &catalog, full_catalog(&catalog));
    let rules = score(&cases, &catalog, preselected(&catalog, &languages, None));
    print_report(&cases, &[("full_catalog", &baseline), ("rules", &rules)]);

    // Issue #19's acceptance criteria, against today's flow.
    assert!(rules.tokens < baseline.tokens, "fewer prompt tokens");
    assert!(
        rules.precision() > baseline.precision(),
        "a more precise tool selection"
    );
    assert_eq!(rules.forbidden, 0, "a negated tool was delivered");
    // Regression guards at the measured values (see benchmarks/intent-selection.md);
    // they record today's result, they are not targets.
    assert!(rules.recall() >= RECALL_GUARD, "recall {}", rules.recall());
    assert!(
        rules.top1().unwrap_or(0.0) >= TOP1_GUARD,
        "top-1 {:?}",
        rules.top1()
    );
}

fn names(tools: &[Tool]) -> Vec<String> {
    tools.iter().map(|t| t.name.to_string()).collect()
}

/// Issue #11, integrated: what `tools/list` carries per turn with Tool
/// Attention on, against the full catalog every client gets today.
#[tokio::test]
async fn tool_attention_narrows_tools_list() {
    let cases = cases();
    let (full, _) = catalog_and_languages();
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let server = MctServer::with_options(
        Index::open_in_memory(&root, ExcludeSet::default()).unwrap(),
        mct_mcp_server::registry::build_registry(),
        ServerOptions {
            cache: CacheConfig::disabled(),
            embedder: None,
            shared_cache: None,
            tool_attention: true,
        },
    );
    let tokens = |tools: &[Tool]| approx_tokens(&serde_json::to_string(tools).unwrap());

    // Off (the default): no select_tools, and nothing else changes.
    assert!(!names(&full).contains(&"select_tools".to_string()));
    let mut on = names(&server.tool_catalog());
    on.retain(|n| n != "select_tools");
    assert_eq!(on, names(&full), "attention changes only select_tools");

    let full_tokens = tokens(&full);
    let initial = server.advertised_tools();
    assert_eq!(names(&initial), ["select_tools"]);

    let (mut turn_tokens, mut groups, mut hit, mut oracle_tokens) = (0, 0, 0, 0);
    let mut fallbacks = Vec::new();
    for case in &cases {
        // Lower bound for any selector with full recall: `select_tools` plus
        // the cheapest acceptable tool of each required group.
        let mut oracle = initial.clone();
        for group in &case.need {
            let cheapest = full
                .iter()
                .filter(|t| group.iter().any(|n| n == t.name.as_ref()))
                .min_by_key(|t| tokens(std::slice::from_ref(*t)))
                .unwrap();
            if !oracle.iter().any(|t| t.name == cheapest.name) {
                oracle.push(cheapest.clone());
            }
        }
        oracle_tokens += tokens(&oracle);

        server.attend(&case.query).await.unwrap();
        let listed = server.advertised_tools();
        let listed_names = names(&listed);
        turn_tokens += tokens(&listed);
        if listed.len() == full.len() + 1 {
            fallbacks.push(case.id.as_str());
        }
        assert!(
            !case.forbid.iter().any(|f| listed_names.contains(f)),
            "{}: a negated tool was listed",
            case.id
        );
        for group in &case.need {
            groups += 1;
            if group.iter().any(|t| listed_names.contains(t)) {
                hit += 1;
            }
        }
    }
    let per_turn = turn_tokens as f64 / cases.len() as f64;
    let oracle = oracle_tokens as f64 / cases.len() as f64;
    let reduction = |t: f64| 1.0 - t / full_tokens as f64;
    let recall = hit as f64 / groups.max(1) as f64;
    println!(
        "attention[4]{{list,approx_tokens,reduction}}:\n  full_catalog,{full_tokens},0.000\n  \
         initial,{},{:.3}\n  per_turn_mean,{per_turn:.1},{:.3}\n  oracle_mean,{oracle:.1},{:.3}\n\
         recall {recall:.3} ({hit}/{groups}), fallbacks {}/{} {fallbacks:?}",
        tokens(&initial),
        reduction(tokens(&initial) as f64),
        reduction(per_turn),
        reduction(oracle),
        fallbacks.len(),
        cases.len()
    );
    assert!(
        reduction(tokens(&initial) as f64) >= 0.90,
        "#11's 90% target"
    );
    assert!(
        reduction(per_turn) >= ATTENTION_TURN_GUARD,
        "per-turn reduction"
    );
    assert!(recall >= RECALL_GUARD, "recall {recall}");

    let off = MctServer::new(
        Index::open_in_memory(&root, ExcludeSet::default()).unwrap(),
        mct_mcp_server::registry::build_registry(),
    );
    assert!(off.attend("who calls parse").await.is_err());
    // Off, `batch` treats it as any unknown name.
    let args = serde_json::from_value(serde_json::json!({"queries": [{"tool": "select_tools"}]}));
    let reply = off
        .batch(rmcp::handler::server::wrapper::Parameters(args.unwrap()))
        .await
        .unwrap();
    assert!(format!("{:?}", reply.content).contains("no tool named `select_tools`"));
    assert!(server.attend("   ").await.is_err());
}

/// Regression guard at the first measured value (see
/// benchmarks/intent-selection.md): 0.753 (0.754 before #17's annotations),
/// held down by the 6/42 fallbacks that list the full catalog. The
/// full-recall floor (`oracle_mean`) is 0.915.
const ATTENTION_TURN_GUARD: f64 = 0.75;

/// First held-out measurement: recall 42/42 groups, top-1 33/34.
const RECALL_GUARD: f64 = 1.0;
const TOP1_GUARD: f64 = 0.97;

/// Development queries for the embedding thresholds — never the eval set.
/// `true`: a code question the rules miss; `false`: no reliable selection.
const DEV_EMBEDDING_QUERIES: &[(&str, bool)] = &[
    ("how is a json-rpc request turned into a response", true),
    ("what happens when a parser hits a syntax error", true),
    ("which part handles file watching", true),
    ("how are embeddings stored", true),
    ("thanks a lot", false),
    ("good morning", false),
    ("tell me a joke", false),
    ("speed up the build please", false),
    ("ok continue", false),
];

#[tokio::test]
#[ignore = "not a bug: needs the local embedding model; run with --features semantic -- --ignored"]
async fn embeddings_compared() {
    let cases = cases();
    let (catalog, languages) = catalog_and_languages();
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let model = mct_mcp_server::embedder::SemanticModel::default();
    let embedder = model.get(&root).unwrap();
    let started = Instant::now();
    let vectors = ToolVectors::new(embedder, &catalog).unwrap();
    println!(
        "embedded {} tool descriptions with {} in {:?} (one-off)",
        catalog.len(),
        embedder.model_id(),
        started.elapsed()
    );

    for (q, code) in DEV_EMBEDDING_QUERIES {
        let ranked = vectors.rank(q).unwrap();
        let top: Vec<String> = ranked
            .iter()
            .take(3)
            .map(|(n, s)| format!("{n}={s:.3}"))
            .collect();
        println!("  dev[{code}] {q}: {}", top.join(" "));
    }

    let baseline = score(&cases, &catalog, full_catalog(&catalog));
    let rules = score(&cases, &catalog, preselected(&catalog, &languages, None));
    let hybrid = score(
        &cases,
        &catalog,
        preselected(&catalog, &languages, Some(&vectors)),
    );
    let embedding_top3 = score(&cases, &catalog, |q| Delivery {
        tools: vectors
            .rank(q)
            .unwrap()
            .into_iter()
            .take(3)
            .map(|(n, _)| n)
            .collect(),
        ordered: true,
        fallback: false,
        intent_line: String::new(),
    });
    print_report(
        &cases,
        &[
            ("full_catalog", &baseline),
            ("rules", &rules),
            ("rules+embeddings", &hybrid),
            ("embedding_top3", &embedding_top3),
        ],
    );
}

