//! File-level `Imports` evidence: each cross-file `use`/`mod` names its
//! target and carries enough evidence to resolve to the right file.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;
use std::sync::Arc;

use mct_core::{LanguageParser, LanguageRegistry, RelationKind, SourceFile, SymbolKind};
use mct_index::{ExcludeSet, Index, Resolution};
use mct_lang_rust::RustParser;

fn parse(path: &str, src: &str) -> mct_core::ParsedFile {
    RustParser
        .parse(&SourceFile {
            relative_path: path.to_string(),
            contents: src.to_string(),
        })
        .unwrap()
}

fn open_indexed() -> Index {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/depgraph");
    let mut registry = LanguageRegistry::new();
    registry.register(Arc::new(RustParser));
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();
    let report = index.reindex(&registry, false).unwrap();
    assert!(report.issues.is_empty(), "{:?}", report.issues);
    index
}

/// What the `imports` relation named `to` from `from_file` resolved to.
fn import_hit(index: &Index, to: &str, from_file: &str) -> (Resolution, Option<String>) {
    let hit = index
        .find_references(to)
        .unwrap()
        .into_iter()
        .find(|h| h.kind == "imports" && h.relative_path == from_file && h.to_name == to)
        .unwrap_or_else(|| panic!("no import {to} in {from_file}"));
    let file = hit.candidates.first().map(|c| c.relative_path.clone());
    (hit.resolution, file)
}

#[test]
fn mod_declarations_and_use_paths_resolve_to_the_target_file() {
    let index = open_indexed();
    // `mod util;` and `mod config;` pull in the sibling files.
    assert_eq!(
        import_hit(&index, "util", "src/lib.rs"),
        (Resolution::Resolved, Some("src/util.rs".to_string()))
    );
    assert_eq!(
        import_hit(&index, "config", "src/lib.rs"),
        (Resolution::Resolved, Some("src/config.rs".to_string()))
    );
    // `use crate::util::helper` must not pick `other.rs`'s `helper`.
    assert_eq!(
        import_hit(&index, "helper", "src/lib.rs"),
        (Resolution::Resolved, Some("src/util.rs".to_string()))
    );
    assert_eq!(
        import_hit(&index, "Settings", "src/util.rs"),
        (Resolution::Resolved, Some("src/config.rs".to_string()))
    );
}

#[test]
fn third_party_and_std_uses_never_resolve_to_a_local_namesake() {
    let index = open_indexed();
    // `other.rs` defines a `Serialize`, but `use serde::Serialize` names
    // the `serde` module.
    let (resolution, _) = import_hit(&index, "Serialize", "src/lib.rs");
    assert_ne!(resolution, Resolution::Resolved);
    let (resolution, _) = import_hit(&index, "Display", "src/lib.rs");
    assert_eq!(resolution, Resolution::External);
}

#[test]
fn mod_declaration_carries_module_evidence() {
    let parsed = parse(
        "src/lib.rs",
        "mod util;\nmod inline { fn f() {} }\nuse a::b::C;\n",
    );
    let target = |name: &str| {
        let (i, _) = parsed
            .relations
            .iter()
            .enumerate()
            .find(|(_, r)| r.kind == RelationKind::Imports && r.to_name == name)
            .unwrap_or_else(|| panic!("no import {name}"));
        parsed
            .relation_targets
            .iter()
            .find(|t| t.relation == i)
            .cloned()
    };
    let util = target("util").unwrap();
    assert_eq!(util.module.as_deref(), Some("util"));
    assert_eq!(util.kind, Some(SymbolKind::Module));
    // An inline `mod inline { … }` imports nothing.
    assert!(!parsed
        .relations
        .iter()
        .any(|r| r.to_name == "inline" && r.kind == RelationKind::Imports));
    // `use a::b::C`: `C` is a type, so `b` is the module and `C` a plain name.
    assert_eq!(target("C").unwrap().module.as_deref(), Some("b"));
}

//! Measures token cost of three canonical queries — "find the definition of
//! X", "what calls this function", "who uses this symbol" — answered via
//! the MCP-style index query versus the realistic Read/Grep/Glob baseline
//! (grep the exact term across the repo, then Read each file grep matched,
//! in full — which is what an agent without semantic navigation actually
//! does; grep alone rarely gives enough context to stop there).
//!
//! Character counts are exact; the "approx. tokens" column is chars/4, a
//! standard rough English/code heuristic — not a real tokenizer run, but
//! good enough to see the order of magnitude of the reduction.
//!
//! Usage: cargo run -p mct-cli --example token_benchmark

// Example code: an unwrap()/expect() here means a broken precondition of
// this benchmark script, and panicking is the correct behavior — this is not
// production code parsing untrusted repo content (see crates/mct-cli/src/
// for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::Path;
use std::sync::Arc;

use mct_core::LanguageRegistry;
use mct_index::{ExcludeSet, Index};

struct Query {
    label: &'static str,
    kind: QueryKind,
    term: &'static str,
}

enum QueryKind {
    Symbol,
    Callers,
    References,
}

fn mcp_chars(index: &Index, query: &Query) -> (usize, String) {
    let text = match query.kind {
        QueryKind::Symbol => {
            let hits = index.find_symbol(query.term).unwrap();
            hits.iter()
                .map(|h| {
                    format!(
                        "{}:{}:{} [{}] {} {}\n",
                        h.relative_path, h.line, h.column, h.language, h.kind, h.name
                    )
                })
                .collect::<String>()
        }
        QueryKind::Callers => {
            let hits = index.find_callers(query.term).unwrap();
            hits.iter()
                .map(|h| {
                    format!(
                        "{}:{}:{} [{}] {} --{}--> {}\n",
                        h.relative_path,
                        h.line,
                        h.column,
                        h.language,
                        h.from_symbol,
                        h.kind,
                        h.to_name
                    )
                })
                .collect::<String>()
        }
        QueryKind::References => {
            let hits = index.find_references(query.term).unwrap();
            hits.iter()
                .map(|h| {
                    format!(
                        "{}:{}:{} [{}] {} --{}--> {}\n",
                        h.relative_path,
                        h.line,
                        h.column,
                        h.language,
                        h.from_symbol,
                        h.kind,
                        h.to_name
                    )
                })
                .collect::<String>()
        }
    };
    (text.chars().count(), text)
}

/// grep the exact term across every file in `root`, then Read (in full)
/// each distinct file that matched — the realistic Read/Grep/Glob baseline.
fn grep_then_read_chars(root: &Path, term: &str) -> (usize, usize, usize) {
    let mut grep_output = String::new();
    let mut matched_files: Vec<std::path::PathBuf> = Vec::new();

    for entry in walkdir_files(root) {
        let contents = fs::read_to_string(&entry).unwrap_or_default();
        let mut matched = false;
        for (i, line) in contents.lines().enumerate() {
            if line.contains(term) {
                grep_output.push_str(&format!("{}:{}:{}\n", entry.display(), i + 1, line));
                matched = true;
            }
        }
        if matched {
            matched_files.push(entry);
        }
    }

    let read_chars: usize = matched_files
        .iter()
        .map(|f| fs::read_to_string(f).unwrap_or_default().chars().count())
        .sum();

    let grep_chars = grep_output.chars().count();
    (grep_chars, read_chars, matched_files.len())
}

fn walkdir_files(root: &Path) -> Vec<std::path::PathBuf> {
    let mut out = Vec::new();
    for entry in walkdir::WalkDir::new(root)
        .into_iter()
        .filter_map(|e| e.ok())
    {
        if entry.file_type().is_file() {
            out.push(entry.path().to_path_buf());
        }
    }
    out
}

fn run_language(name: &str, root: &Path, registry: LanguageRegistry, queries: &[Query]) {
    let mut index = Index::open_in_memory(root, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();

    println!("\n## {name}\n");
    println!(
        "| Query | MCP chars | MCP ~tokens | Grep+Read chars | Grep+Read ~tokens | Reduction |"
    );
    println!("|---|---|---|---|---|---|");
    for query in queries {
        let (mcp_c, _) = mcp_chars(&index, query);
        let (grep_c, read_c, files) = grep_then_read_chars(root, query.term);
        let baseline_c = grep_c + read_c;
        let reduction = if baseline_c > 0 {
            100.0 * (1.0 - mcp_c as f64 / baseline_c as f64)
        } else {
            0.0
        };
        println!(
            "| {} (`{}`) | {} | ~{} | {} (grep {} + read {} across {} file(s)) | ~{} | {:.1}% |",
            query.label,
            query.term,
            mcp_c,
            mcp_c / 4,
            baseline_c,
            grep_c,
            read_c,
            files,
            baseline_c / 4,
            reduction
        );
    }
}

fn main() {
    let java_root =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../mct-lang-java/tests/fixtures/billing-app");
    let mut java_registry = LanguageRegistry::new();
    java_registry.register(Arc::new(mct_lang_java::JavaParser));
    run_language(
