    pub shared_cache: Option<Arc<std::sync::Mutex<QueryCache>>>,
    /// Tool Attention (issue #11): `tools/list` starts with `select_tools`
    /// only and is narrowed per request. Off: the full catalog, no
    /// `select_tools`.
    pub tool_attention: bool,
