//! What `Index::change_marker` covers, before anything relies on it to detect
//! an index that changed between two pages of results: it must move on every
//! symbol, relation and file addition, edit and removal, and stay put when a
//! reindex finds nothing to do. It is a database-level, conservative marker:
//! it may move for writes that do not affect a given result.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

use mct_core::{
    Location, ParseError, ParsedFile, RelationKind, SourceFile, SymbolKind, SymbolRecord,
    SymbolRelation,
};
use mct_index::{ExcludeSet, Index};

/// Each line is `NAME` or `NAME calls OTHER`.
struct FakeParser;

impl mct_core::LanguageParser for FakeParser {
    fn language_id(&self) -> &'static str {
        "fake"
    }

    fn file_extensions(&self) -> &'static [&'static str] {
        &["fake"]
    }

    fn parse(&self, file: &SourceFile) -> Result<ParsedFile, ParseError> {
        let mut parsed = ParsedFile::default();
        for (n, line) in file.contents.lines().enumerate() {
            let mut parts = line.split_whitespace();
            let Some(name) = parts.next() else { continue };
            let location = Location {
                line: n as u32 + 1,
                column: 1,
                byte_len: line.len() as u32,
                end_line: Some(n as u32 + 1),
            };
            let id = parsed.symbols.len() as u32;
            parsed.symbols.push(SymbolRecord {
                id,
                name: name.to_string(),
                kind: SymbolKind::Function,
                location,
                parent: None,
                level: None,
            });
            if let (Some("calls"), Some(callee)) = (parts.next(), parts.next()) {
                parsed.relations.push(SymbolRelation {
                    from: id,
                    kind: RelationKind::Calls,
                    to_name: callee.to_string(),
                    location,
                });
            }
        }
        Ok(parsed)
    }
}

fn registry() -> mct_core::LanguageRegistry {
    let mut registry = mct_core::LanguageRegistry::new();
    registry.register(Arc::new(FakeParser));
    registry
}

fn project() -> (PathBuf, Index) {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let dir = std::env::temp_dir().join(format!(
        "mct-change-marker-{}-{}",
        std::process::id(),
        COUNTER.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    let dir = dir.canonicalize().unwrap();
    fs::write(dir.join("a.fake"), "one calls two\ntwo\n").unwrap();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
    index.reindex(&registry(), false).unwrap();
    (dir, index)
}

#[test]
fn the_marker_is_stable_between_reads_and_conservative_on_a_no_op_reindex() {
    let (dir, mut index) = project();
    let before = index.change_marker().unwrap();
    assert_eq!(
        index.change_marker().unwrap(),
        before,
        "reads never move it"
    );
    let symbols = index.find_symbol("one").unwrap();
    assert_eq!(
        index.change_marker().unwrap(),
        before,
        "queries never move it"
    );
    index.reindex(&registry(), false).unwrap();
    // Measured: a reindex that skips every file still writes bookkeeping
    // (run metadata), so the marker may move without any symbol changing.
    // That is a false positive, never a false negative; the result is the same.
    assert_eq!(index.find_symbol("one").unwrap().len(), symbols.len());
    fs::remove_dir_all(dir).unwrap();
}

#[test]
fn the_marker_moves_on_edit_addition_relation_change_and_removal() {
    let (dir, mut index) = project();
    let mut last = index.change_marker().unwrap();
    let mut step = |index: &mut Index, what: &str| {
        index.reindex(&registry(), false).unwrap();
        let now = index.change_marker().unwrap();
        assert_ne!(now, last, "marker must move after: {what}");
        last = now;
    };

    fs::write(dir.join("a.fake"), "one calls two\ntwo\nthree\n").unwrap();
    step(&mut index, "a symbol was added to a file");
    assert!(!index.find_symbol("three").unwrap().is_empty());

    fs::write(dir.join("a.fake"), "one calls three\ntwo\nthree\n").unwrap();
    step(&mut index, "only a relation target changed");
    assert_eq!(index.find_callers("three").unwrap().len(), 1);

    fs::write(dir.join("b.fake"), "extra\n").unwrap();
    step(&mut index, "a file was added");

    fs::remove_file(dir.join("b.fake")).unwrap();
    step(&mut index, "a file was removed");
    assert!(index.find_symbol("extra").unwrap().is_empty());
    fs::remove_dir_all(dir).unwrap();
}

sources.crates/mct-index/tests/exclude_reload.rs:
//! An `ExcludeSet::for_project` picks up edits to `.mctignore` (and to an
//! imported `.gitignore`) without reopening the index: a rule added later
//! drops the file's symbols and relations, a rule removed later brings it
//! back — through a full reindex (forced or not) or through `reindex_paths`
//! of the edited ignore file, which is all a watcher reports.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-index/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

use mct_core::{
    Location, ParseError, ParsedFile, RelationKind, SourceFile, SymbolKind, SymbolRecord,
    SymbolRelation,
};
use mct_index::{ExcludeSet, Index, IGNORE_FILE_NAME};

/// Toy format: each line is `NAME` or `NAME calls OTHER`.
struct FakeParser;

impl mct_core::LanguageParser for FakeParser {
    fn language_id(&self) -> &'static str {
        "fake"
    }

    fn file_extensions(&self) -> &'static [&'static str] {
        &["fake"]
    }

    fn parse(&self, file: &SourceFile) -> Result<ParsedFile, ParseError> {
        let mut parsed = ParsedFile::default();
        for (line_no, line) in file.contents.lines().enumerate() {
            let mut parts = line.split_whitespace();
            let Some(name) = parts.next() else { continue };
            let location = Location {
                line: line_no as u32 + 1,
                column: 1,
                byte_len: line.len() as u32,
                end_line: Some(line_no as u32 + 1),
            };
            let id = parsed.symbols.len() as u32;
            parsed.symbols.push(SymbolRecord {
                id,
                name: name.to_string(),
                kind: SymbolKind::Function,
                location,
                parent: None,
                level: None,
            });
            if let (Some("calls"), Some(callee)) = (parts.next(), parts.next()) {
                parsed.relations.push(SymbolRelation {
                    from: id,
                    kind: RelationKind::Calls,
                    to_name: callee.to_string(),
                    location,
                });
            }
        }
        Ok(parsed)
    }
}

fn registry() -> mct_core::LanguageRegistry {
    let mut registry = mct_core::LanguageRegistry::new();
    registry.register(Arc::new(FakeParser));
    registry
}

fn tempdir() -> PathBuf {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let dir = std::env::temp_dir().join(format!(
        "mct-exclude-reload-{}-{}",
        std::process::id(),
        COUNTER.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    dir.canonicalize().unwrap()
}

/// A project with `hidden.fake` (whose symbol calls `helper`) and
/// `keep.fake` (defining `helper`), indexed with the project's own rules.
fn project() -> (PathBuf, Index) {
    let dir = tempdir();
    fs::write(
        dir.join("hidden.fake"),
        "audit_hidden_symbol calls helper\n",
    )
    .unwrap();
    fs::write(dir.join("keep.fake"), "helper\n").unwrap();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::for_project(&dir)).unwrap();
    index.reindex(&registry(), false).unwrap();
    assert!(is_indexed(&index));
    (dir, index)
}

/// Whether `hidden.fake`'s symbol and its call to `helper` are indexed.
fn is_indexed(index: &Index) -> bool {
    let symbol = !index.find_symbol("audit_hidden_symbol").unwrap().is_empty();
    let relation = !index.find_callers("helper").unwrap().is_empty();
    assert_eq!(symbol, relation, "symbol and relation must go together");
    symbol
}

fn write_rules(dir: &Path, contents: &str) -> PathBuf {
    let path = dir.join(IGNORE_FILE_NAME);
    fs::write(&path, contents).unwrap();
    path
}

#[test]
fn a_forced_reindex_applies_a_rule_added_after_opening() {
    let (dir, mut index) = project();

    write_rules(&dir, "hidden.fake\n");
    index.reindex(&registry(), true).unwrap();
    assert!(!is_indexed(&index), "a new rule must drop the file");
    assert_eq!(index.find_symbol("helper").unwrap().len(), 1);

    fs::remove_file(dir.join(IGNORE_FILE_NAME)).unwrap();
    index.reindex(&registry(), false).unwrap();
    assert!(
        is_indexed(&index),
        "a removed rule must bring the file back"
    );
}

#[test]
fn reindexing_just_the_edited_ignore_file_applies_its_rules_everywhere() {
    let (dir, mut index) = project();

    let rules = write_rules(&dir, "hidden.fake\n");
    index
        .reindex_paths(&registry(), std::slice::from_ref(&rules))
        .unwrap();
    assert!(!is_indexed(&index));

    // Un-excluding reports no event for `hidden.fake` itself: only the
    // ignore file changed, and that must be enough.
    write_rules(&dir, "# nothing excluded\n");
    index.reindex_paths(&registry(), &[rules]).unwrap();
    assert!(is_indexed(&index));
}

#[test]
fn an_imported_gitignore_edit_applies_too() {
    let (dir, mut index) = project();
    let rules = write_rules(&dir, "@import-gitignore\n");
    index.reindex_paths(&registry(), &[rules]).unwrap();
    assert!(is_indexed(&index), "an empty import excludes nothing");

    let gitignore = dir.join(".gitignore");
    fs::write(&gitignore, "hidden.fake\n").unwrap();
    index
        .reindex_paths(&registry(), std::slice::from_ref(&gitignore))
        .unwrap();
    assert!(!is_indexed(&index));

    fs::write(&gitignore, "").unwrap();
    index.reindex_paths(&registry(), &[gitignore]).unwrap();
    assert!(is_indexed(&index));
}

#[test]
fn an_ordinary_change_stays_incremental() {
    let (dir, mut index) = project();
    write_rules(&dir, "# unrelated comment\n");
    let keep = dir.join("keep.fake");
    fs::write(&keep, "helper\nextra\n").unwrap();

    let report = index
        .reindex_paths(&registry(), &[keep, dir.join(IGNORE_FILE_NAME)])
        .unwrap();
    assert_eq!(report.files_parsed, 1);
    // A full walk would have hash-checked `hidden.fake` too.
    assert_eq!(report.files_unchanged, 0);
    assert!(is_indexed(&index));
}

#[test]
fn applying_exclusion_changes_sweeps_a_new_rule_before_any_reindex() {
    let (dir, mut index) = project();
    assert!(
        !index.apply_exclusion_changes(&registry()).unwrap(),
        "unchanged rules need no sweep"
    );

    write_rules(&dir, "hidden.fake\n");
    assert!(index.apply_exclusion_changes(&registry()).unwrap());
    assert!(!is_indexed(&index), "a new rule must drop the file at once");
    assert_eq!(index.find_symbol("helper").unwrap().len(), 1);
    assert!(
        !index.apply_exclusion_changes(&registry()).unwrap(),
        "an applied rule is not applied twice"
    );

    write_rules(&dir, "# nothing excluded\n");
    assert!(index.apply_exclusion_changes(&registry()).unwrap());
    assert!(
        is_indexed(&index),
        "a removed rule must bring the file back"
    );
}

/// The watcher reloads its clone of the rules before it takes the index to
/// reindex. A query in between must not take the swapped-in rules for
/// already applied: the stored rows still predate them.
#[test]
fn rules_reloaded_through_another_clone_are_still_swept() {
    let dir = tempdir();
    fs::write(
        dir.join("hidden.fake"),
        "audit_hidden_symbol calls helper\n",
    )
    .unwrap();
    fs::write(dir.join("keep.fake"), "helper\n").unwrap();
    let exclude = ExcludeSet::for_project(&dir);
    let watcher_rules = exclude.clone();
    let mut index = Index::open_in_memory(&dir, exclude).unwrap();
    index.reindex(&registry(), false).unwrap();

    write_rules(&dir, "hidden.fake\n");
    assert!(watcher_rules.reload());
    assert!(is_indexed(&index), "nothing has swept the rows yet");

    assert!(index.apply_exclusion_changes(&registry()).unwrap());
    assert!(!is_indexed(&index));
}

#[test]
fn a_fixed_set_never_reloads_and_clones_share_reloaded_rules() {
    let dir = tempdir();
    write_rules(&dir, "hidden.fake\n");

    let fixed = ExcludeSet::new(&[]);
    assert!(!fixed.reload());
    assert!(!fixed.is_excluded("hidden.fake"));

    let project = ExcludeSet::for_project(&dir);
    let clone = project.clone();
    assert!(project.is_excluded("hidden.fake"));
    assert!(!clone.reload(), "unchanged rules are not a change");

    write_rules(&dir, "other.fake\n");
    assert!(clone.reload());
    assert!(!project.is_excluded("hidden.fake"));
    assert!(project.is_excluded("other.fake"));
}

#[cfg(unix)]
#[test]
fn an_explicit_exclusion_overrides_retention_under_an_unreadable_parent() {
    use std::os::unix::fs::PermissionsExt;

    let dir = tempdir();
    let locked = dir.join("locked");
    fs::create_dir(&locked).unwrap();
    fs::write(
        locked.join("hidden.fake"),
        "audit_hidden_symbol calls helper\n",
    )
    .unwrap();
    fs::write(dir.join("keep.fake"), "helper\n").unwrap();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::for_project(&dir)).unwrap();
    index.reindex(&registry(), false).unwrap();
    assert!(is_indexed(&index));

    write_rules(&dir, "locked/hidden.fake\n");
    let previous = fs::metadata(&locked).unwrap().permissions();
    fs::set_permissions(&locked, fs::Permissions::from_mode(0o0)).unwrap();
    if fs::read_dir(&locked).is_ok() {
        fs::set_permissions(&locked, previous).unwrap();
        eprintln!("permission-denial fixture unavailable to this privileged user");
        return;
    }
    let result = index.apply_exclusion_changes(&registry());
    fs::set_permissions(&locked, previous).unwrap();
    assert!(result.unwrap());
    assert!(
        !is_indexed(&index),
        "an unreadable parent must not retain an explicitly excluded file"
    );
    assert_eq!(index.find_symbol("helper").unwrap().len(), 1);
}

#[test]
fn a_hook_failure_during_an_exclusion_reindex_waits_in_take_warnings() {
    let dir = tempdir();
    fs::write(dir.join("keep.fake"), "helper\n").unwrap();
    fs::write(dir.join("drop.fake"), "dropped\n").unwrap();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::for_project(&dir)).unwrap();
    index.reindex(&registry(), false).unwrap();
    index.set_post_reindex_hook(Box::new(|_| {
        Err(mct_index::IndexError::Hook("disk full".into()))
    }));
    assert!(index.take_warnings().is_empty());

    write_rules(&dir, "drop.fake\n");
    assert!(index.apply_exclusion_changes(&registry()).unwrap());

    let warnings = index.take_warnings();
    assert_eq!(warnings.len(), 1, "{warnings:?}");
    assert!(warnings[0].contains("disk full"), "{warnings:?}");
    assert!(index.take_warnings().is_empty(), "taking must clear them");
}

sources.crates/mct-lang-css/tests/index_integrat:
//! Runs the real `mct-index` pipeline against a small 2-file stylesheet:
//! `main.css` (an `@import`, a simple id selector, two comma-separated class
//! selectors, one nested inside a `@media` block) and `extra.css` (the
//! imported file, with its own unrelated rule).

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-css/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;
use std::sync::Arc;

use mct_core::LanguageRegistry;
use mct_index::{ExcludeSet, Index};
use mct_lang_css::CssParser;

fn fixture_root() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/theme")
}

fn registry() -> LanguageRegistry {
    let mut registry = LanguageRegistry::new();
    registry.register(Arc::new(CssParser));
    registry
}

fn open_indexed() -> Index {
    let root = fixture_root();
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();
    let report = index.reindex(&registry(), false).unwrap();
    assert_eq!(report.files_parsed, 2, "main.css, extra.css");
    assert!(
        report.issues.is_empty(),
        "no parse issues expected: {:?}",
        report.issues
    );
    index
}

#[test]
fn find_symbol_locates_the_id_selector() {
    let index = open_indexed();
    let hits = index.find_symbol("#header").unwrap();
    assert_eq!(hits.len(), 1);
    assert_eq!(hits[0].kind, "rule");
    assert_eq!(hits[0].relative_path, "main.css");
    // `language` is read straight off the `files.language` column via the
    // symbols->files JOIN, so this is what proves the row landed under the
    // right language and not merely that the parser produced the symbol.
    assert_eq!(hits[0].language, "css");
    // A selector's recorded position is the only thing tying an indexed rule
    // back to the source text — assert it exactly. Lines are 1-based.
    assert_eq!(hits[0].line, 3, "`#header {{` is on line 3 of main.css");
}

#[test]
fn find_symbol_locates_the_comma_separated_class_selector_with_one_use() {
    let index = open_indexed();
    assert_eq!(index.find_symbol(".sidebar").unwrap().len(), 1);
}

#[test]
fn find_symbol_locates_the_rule_nested_in_a_media_query() {
    let index = open_indexed();
    // ".nav" appears twice: once in the top-level comma list, once again
    // inside @media — two distinct Rule symbols, same name.
    let hits = index.find_symbol(".nav").unwrap();
    assert_eq!(
        hits.len(),
        2,
        "top-level .nav and the one nested in @media: {hits:?}"
    );
    // Two same-named rules are only distinguishable by position, so the
    // lines are load-bearing here: line 7 is the comma list, line 13 the
    // copy nested inside `@media (min-width: 600px)`.
    let mut lines: Vec<_> = hits.iter().map(|h| h.line).collect();
    lines.sort_unstable();
    assert_eq!(lines, vec![7, 13], "{hits:?}");
    assert!(hits
        .iter()
        .all(|h| h.kind == "rule" && h.relative_path == "main.css"));
}

#[test]
fn find_references_shows_the_cross_file_import() {
    let index = open_indexed();
    let refs = index.find_references("extra.css").unwrap();
    assert_eq!(refs.len(), 1, "only main.css imports extra.css");
    assert_eq!(refs[0].relative_path, "main.css");
    assert_eq!(refs[0].kind, "imports");
}

#[test]
fn status_reports_full_css_coverage() {
    let index = open_indexed();
    let status = index.status().unwrap();
    let css = status
        .languages
        .iter()
        .find(|l| l.language == "css")
        .unwrap();
    assert_eq!(css.file_count, 2);
    assert!(status.unsupported_languages.is_empty());
    assert!(status.syntax_errors.is_empty());
}

#[test]
fn a_second_reindex_skips_unchanged_files_and_force_reparses_them() {
    let root = fixture_root();
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();

    let first = index.reindex(&registry(), false).unwrap();
    assert_eq!(first.files_parsed, 2);
    let symbols_after_first = index.status().unwrap().total_symbols;

    // Incremental: nothing on disk changed, so the real grammar must not be
    // re-run at all.
    let second = index.reindex(&registry(), false).unwrap();
    assert_eq!(second.files_parsed, 0, "{second:?}");
    assert_eq!(second.files_unchanged, 2);

    // Forced: re-parses despite being unchanged, and must land on exactly
    // the same symbol set rather than duplicating rows.
    let forced = index.reindex(&registry(), true).unwrap();
    assert_eq!(forced.files_parsed, 2, "{forced:?}");
    assert!(forced.issues.is_empty(), "{:?}", forced.issues);

    assert_eq!(
        index.status().unwrap().total_symbols,
        symbols_after_first,
        "a forced reparse must not duplicate symbols"
    );
    assert_eq!(index.find_symbol(".nav").unwrap().len(), 2);
    assert_eq!(index.find_references("extra.css").unwrap().len(), 1);
}

sources.crates/mct-lang-html/tests/index_integra:
//! Runs the real `mct-index` pipeline against a small 2-file, 2-language
//! fixture (`index.html` + `style.css`) to prove the cross-language part of
//! this feature end-to-end: an id'd/class'd HTML element's `References`
//! relations actually resolve against `Rule` symbols that `mct-lang-css`
//! indexed from a *different file* — not just that both parsers run without
//! error side by side (that's what `mct-mcp-server`'s `polyglot_fixture.rs`
//! already covers for unrelated languages).

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-html/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;
use std::sync::Arc;

use mct_core::LanguageRegistry;
use mct_index::{ExcludeSet, Index};
use mct_lang_css::CssParser;
use mct_lang_html::HtmlParser;

fn fixture_root() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/site")
}

fn registry() -> LanguageRegistry {
    let mut registry = LanguageRegistry::new();
    registry.register(Arc::new(HtmlParser));
    registry.register(Arc::new(CssParser));
    registry
}

fn open_indexed() -> Index {
    let root = fixture_root();
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();
    let report = index.reindex(&registry(), false).unwrap();
    assert_eq!(report.files_parsed, 2, "index.html, style.css");
    assert!(
        report.issues.is_empty(),
        "no parse issues expected: {:?}",
        report.issues
    );
    index
}

#[test]
fn status_reports_coverage_for_both_languages() {
    let index = open_indexed();
    let status = index.status().unwrap();
    assert!(status
        .languages
        .iter()
        .any(|l| l.language == "html" && l.file_count == 1));
    assert!(status
        .languages
        .iter()
        .any(|l| l.language == "css" && l.file_count == 1));
}

#[test]
fn find_symbol_locates_the_element_and_the_rule_in_their_own_languages() {
    let index = open_indexed();

    let header_el = index.find_symbol("header").unwrap();
    assert_eq!(header_el.len(), 1);
    assert_eq!(header_el[0].kind, "element");
    assert_eq!(header_el[0].relative_path, "index.html");
    // Two same-named things in one index, one per language: the whole point
    // of the `files.language` column is that these stay distinguishable.
    // `language` comes off that column via the symbols->files JOIN.
    assert_eq!(header_el[0].language, "html");
    // Lines are 1-based; `<div id="header" class="nav">` is line 7.
    assert_eq!(header_el[0].line, 7);

    let header_rule = index.find_symbol("#header").unwrap();
    assert_eq!(header_rule.len(), 1);
    assert_eq!(header_rule[0].kind, "rule");
    assert_eq!(header_rule[0].relative_path, "style.css");
    assert_eq!(header_rule[0].language, "css");
}

#[test]
fn a_second_reindex_skips_unchanged_files_and_force_reparses_them() {
    let root = fixture_root();
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();

    let first = index.reindex(&registry(), false).unwrap();
    assert_eq!(first.files_parsed, 2);
    let symbols_after_first = index.status().unwrap().total_symbols;

    // Incremental: nothing on disk changed, so neither grammar re-runs.
    let second = index.reindex(&registry(), false).unwrap();
    assert_eq!(second.files_parsed, 0, "{second:?}");
    assert_eq!(second.files_unchanged, 2);

    // Forced: both files re-parse, and the cross-language relations must be
    // rebuilt identically rather than duplicated or dropped.
    let forced = index.reindex(&registry(), true).unwrap();
    assert_eq!(forced.files_parsed, 2, "{forced:?}");
    assert!(forced.issues.is_empty(), "{:?}", forced.issues);

    assert_eq!(
        index.status().unwrap().total_symbols,
        symbols_after_first,
        "a forced reparse must not duplicate symbols"
    );
    assert_eq!(index.find_references("#header").unwrap().len(), 1);
    assert_eq!(index.find_references(".nav").unwrap().len(), 1);
}

#[test]
fn find_references_resolves_the_id_selector_back_to_its_html_element() {
    let index = open_indexed();
    let refs = index.find_references("#header").unwrap();
    assert_eq!(refs.len(), 1, "{refs:?}");
    assert_eq!(refs[0].relative_path, "index.html");
    assert_eq!(refs[0].from_symbol, "header");
    // Resolved through the explicit CSS evidence to the one rule.
    assert_eq!(refs[0].resolution, mct_index::Resolution::Resolved);
    let target = index.symbols_by_ids(&[refs[0].target_id.unwrap()]).unwrap();
    assert_eq!(target[0].relative_path, "style.css");
    assert_eq!(target[0].language, "css");
    assert_eq!(target[0].line, 1);
}

#[test]
fn find_references_resolves_the_class_selector_back_to_its_html_element() {
    let index = open_indexed();
    let refs = index.find_references(".nav").unwrap();
    assert_eq!(refs.len(), 1, "{refs:?}");
    assert_eq!(refs[0].relative_path, "index.html");
    assert_eq!(refs[0].from_symbol, "header");
}

#[test]
fn find_references_shows_the_stylesheet_and_script_imports() {
    let index = open_indexed();

    let css_refs = index.find_references("style.css").unwrap();
    assert_eq!(css_refs.len(), 1);
    assert_eq!(css_refs[0].relative_path, "index.html");
    assert_eq!(css_refs[0].kind, "imports");

    let js_refs = index.find_references("app.js").unwrap();
    assert_eq!(js_refs.len(), 1);
    assert_eq!(js_refs[0].relative_path, "index.html");
    assert_eq!(js_refs[0].kind, "imports");
}

#[test]
fn nested_element_without_its_own_id_reference_still_resolves_via_parent() {
    let index = open_indexed();
    let logo = index.find_symbol("logo").unwrap();
    assert_eq!(logo.len(), 1);
    assert_eq!(logo[0].parent.as_deref(), Some("header"));
}

sources.crates/mct-lang-xaml/tests/index_integra:
//! Runs the real `mct-index` pipeline against a small 2-file, 2-language
//! fixture (`MainWindow.xaml` + `MainWindow.xaml.cs`) to prove the
//! cross-language part of this feature end-to-end: a XAML event-handler
//! attribute's `References` relation actually resolves against a C# method
//! that `mct-lang-csharp` indexed from a *different file* — not just that
//! both parsers run without error side by side.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-xaml/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;
use std::sync::Arc;

use mct_core::LanguageRegistry;
use mct_index::{ExcludeSet, Index};
use mct_lang_csharp::CSharpParser;
use mct_lang_xaml::XamlParser;

fn fixture_root() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/app")
}

fn registry() -> LanguageRegistry {
    let mut registry = LanguageRegistry::new();
    registry.register(Arc::new(XamlParser));
    registry.register(Arc::new(CSharpParser));
    registry
}

fn open_indexed() -> Index {
    let root = fixture_root();
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();
    let report = index.reindex(&registry(), false).unwrap();
    assert_eq!(
        report.files_parsed, 2,
        "MainWindow.xaml, MainWindow.xaml.cs"
    );
    assert!(
        report.issues.is_empty(),
        "no parse issues expected: {:?}",
        report.issues
    );
    index
}

#[test]
fn status_reports_coverage_for_both_languages() {
    let index = open_indexed();
    let status = index.status().unwrap();
    assert!(status
        .languages
        .iter()
        .any(|l| l.language == "xaml" && l.file_count == 1));
    assert!(status
        .languages
        .iter()
        .any(|l| l.language == "csharp" && l.file_count == 1));
}

#[test]
fn find_symbol_locates_the_element_and_the_method_in_their_own_languages() {
    let index = open_indexed();

    let btn = index.find_symbol("SaveBtn").unwrap();
    assert_eq!(btn.len(), 1);
    assert_eq!(btn[0].kind, "element");
    assert_eq!(btn[0].relative_path, "MainWindow.xaml");
    // `.xaml` and `.xaml.cs` are the same stem with different suffixes — the
    // `files.language` column (read here via the symbols->files JOIN) is what
    // keeps the element and the handler apart.
    assert_eq!(btn[0].language, "xaml");
    // Lines are 1-based; the Button is on line 2 of MainWindow.xaml.
    assert_eq!(btn[0].line, 2);

    let handler = index.find_symbol("SaveBtn_Click").unwrap();
    assert_eq!(handler.len(), 1);
    assert_eq!(handler[0].kind, "method");
    assert_eq!(handler[0].relative_path, "MainWindow.xaml.cs");
    assert_eq!(handler[0].language, "csharp");

    let window = index.find_symbol("MainWindow").unwrap();
    let element = window.iter().find(|h| h.kind == "element").unwrap();
    assert_eq!(element.relative_path, "MainWindow.xaml");
    assert_eq!(element.language, "xaml");
    assert_eq!(element.line, 1);
}

#[test]
fn a_second_reindex_skips_unchanged_files_and_force_reparses_them() {
    let root = fixture_root();
    let mut index = Index::open_in_memory(&root, ExcludeSet::default()).unwrap();

    let first = index.reindex(&registry(), false).unwrap();
    assert_eq!(first.files_parsed, 2);
    let symbols_after_first = index.status().unwrap().total_symbols;

    // Incremental: nothing on disk changed, so neither grammar re-runs.
    let second = index.reindex(&registry(), false).unwrap();
    assert_eq!(second.files_parsed, 0, "{second:?}");
    assert_eq!(second.files_unchanged, 2);

    // Forced: both files re-parse, and the cross-language handler relation
    // must be rebuilt identically rather than duplicated or dropped.
    let forced = index.reindex(&registry(), true).unwrap();
    assert_eq!(forced.files_parsed, 2, "{forced:?}");
    assert!(forced.issues.is_empty(), "{:?}", forced.issues);

    assert_eq!(
        index.status().unwrap().total_symbols,
        symbols_after_first,
        "a forced reparse must not duplicate symbols"
    );
    assert_eq!(index.find_references("SaveBtn_Click").unwrap().len(), 1);
}

#[test]
fn find_references_resolves_the_click_handler_back_to_its_xaml_element() {
    let index = open_indexed();
    let refs = index.find_references("SaveBtn_Click").unwrap();
    assert_eq!(refs.len(), 1, "{refs:?}");
    assert_eq!(refs[0].relative_path, "MainWindow.xaml");
    assert_eq!(refs[0].from_symbol, "SaveBtn");
    // Resolved by the code-behind evidence to the one C# method, not by name.
    assert_eq!(refs[0].resolution, mct_index::Resolution::Resolved);
    let target = index.symbols_by_ids(&[refs[0].target_id.unwrap()]).unwrap();
    assert_eq!(target[0].relative_path, "MainWindow.xaml.cs");
    assert_eq!(target[0].language, "csharp");
    assert_eq!(target[0].kind, "method");
}

#[test]
fn find_references_resolves_the_loaded_handler_owned_by_the_module_root() {
    let index = open_indexed();
    let refs = index.find_references("Window_Loaded").unwrap();
    assert_eq!(refs.len(), 1, "{refs:?}");
    assert_eq!(refs[0].relative_path, "MainWindow.xaml");
    assert_eq!(
        refs[0].from_symbol, "MainWindow",
        "Window's own x:Name owns its Loaded handler"
    );
}

