//! Markdown notes through the existing MCP tools (issue #98): notes show up in
//! the project overview, a heading's context pack is its section, a note's is
//! the note, and `find_references` keeps note links apart by resolved target.
//! No Markdown-specific tool: everything below is `get_project_overview`,
//! `build_context_pack` and `find_references`.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-mcp-server/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::{Path, PathBuf};

use mct_index::{ExcludeSet, Index};
use mct_mcp_server::server::MctServer;
use serde_json::{json, Value};

fn vault(files: &[(&str, &str)]) -> PathBuf {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let dir = std::env::temp_dir().join(format!(
        "mct-mcp-md-notes-{}-{}",
        std::process::id(),
        COUNTER.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = fs::remove_dir_all(&dir);
    for (path, contents) in files {
        let file = dir.join(path);
        fs::create_dir_all(file.parent().unwrap()).unwrap();
        fs::write(file, contents).unwrap();
    }
    dir
}

async fn call(server: &MctServer, tool: &str, args: Value) -> String {
    let Value::Object(map) = args else {
        panic!("args must be an object")
    };
    let result = server
        .call_read_only_tool(tool, Some(map))
        .await
        .unwrap_or_else(|err| panic!("`{tool}` failed: {}", err.message));
    result
        .content
        .iter()
        .filter_map(|block| block.as_text())
        .map(|t| t.text.clone())
        .collect::<Vec<_>>()
        .join("\n")
}

async fn server_for(dir: &Path) -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(dir, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::new(index, registry)
}

const FILES: &[(&str, &str)] = &[
    ("bare.md", "Only text, no heading. See [[beta]].\n"),
    (
        "a/beta.md",
        "---\ntags: [x]\n---\n# Beta\n\nintro\n\n## Shared\n\nalpha body\n\n## Other\n\nother body\n",
    ),
    ("b/beta.md", "# Beta Two\n\n## Shared\n\nsecond body\n"),
    ("src.md", "Go to [[a/beta#Shared]] and ![[b/beta]].\n"),
];

#[tokio::test]
async fn the_overview_lists_every_note_including_heading_less_ones() {
    let dir = vault(FILES);
    let server = server_for(&dir).await;
    let out = call(&server, "get_project_overview", json!({})).await;
    for note in ["bare.md", "a/beta.md", "b/beta.md", "src.md"] {
        assert!(
            out.contains(&format!("\n{note}:\n")),
            "{note} missing:\n{out}"
        );
    }
    assert!(out.contains("[module] bare"), "{out}");
    let _ = fs::remove_dir_all(&dir);
}

#[tokio::test]
async fn a_heading_pack_is_its_section_and_stops_at_the_next_sibling() {
    let dir = vault(FILES);
    let server = server_for(&dir).await;
    let out = call(
        &server,
        "build_context_pack",
        json!({"symbol": "Shared", "path": "a/beta.md", "format": "text"}),
    )
    .await;
    assert!(out.contains("alpha body"), "{out}");
    assert!(
        !out.contains("other body"),
        "section must end at `## Other`:\n{out}"
    );
    assert!(!out.contains("second body"), "{out}");
    let _ = fs::remove_dir_all(&dir);
}

#[tokio::test]
async fn a_note_pack_is_the_note_with_its_links() {
    let dir = vault(FILES);
    let server = server_for(&dir).await;
    let out = call(
        &server,
        "build_context_pack",
        json!({"symbol": "bare", "path": "bare.md", "format": "text"}),
    )
    .await;
    assert!(out.contains("Only text, no heading"), "{out}");
    let _ = fs::remove_dir_all(&dir);
}

#[tokio::test]
async fn a_note_pack_lists_only_the_notes_that_link_to_that_exact_path() {
    let dir = vault(FILES);
    let server = server_for(&dir).await;
    let pack = |path: &str| {
        call(
            &server,
            "build_context_pack",
            json!({"symbol": "beta", "path": path, "depth": 1, "format": "text"}),
        )
    };
    let first = pack("a/beta.md").await;
    let second = pack("b/beta.md").await;
    // `src.md` links `a/beta#Shared` (a reference to a/beta.md) and embeds
    // `b/beta`; `bare.md`'s bare `[[beta]]` is ambiguous between the two, so
    // it is reported as uncertain, never as a confirmed backlink.
    assert!(first.contains("references src"), "{first}");
    assert!(!first.contains("imports src"), "{first}");
    assert!(second.contains("imports src"), "{second}");
    assert!(!second.contains("references src"), "{second}");
    for pack in [&first, &second] {
        assert!(pack.contains("Uncertain relations"), "{pack}");
        assert!(pack.contains("bare"), "{pack}");
    }
    let _ = fs::remove_dir_all(&dir);
}

#[tokio::test]
async fn references_flag_an_ambiguous_note_link_and_keep_raw_spelling() {
    let dir = vault(FILES);
    let server = server_for(&dir).await;
    let out = call(
        &server,
        "find_references",
        json!({"symbol": "beta", "format": "text"}),
    )
    .await;
    assert!(
        out.contains("bare.md:1:1 [markdown] bare --references--> beta (ambiguous among 2: a/beta.md:1, b/beta.md:1)"),
        "{out}"
    );
    assert!(
        out.contains("src --imports--> beta -> b/beta.md:1"),
        "embed keeps its own kind:\n{out}"
    );
    let _ = fs::remove_dir_all(&dir);
}

sources.crates/mct-mcp-server/tests/relation_ide:
//! Issue #97 end to end, through the real Rust parser and the tool layer: a
//! path-scoped relation query never reports a relation to a same-named
//! definition outside the scoped start, and a module path or receiver call
//! never resolves to an unrelated definition that merely shares its name.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-mcp-server/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};

use mct_index::{ExcludeSet, Index};
use mct_mcp_server::server::MctServer;
use serde_json::{json, Value};

const FILES: [(&str, &str); 4] = [
    (
        "a/src/lib.rs",
        "pub struct A;\n\
         impl A {\n    pub fn run() {}\n}\n\
         pub fn to_a() { A::run(); }\n\
         pub fn to_b() { B::run(); }\n",
    ),
    (
        "b/src/lib.rs",
        "pub struct B;\nimpl B {\n    pub fn run() {}\n}\n",
    ),
    (
        "c/src/util.rs",
        "pub fn random() -> u8 { 4 }\n\
         pub fn from_str() {}\n\
         pub struct Repo;\n\
         impl Repo {\n    pub fn get(&self) {}\n}\n",
    ),
    (
        "c/src/main.rs",
        "fn main() {\n\
         \x20   let _ = rand::random();\n\
         \x20   serde_json::from_str();\n\
         \x20   let v = vec![1];\n\
         \x20   v.get(0);\n\
         }\n",
    ),
];

fn fixture() -> PathBuf {
    let root = std::env::temp_dir().join(format!("mct-relation-identity-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    for (path, contents) in FILES {
        let file = root.join(path);
        std::fs::create_dir_all(file.parent().unwrap()).unwrap();
        std::fs::write(file, contents).unwrap();
    }
    root
}

async fn server(root: &Path) -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(root, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::new(index, registry)
}

async fn call(server: &MctServer, tool: &str, args: Value) -> String {
    let Value::Object(args) = args else {
        unreachable!()
    };
    server
        .call_read_only_tool(tool, Some(args))
        .await
        .unwrap_or_else(|err| panic!("`{tool}` failed: {}", err.message))
        .content
        .iter()
        .filter_map(|block| block.as_text())
        .map(|t| t.text.clone())
        .collect::<Vec<_>>()
        .join("\n")
}

#[tokio::test]
async fn path_scoped_relation_tools_never_report_a_same_named_target_outside_the_start() {
    let root = fixture();
    let server = server(&root).await;

    let callers = call(
        &server,
        "find_callers",
        json!({ "function": "run", "path": "a", "format": "text" }),
    )
    .await;
    let references = call(
        &server,
        "find_references",
        json!({ "symbol": "run", "path": "a", "format": "text" }),
    )
    .await;
    let impact = call(
        &server,
        "impact_analysis",
        json!({ "symbol": "run", "path": "a", "format": "text" }),
    )
    .await;
    let unscoped = call(
        &server,
        "find_callers",
        json!({ "function": "run", "format": "text" }),
    )
    .await;

    for text in [&callers, &references, &impact] {
        assert!(text.contains("to_a "), "{text}");
        assert!(
            !text.contains("to_b"),
            "B::run leaked into the `a` scope:\n{text}"
        );
    }
    assert!(
        callers.contains("to_a --calls--> run -> L3 in A\n"),
        "{callers}"
    );
    assert!(impact.contains("  1 direct caller(s)\n"), "{impact}");
    // Unscoped, both definitions are starts and each call names its own.
    assert!(
        unscoped.contains("to_b --calls--> run -> b/src/lib.rs:3 in B\n"),
        "{unscoped}"
    );

    let calls = call(
        &server,
        "find_calls",
        json!({ "function": "main", "format": "text" }),
    )
    .await;
    let _ = std::fs::remove_dir_all(&root);
    // `rand::`/`serde_json::` are not `c/src/util.rs`, whatever it defines.
    assert!(
        calls.contains("--calls--> random (unresolved)\n"),
        "{calls}"
    );
    assert!(
        calls.contains("--calls--> from_str (unresolved)\n"),
        "{calls}"
    );
    // `v.get()`: the one same-named method is a candidate, never the target.
    assert!(
        calls.contains("--calls--> get (ambiguous among 1: c/src/util.rs:5 in Repo)\n"),
        "{calls}"
    );
}

//! The query cache (issue #16) end to end, through the real tools: exact and
//! semantic hits, every validation that must turn a candidate into a miss,
//! granular invalidation, and the token saving of a hit. The semantic path
//! runs on a deterministic fake embedder whose query vectors are set per test,
//! so similarities are exact rather than whatever a real model makes of them.
//! Latency is measured separately, by `examples/cache_benchmark.rs`.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-mcp-server/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};

use mct_index::{Embedder, ExcludeSet, Index};
use mct_mcp_server::cache::{CacheConfig, CacheStats, ResponseMode};
use mct_mcp_server::server::{HybridSearchArgs, MctServer, SearchSymbolsArgs, ServerOptions};
use rmcp::handler::server::wrapper::Parameters;

const DIM: usize = 16;

/// Symbol texts get a hashed bag of words; queries listed in `queries` (keyed
/// by their split, lowercased words) get exactly the vector given.
struct FakeEmbedder {
    model: String,
    queries: HashMap<String, Vec<f32>>,
}

fn bag_of_words(text: &str) -> Vec<f32> {
    let mut v = vec![0.0f32; DIM];
    for word in text
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
    {
        let h = word.bytes().fold(0xcbf2_9ce4_8422_2325u64, |h, b| {
            (h ^ b as u64).wrapping_mul(0x100_0000_01b3)
        });
        v[(h % DIM as u64) as usize] += 1.0;
    }
    v
}

impl Embedder for FakeEmbedder {
    fn model_id(&self) -> &str {
        &self.model
    }
    fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>, String> {
        Ok(texts.iter().map(|t| bag_of_words(t)).collect())
    }
    fn embed_query(&self, query: &str) -> Result<Vec<f32>, String> {
        let key = query.split_whitespace().collect::<Vec<_>>().join(" ");
        Ok(self
            .queries
            .get(&key)
            .cloned()
            .unwrap_or_else(|| bag_of_words(query)))
    }
}

fn unit(i: usize) -> Vec<f32> {
    let mut v = vec![0.0; DIM];
    v[i] = 1.0;
    v
}

/// `cos * a + sin * b` for orthonormal `a`, `b`: similarity `cos` to `a`.
fn at_similarity(a: usize, b: usize, cos: f32) -> Vec<f32> {
    let mut v = vec![0.0; DIM];
    v[a] = cos;
    v[b] = (1.0 - cos * cos).sqrt();
    v
}

/// The vectors every semantic test uses.
fn query_vectors() -> HashMap<String, Vec<f32>> {
    let mut q = HashMap::new();
    q.insert("create invoice".to_string(), unit(0));
    q.insert("make a new invoice".to_string(), at_similarity(0, 1, 0.99));
    q.insert("build invoice".to_string(), at_similarity(0, 1, 0.90));
    // Two cached queries 0.94 apart (too far for one to hit the other), and
    // a third 0.975 from one and 0.970 from the other: a best match above the
    // threshold with no clear margin.
    q.insert("send notification".to_string(), unit(2));
    q.insert("notify user".to_string(), at_similarity(2, 3, 0.94));
    let (x, y) = (
        0.975f32,
        (0.970 - 0.94 * 0.975) / (1.0 - 0.94f32 * 0.94).sqrt(),
    );
    let mut ambiguous = vec![0.0; DIM];
    ambiguous[2] = x;
    ambiguous[3] = y;
    ambiguous[4] = (1.0 - x * x - y * y).sqrt();
    q.insert("alert user".to_string(), ambiguous);
    q
}

/// A throwaway project the tests can edit.
fn project(tag: &str) -> PathBuf {
    // Unique per call: tests run in parallel and some share a tag.
    static NEXT: AtomicUsize = AtomicUsize::new(0);
    let dir = std::env::temp_dir().join(format!(
        "mct-query-cache-{tag}-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(dir.join("src")).unwrap();
    std::fs::write(
        dir.join("src/billing.rs"),
        "pub fn create_invoice(customer: &str) -> String {\n    format!(\"inv-{customer}\")\n}\n\n\
         pub fn cancel_invoice(id: &str) -> bool {\n    !id.is_empty()\n}\n",
    )
    .unwrap();
    std::fs::write(
        dir.join("src/notify.rs"),
        "pub fn send_notification(user: &str) -> usize {\n    user.len()\n}\n",
    )
    .unwrap();
    std::fs::write(
        dir.join("src/other.rs"),
        "pub fn unrelated_helper() -> u32 {\n    42\n}\n",
    )
    .unwrap();
    dir.canonicalize().unwrap()
}

fn options(cache: CacheConfig, model: &str) -> ServerOptions {
    ServerOptions {
        cache,
        embedder: Some(Box::new(FakeEmbedder {
            model: model.to_string(),
            queries: query_vectors(),
        })),
        shared_cache: None,
        tool_attention: false,
    }
}

fn server_with(root: &Path, options: ServerOptions) -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(root, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::with_options(index, registry, options)
}

fn server(root: &Path) -> MctServer {
    server_with(root, options(CacheConfig::default(), "fake/m1"))
}

async fn reindex(server: &MctServer) {
    let registry = server.registry_handle();
    server
        .index_handle()
        .lock()
        .await
        .reindex(&registry, false)
        .unwrap();
}

fn text(result: rmcp::model::CallToolResult) -> String {
    result
        .content
        .first()
        .and_then(|block| block.as_text())
        .map(|t| t.text.clone())
        .unwrap_or_default()
}

fn search_args(query: &str) -> SearchSymbolsArgs {
    SearchSymbolsArgs {
        query: query.to_string(),
        path: None,
        language: None,
        limit: None,
        offset: None,
        snippet_lines: None,
        format: Some("text".to_string()),
        cache: None,
        detail: None,
        max_tokens: None,
    }
}

fn hybrid_args(query: &str) -> HybridSearchArgs {
    HybridSearchArgs {
        query: query.to_string(),
        // Explicit, so paraphrases share a key (auto routing may differ).
        alpha: Some(0.75),
        path: None,
        language: None,
        top_k: None,
        offset: None,
        snippet_lines: None,
        format: Some("text".to_string()),
        cache: None,
        detail: None,
        max_tokens: None,
    }
}

async fn search(server: &MctServer, args: SearchSymbolsArgs) -> String {
    text(server.search_symbols(Parameters(args)).await.unwrap())
}

async fn hybrid(server: &MctServer, args: HybridSearchArgs) -> String {
    text(server.hybrid_search(Parameters(args)).await.unwrap())
}

fn is_reference(reply: &str) -> bool {
    reply.starts_with("cache: ") && !reply.contains('\n')
}

/// What `server`'s index answers with no cache at all, for comparison.
async fn uncached_search(root: &Path, args: SearchSymbolsArgs) -> String {
    search(
        &server_with(root, options(CacheConfig::disabled(), "fake/m1")),
        args,
    )
    .await
}

async fn uncached_hybrid(root: &Path, args: HybridSearchArgs) -> String {
    hybrid(
        &server_with(root, options(CacheConfig::disabled(), "fake/m1")),
        args,
    )
    .await
}

// ---- exact path -------------------------------------------------------

#[tokio::test]
async fn an_identical_repeat_is_an_exact_hit_answered_by_reference() {
    let root = project("exact-hit");
    let server = server(&root);
    let first = search(&server, search_args("invoice")).await;
    assert!(first.contains("create_invoice"), "got: {first}");
    assert_eq!(first, uncached_search(&root, search_args("invoice")).await);

    let second = search(&server, search_args("invoice")).await;
    assert_eq!(
        second,
        "cache: unchanged since your identical earlier call (cache:false resends)"
    );
    // Whitespace-only differences normalise to the same key.
    let spaced = search(&server, search_args("  invoice ")).await;
    assert!(is_reference(&spaced), "got: {spaced}");

    let stats = server.cache_stats();
    assert_eq!((stats.exact_hit, stats.exact_miss), (2, 1), "{stats:?}");
    assert_eq!(stats.reference_responses, 2);
}

#[tokio::test]
async fn cache_false_resends_the_full_result() {
    let root = project("bypass");
    let server = server(&root);
    let first = search(&server, search_args("invoice")).await;
    let resent = search(
        &server,
        SearchSymbolsArgs {
            cache: Some(false),
            ..search_args("invoice")
        },
    )
    .await;
    assert_eq!(resent, first);
    assert_eq!(server.cache_stats().exact_hit, 0);
}

#[tokio::test]
async fn a_different_query_or_ranking_parameter_misses() {
    let root = project("params");
    let server = server(&root);
    search(&server, search_args("invoice")).await;
    for args in [
        search_args("invoices"),
        SearchSymbolsArgs {
            path: Some("src/billing.rs".to_string()),
            ..search_args("invoice")
        },
        SearchSymbolsArgs {
            language: Some("python".to_string()),
            ..search_args("invoice")
        },
    ] {
        let reply = search(&server, args).await;
        assert!(!is_reference(&reply), "got: {reply}");
    }
    let stats = server.cache_stats();
    assert_eq!((stats.exact_hit, stats.exact_miss), (0, 4), "{stats:?}");
}

#[tokio::test]
async fn presentation_parameters_reuse_the_ranking_but_render_afresh() {
    let root = project("presentation");
    let server = server(&root);
    search(&server, search_args("invoice")).await;
    let paged = SearchSymbolsArgs {
        offset: Some(1),
        snippet_lines: Some(2),
        format: Some("toon".to_string()),
        ..search_args("invoice")
    };
    let reply = search(&server, paged).await;
    // A hit (same ranking), but this page was never sent: full text, and
    // exactly what an uncached server renders.
    assert_eq!(server.cache_stats().exact_hit, 1);
    let paged = SearchSymbolsArgs {
        offset: Some(1),
        snippet_lines: Some(2),
        format: Some("toon".to_string()),
        ..search_args("invoice")
    };
    assert_eq!(reply, uncached_search(&root, paged).await);
}

#[tokio::test]
async fn a_different_tool_or_alpha_never_shares_an_entry() {
    let root = project("tools");
    let server = server(&root);
    search(&server, search_args("invoice")).await;
    let lexical_hybrid = hybrid(
        &server,
        HybridSearchArgs {
            alpha: Some(0.0),
            ..hybrid_args("invoice")
        },
    )
    .await;
    assert!(
        lexical_hybrid.starts_with("hybrid: alpha 0"),
        "got: {lexical_hybrid}"
    );
    let other_alpha = hybrid(
        &server,
        HybridSearchArgs {
            alpha: Some(0.5),
            ..hybrid_args("invoice")
        },
    )
    .await;
    assert!(!is_reference(&other_alpha), "got: {other_alpha}");
    let stats = server.cache_stats();
    assert_eq!((stats.exact_hit, stats.exact_miss), (0, 3), "{stats:?}");
}

// ---- semantic path ----------------------------------------------------

#[tokio::test]
async fn an_equivalent_query_is_a_validated_semantic_hit() {
    let root = project("semantic-hit");
    let server = server(&root);
    let original = hybrid(&server, hybrid_args("create invoice")).await;
    assert!(original.contains("create_invoice"), "got: {original}");

    let paraphrase = hybrid(&server, hybrid_args("make a new invoice")).await;
    assert_eq!(
        paraphrase,
        "cache: same as your earlier `create invoice` (sim 0.990); cache:false resends"
    );
    let stats = server.cache_stats();
    assert_eq!(
        (
            stats.semantic_candidate,
            stats.semantic_hit,
            stats.semantic_miss
        ),
        (1, 1, 1),
        "{stats:?}"
    );
    assert_eq!(stats.embedding_latency.count, 2);
}

#[tokio::test]
async fn a_semantic_hit_in_full_mode_says_whose_ranking_it_reuses() {
    let root = project("semantic-full");
    let config = CacheConfig {
        response: ResponseMode::Full,
        ..CacheConfig::default()
    };
    let server = server_with(&root, options(config, "fake/m1"));
    let original = hybrid(&server, hybrid_args("create invoice")).await;
    let paraphrase = hybrid(&server, hybrid_args("make a new invoice")).await;
    assert!(
        paraphrase.ends_with(
            "cache: ranking reused from earlier query `create invoice` (similarity 0.990), re-validated against the current index\n"
        ),
        "got: {paraphrase}"
    );
    // Same ranked symbols as the source query, rendered for this call.
    let body = |t: &str| {
        t.lines()
            .filter(|l| l.starts_with("src/"))
            .map(str::to_string)
            .collect::<Vec<_>>()
    };
    assert_eq!(body(&paraphrase), body(&original));
    // An exact repeat in full mode is the full text again, unannotated.
    assert_eq!(
        hybrid(&server, hybrid_args("create invoice")).await,
        original
    );
}

#[tokio::test]
async fn a_similarity_below_the_threshold_is_not_even_a_candidate() {
    let root = project("semantic-below");
    let server = server(&root);
    hybrid(&server, hybrid_args("create invoice")).await;
    let reply = hybrid(&server, hybrid_args("build invoice")).await;
    assert!(reply.starts_with("hybrid: alpha 0.75"), "got: {reply}");
    let stats = server.cache_stats();
    assert_eq!(
        (stats.semantic_candidate, stats.semantic_hit),
        (0, 0),
        "{stats:?}"
    );
    assert_eq!(
        reply,
        uncached_hybrid(&root, hybrid_args("build invoice")).await
    );
}

#[tokio::test]
async fn a_close_runner_up_makes_the_match_ambiguous_and_a_miss() {
    let root = project("semantic-ambiguous");
    let server = server(&root);
    hybrid(&server, hybrid_args("send notification")).await;
    hybrid(&server, hybrid_args("notify user")).await;
    let reply = hybrid(&server, hybrid_args("alert user")).await;
    assert!(!is_reference(&reply), "got: {reply}");
    assert!(!reply.contains("cache:"), "got: {reply}");
    let stats = server.cache_stats();
    assert_eq!(
        (
            stats.semantic_candidate,
            stats.ambiguous_match,
            stats.semantic_hit
        ),
        (1, 1, 0),
        "{stats:?}"
    );
    assert_eq!(
        reply,
        uncached_hybrid(&root, hybrid_args("alert user")).await
    );
}

#[tokio::test]
async fn another_embedding_model_shares_nothing() {
    let root = project("model-change");
    // Same repository and cache, different model: neither the exact nor the
    // semantic path may reuse a ranking (or compare vectors) across models.
    for query in ["create invoice", "make a new invoice"] {
        let first = server(&root);
        hybrid(&first, hybrid_args("create invoice")).await;
        let mut switched = options(CacheConfig::default(), "fake/m2");
        switched.shared_cache = Some(first.cache_handle());
        let second = server_with(&root, switched);
        let reply = hybrid(&second, hybrid_args(query)).await;
        assert!(reply.contains("(fake/m2)"), "got: {reply}");
        assert!(!reply.contains("cache:"), "got: {reply}");
        let stats = second.cache_stats();
        assert_eq!(
            (stats.exact_hit, stats.exact_miss, stats.semantic_candidate),
            (0, 2, 0),
            "{query}: {stats:?}"
        );
    }
}

#[tokio::test]
async fn disabling_the_semantic_cache_keeps_the_exact_one() {
    let root = project("semantic-off");
    let config = CacheConfig {
        semantic: false,
        ..CacheConfig::default()
    };
    let server = server_with(&root, options(config, "fake/m1"));
    hybrid(&server, hybrid_args("create invoice")).await;
    let paraphrase = hybrid(&server, hybrid_args("make a new invoice")).await;
    assert!(!paraphrase.contains("cache:"), "got: {paraphrase}");
    let repeat = hybrid(&server, hybrid_args("create invoice")).await;
    assert!(is_reference(&repeat), "got: {repeat}");
    let stats = server.cache_stats();
    assert_eq!(
        (stats.semantic_candidate, stats.exact_hit),
        (0, 1),
        "{stats:?}"
    );
    assert_eq!(stats.embedding_latency.count, 0);
}

#[tokio::test]
async fn a_disabled_cache_changes_nothing() {
    let root = project("disabled");
    let server = server_with(&root, options(CacheConfig::disabled(), "fake/m1"));
    let first = hybrid(&server, hybrid_args("create invoice")).await;
    assert_eq!(hybrid(&server, hybrid_args("create invoice")).await, first);
    assert_eq!(
        search(&server, search_args("invoice")).await,
        search(&server, search_args("invoice")).await
    );
    assert_eq!(server.cache_stats(), CacheStats::default());
}

// ---- validation and invalidation --------------------------------------

#[tokio::test]
async fn deleting_a_ranked_symbol_is_a_stale_rejection() {
    let root = project("stale");
    let server = server(&root);
    search(&server, search_args("invoice")).await;
    std::fs::write(
        root.join("src/billing.rs"),
        "pub fn cancel_invoice(id: &str) -> bool {\n    !id.is_empty()\n}\n",
    )
    .unwrap();
    reindex(&server).await;
    let reply = search(&server, search_args("invoice")).await;
    assert!(!reply.contains("create_invoice"), "got: {reply}");
    assert_eq!(reply, uncached_search(&root, search_args("invoice")).await);
    let stats = server.cache_stats();
    assert_eq!(
        (stats.stale_rejection, stats.exact_hit),
        (1, 0),
        "{stats:?}"
    );
}

#[tokio::test]
async fn editing_a_referenced_file_is_a_fingerprint_mismatch() {
    let root = project("fingerprint");
    let server = server(&root);
    let before = search(&server, search_args("invoice")).await;
    // Every ranked symbol keeps its row, but its file's content changed.
    let path = root.join("src/billing.rs");
    let source = std::fs::read_to_string(&path).unwrap();
    std::fs::write(&path, format!("{source}// trailing comment\n")).unwrap();
    reindex(&server).await;
    let reply = search(&server, search_args("invoice")).await;
    assert_eq!(reply, before, "same ranking, rendered in full again");
    let stats = server.cache_stats();
    assert_eq!(
        (
            stats.fingerprint_mismatch,
            stats.stale_rejection,
            stats.exact_hit
        ),
        (1, 0, 0),
        "{stats:?}"
    );
}

#[tokio::test]
async fn an_unrelated_change_keeps_the_entry_after_revalidation() {
    let root = project("unrelated");
    let server = server(&root);
    // In a repo this small every symbol is one of hybrid_search's semantic
    // candidates — every file is referenced by an unscoped result — so the
    // hybrid call is scoped to keep `src/other.rs` out of its result.
    let scoped = || HybridSearchArgs {
        path: Some("src/billing.rs".to_string()),
        ..hybrid_args("create invoice")
    };
    search(&server, search_args("invoice")).await;
    hybrid(&server, scoped()).await;
    // Same symbols, new body: the file's hash (and the repository state)
    // moves, no ranked symbol's file does.
    std::fs::write(
        root.join("src/other.rs"),
        "pub fn unrelated_helper() -> u32 {\n    43\n}\n",
    )
    .unwrap();
    reindex(&server).await;

    let lexical = search(&server, search_args("invoice")).await;
    assert!(is_reference(&lexical), "got: {lexical}");
    let semantic = hybrid(&server, scoped()).await;
    assert!(is_reference(&semantic), "got: {semantic}");
    let stats = server.cache_stats();
    assert_eq!(
        (
            stats.exact_hit,
            stats.repository_mismatch,
            stats.fingerprint_mismatch
        ),
        (2, 0, 0),
        "{stats:?}"
    );
}

#[tokio::test]
async fn a_change_elsewhere_that_alters_the_ranking_is_a_repository_mismatch() {
    let root = project("ranking-change");
    let server = server(&root);
    search(&server, search_args("invoice")).await;
    // No referenced file changed, but a new symbol now matches the query.
    std::fs::write(
        root.join("src/other.rs"),
        "pub fn unrelated_helper() -> u32 {\n    42\n}\n\npub fn invoice_total() -> u32 {\n    0\n}\n",
    )
    .unwrap();
    reindex(&server).await;
    let reply = search(&server, search_args("invoice")).await;
    assert!(reply.contains("invoice_total"), "got: {reply}");
    assert_eq!(reply, uncached_search(&root, search_args("invoice")).await);
    let stats = server.cache_stats();
    assert_eq!(
        (stats.repository_mismatch, stats.exact_hit),
        (1, 0),
        "{stats:?}"
    );
}

#[tokio::test]
async fn a_hit_never_shows_stale_source() {
    let root = project("fresh-source");
    let server = server(&root);
    let with_snippet = || SearchSymbolsArgs {
        snippet_lines: Some(3),
        ..search_args("create_invoice")
    };
    let before = search(&server, with_snippet()).await;
    assert!(
        before.contains("format!(\"inv-{customer}\")"),
        "got: {before}"
    );
    // The file changes on disk but the index hasn't caught up yet: the
    // ranking is still valid (a hit), the source shown must be today's.
    let path = root.join("src/billing.rs");
    let source = std::fs::read_to_string(&path).unwrap();
    std::fs::write(&path, source.replace("inv-", "INV-")).unwrap();
    let after = search(&server, with_snippet()).await;
    assert_eq!(server.cache_stats().exact_hit, 1);
    assert!(
        after.contains("format!(\"INV-{customer}\")"),
        "got: {after}"
    );
    assert!(!after.contains("\"inv-"), "got: {after}");
}

#[tokio::test]
async fn a_hit_on_the_semantic_path_is_revalidated_too() {
    let root = project("semantic-stale");
    let server = server(&root);
    hybrid(&server, hybrid_args("create invoice")).await;
    std::fs::write(
        root.join("src/billing.rs"),
        "pub fn cancel_invoice(id: &str) -> bool {\n    !id.is_empty()\n}\n",
    )
    .unwrap();
    reindex(&server).await;
    let reply = hybrid(&server, hybrid_args("make a new invoice")).await;
    assert!(!reply.contains("cache:"), "got: {reply}");
    let stats = server.cache_stats();
    assert_eq!(
        (
            stats.semantic_candidate,
            stats.stale_rejection,
            stats.semantic_hit
        ),
        (1, 1, 0),
        "{stats:?}"
    );
}

#[tokio::test]
async fn the_status_report_shows_the_cache_counters_once_used() {
    let root = project("status");
    let server = server(&root);
    let status = |s: MctServer| async move {
        text(
            s.get_indexing_status(Parameters(Default::default()))
                .await
                .unwrap(),
        )
    };
    assert!(!status(server.clone()).await.contains("Query cache"));
    search(&server, search_args("invoice")).await;
    search(&server, search_args("invoice")).await;
    let report = status(server.clone()).await;
    assert!(
        report.contains("Query cache (semantic on, threshold 0.95"),
        "got: {report}"
    );
    assert!(report.contains("exact: 1 hit, 1 miss"), "got: {report}");
}

#[tokio::test]
async fn the_entry_limit_holds() {
    let root = project("eviction");
    let server = server_with(
        &root,
        options(
            CacheConfig {
                max_entries: 2,
                ..CacheConfig::default()
            },
            "fake/m1",
        ),
    );
    for q in ["invoice", "cancel", "notification"] {
        search(&server, search_args(q)).await;
    }
    assert_eq!(server.cache_stats().entries, 2);
    // "invoice" was the least recently used: evicted, so a miss.
    let reply = search(&server, search_args("invoice")).await;
    assert!(!is_reference(&reply), "got: {reply}");
}

// ---- token reduction --------------------------------------------------

fn approx_tokens(text: &str) -> f64 {
    text.chars().count() as f64 / 4.0
}

fn reduction(uncached: &str, cached: &str) -> f64 {
    1.0 - approx_tokens(cached) / approx_tokens(uncached)
}

/// A project whose default search page is full (10 of many hits), the shape
/// of a real repository's answer.
fn large_project() -> PathBuf {
    let dir = project("tokens");
    let mut source = String::new();
    for i in 0..40 {
        source.push_str(&format!(
            "pub fn create_invoice_line_{i}(amount: u32) -> u32 {{\n    amount + {i}\n}}\n\n"
        ));
    }
    std::fs::write(dir.join("src/invoice_lines.rs"), source).unwrap();
    dir
}

#[tokio::test]
async fn exact_hits_cut_tokens_by_at_least_ninety_percent() {
    let root = large_project();
    let server = server(&root);
    let uncached = search(&server, search_args("create invoice")).await;
    let cached = search(&server, search_args("create invoice")).await;
    assert!(is_reference(&cached), "got: {cached}");
    let r = reduction(&uncached, &cached);
    assert!(r >= 0.90, "exact: {r:.3} ({uncached:?} vs {cached:?})");
}

#[tokio::test]
async fn semantic_hits_cut_tokens_by_at_least_ninety_percent() {
    let root = large_project();
    let server = server(&root);
    hybrid(&server, hybrid_args("create invoice")).await;
    // The paraphrase's own uncached answer is what a hit replaces.
    let uncached = uncached_hybrid(&root, hybrid_args("make a new invoice")).await;
    let cached = hybrid(&server, hybrid_args("make a new invoice")).await;
    assert!(is_reference(&cached), "got: {cached}");
    let r = reduction(&uncached, &cached);
    assert!(r >= 0.90, "semantic: {r:.3} ({uncached:?} vs {cached:?})");
}

sources.crates/mct-mcp-server/tests/semantic_aud:
//! R03 semantic-runtime audit: `hybrid_search` must not hold the index mutex
//! while it waits on the embedding model, ordinary queries must stay
//! responsive meanwhile, and a reindex that lands during that wait must not
//! be ranked from the stale view or leave vectors for deleted symbols.
//!
//! The regressions use a deterministic embedder whose query embedding blocks
//! on a gate the test controls (no sleeps, no timing assertions: a regression
//! shows as the embedder's own bounded wait expiring). The `semantic`-feature
//! test at the bottom runs the real local model and prints the timings that
//! `benchmarks/semantic-runtime.md` records; it is `#[ignore]`d because the
//! first run downloads the model and embeds a whole repository.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-mcp-server/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::time::Duration;

use mct_index::{Embedder, ExcludeSet, Index};
use mct_mcp_server::cache::CacheConfig;
use mct_mcp_server::server::{HybridSearchArgs, MctServer, SearchSymbolsArgs, ServerOptions};
use rmcp::handler::server::wrapper::Parameters;
use tokio::sync::Notify;

const DIM: usize = 16;
const MODEL: &str = "fake/gate";

/// How long a blocked embedder waits for the test before giving up and
/// recording that something held it up. Generous: it only matters on failure.
const GATE_LIMIT: Duration = Duration::from_secs(10);

fn bag_of_words(text: &str) -> Vec<f32> {
    let mut v = vec![0.0f32; DIM];
    for word in text
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
    {
        let h = word.bytes().fold(0xcbf2_9ce4_8422_2325u64, |h, b| {
            (h ^ b as u64).wrapping_mul(0x100_0000_01b3)
        });
        v[(h % DIM as u64) as usize] += 1.0;
    }
    v
}

/// A latch the test opens; waiting on it is bounded.
#[derive(Default)]
struct Gate {
    open: Mutex<bool>,
    changed: Condvar,
}

impl Gate {
    fn open(&self) {
        *self.open.lock().unwrap() = true;
        self.changed.notify_all();
    }

    /// Whether the gate was opened before `limit` ran out.
    fn wait_open(&self, limit: Duration) -> bool {
        let guard = self.open.lock().unwrap();
        let (guard, _) = self
            .changed
            .wait_timeout_while(guard, limit, |open| !*open)
            .unwrap();
        *guard
    }
}

/// Symbol texts embed instantly; the *query* embedding signals `entered`, then
/// blocks until the gate opens — standing in for ONNX inference.
struct BlockingEmbedder {
    entered: Arc<Notify>,
    gate: Arc<Gate>,
    timed_out: Arc<AtomicBool>,
    query_calls: Arc<AtomicUsize>,
    /// When set, symbol embedding (the pending-symbol refresh) waits on this
    /// gate instead, and signals the paired notify when it starts waiting.
    symbol_gate: Option<(Arc<Gate>, Arc<Notify>)>,
}

impl Embedder for BlockingEmbedder {
    fn model_id(&self) -> &str {
        MODEL
    }
    fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>, String> {
        if let Some((gate, entered)) = &self.symbol_gate {
            entered.notify_one();
            if !gate.wait_open(GATE_LIMIT) {
                self.timed_out.store(true, Ordering::SeqCst);
            }
        }
        Ok(texts.iter().map(|t| bag_of_words(t)).collect())
    }
    fn embed_query(&self, query: &str) -> Result<Vec<f32>, String> {
        self.query_calls.fetch_add(1, Ordering::SeqCst);
        self.entered.notify_one();
        if !self.gate.wait_open(GATE_LIMIT) {
            self.timed_out.store(true, Ordering::SeqCst);
        }
        Ok(bag_of_words(query))
    }
}

/// A throwaway project the tests can edit.
fn project(tag: &str) -> PathBuf {
    // Unique per call: tests run in parallel and some share a tag.
    static NEXT: AtomicUsize = AtomicUsize::new(0);
    let dir = std::env::temp_dir().join(format!(
        "mct-semantic-audit-{tag}-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(dir.join("src")).unwrap();
    std::fs::write(
        dir.join("src/billing.rs"),
        "pub fn create_invoice(customer: &str) -> String {\n    format!(\"inv-{customer}\")\n}\n",
    )
    .unwrap();
    std::fs::write(
        dir.join("src/notify.rs"),
        "pub fn send_notification(user: &str) -> usize {\n    user.len()\n}\n",
    )
    .unwrap();
    std::fs::write(
        dir.join("src/other.rs"),
        "pub fn unrelated_helper() -> u32 {\n    42\n}\n",
    )
    .unwrap();
    dir.canonicalize().unwrap()
}

fn server_with(root: &Path, options: ServerOptions) -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(root, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::with_options(index, registry, options)
}

async fn reindex(server: &MctServer) {
    let registry = server.registry_handle();
    server
        .index_handle()
        .lock()
        .await
        .reindex(&registry, false)
        .unwrap();
}

fn text(result: rmcp::model::CallToolResult) -> String {
    result
        .content
        .first()
        .and_then(|block| block.as_text())
        .map(|t| t.text.clone())
        .unwrap_or_default()
}

fn search_args(query: &str) -> SearchSymbolsArgs {
    SearchSymbolsArgs {
        query: query.to_string(),
        path: None,
        language: None,
        limit: None,
        offset: None,
        snippet_lines: None,
        format: None,
        cache: None,
        detail: None,
        max_tokens: None,
    }
}

fn hybrid_args(query: &str, alpha: f64) -> HybridSearchArgs {
    HybridSearchArgs {
        query: query.to_string(),
        alpha: Some(alpha),
        path: None,
        language: None,
        top_k: None,
        offset: None,
        snippet_lines: None,
        format: None,
        cache: None,
        detail: None,
        max_tokens: None,
    }
}

async fn search(server: &MctServer, query: &str) -> String {
    text(
        server
            .search_symbols(Parameters(search_args(query)))
            .await
            .unwrap(),
    )
}

async fn hybrid(server: &MctServer, query: &str, alpha: f64) -> String {
    text(
        server
            .hybrid_search(Parameters(hybrid_args(query, alpha)))
            .await
            .unwrap(),
    )
}

struct Blocked {
    server: MctServer,
    root: PathBuf,
    entered: Arc<Notify>,
    gate: Arc<Gate>,
    timed_out: Arc<AtomicBool>,
    query_calls: Arc<AtomicUsize>,
}

fn blocked_server(
    tag: &str,
    cache: CacheConfig,
    symbol_gate: Option<(Arc<Gate>, Arc<Notify>)>,
) -> Blocked {
    let entered = Arc::new(Notify::new());
    let gate = Arc::new(Gate::default());
    let timed_out = Arc::new(AtomicBool::new(false));
    let query_calls = Arc::new(AtomicUsize::new(0));
    let root = project(tag);
    let server = server_with(
        &root,
        ServerOptions {
            cache,
            embedder: Some(Box::new(BlockingEmbedder {
                entered: Arc::clone(&entered),
                gate: Arc::clone(&gate),
                timed_out: Arc::clone(&timed_out),
                query_calls: Arc::clone(&query_calls),
                symbol_gate,
            })),
            shared_cache: None,
            tool_attention: false,
        },
    );
    Blocked {
        server,
        root,
        entered,
        gate,
        timed_out,
        query_calls,
    }
}

/// While one `hybrid_search` waits on the model for its query vector, lexical
/// queries, an alpha-0 `hybrid_search` and a full reindex all complete — the
/// index mutex is not held — and the blocked call then ranks the *new* index:
/// the deleted file's symbol is gone from its answer and from the embedded
/// set (no vector resurrected), and every live symbol has a vector.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_index_mutex_is_free_while_the_query_embedding_blocks() {
    let b = blocked_server("gate", CacheConfig::default(), None);
    let semantic = {
        let server = b.server.clone();
        tokio::spawn(async move { hybrid(&server, "send notification", 0.75).await })
    };
    b.entered.notified().await;

    let lexical = search(&b.server, "create_invoice").await;
    assert!(lexical.contains("create_invoice"), "{lexical}");
    let alpha_zero = hybrid(&b.server, "unrelated_helper", 0.0).await;
    assert!(alpha_zero.contains("unrelated_helper"), "{alpha_zero}");

    std::fs::remove_file(b.root.join("src/notify.rs")).unwrap();
    reindex(&b.server).await;
    assert!(
        !b.timed_out.load(Ordering::SeqCst),
        "ordinary queries or the reindex waited for the model: the index mutex was held"
    );

    b.gate.open();
    let reply = semantic.await.unwrap();
    assert!(
        !reply.contains("send_notification"),
        "ranked from the pre-reindex view:\n{reply}"
    );
    assert!(reply.contains("create_invoice"), "{reply}");

    let index = b.server.index_handle();
    let index = index.lock().await;
    let coverage = index.embedding_coverage(MODEL).unwrap();
    assert!(coverage.total > 0);
    assert_eq!(
        coverage.embedded, coverage.total,
        "every live symbol, and nothing else, has a vector"
    );
    assert!(index.find_symbol("send_notification").unwrap().is_empty());
}

/// Concurrent semantic queries neither deadlock nor disagree: the model is
/// built once and shared, the index and cache locks are always taken in the
/// same order, and with the cache off every call takes the full path.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn concurrent_semantic_queries_agree_and_do_not_deadlock() {
    let b = blocked_server("concurrent", CacheConfig::disabled(), None);
    b.gate.open();
    let (a, b2, c, d) = tokio::join!(
        hybrid(&b.server, "create invoice", 0.75),
        hybrid(&b.server, "create invoice", 0.75),
        hybrid(&b.server, "create invoice", 0.75),
        search(&b.server, "create_invoice"),
    );
    assert_eq!(a, b2);
    assert_eq!(a, c);
    assert!(d.contains("create_invoice"), "{d}");
    assert!(a.contains("create_invoice"), "{a}");
    assert_eq!(b.query_calls.load(Ordering::SeqCst), 3);
    assert!(!b.timed_out.load(Ordering::SeqCst));
}

/// A quoted phrase and alpha 0 never touch the model: the query embedder is
/// not called, so neither can wait on it.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn lexical_only_queries_never_reach_the_model() {
    let b = blocked_server("lexical", CacheConfig::default(), None);
    let phrase = hybrid(&b.server, "\"create invoice\"", 0.75).await;
    assert!(phrase.starts_with("hybrid:"), "{phrase}");
    let _ = hybrid(&b.server, "create_invoice", 0.0).await;
    assert_eq!(b.query_calls.load(Ordering::SeqCst), 0);
}

/// The pending-symbol refresh holds the index mutex only for its snapshot and
/// each commit: while a semantic query waits on the symbol embedder, lexical
/// queries and a reindex complete, and the blocked call then ranks the new
/// index with no vector left for the deleted symbol.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_index_mutex_is_free_while_pending_symbols_embed() {
    let symbol_gate = Arc::new(Gate::default());
    let symbols_entered = Arc::new(Notify::new());
    let b = blocked_server(
        "symbols",
        CacheConfig::disabled(),
        Some((Arc::clone(&symbol_gate), Arc::clone(&symbols_entered))),
    );
    // The query itself is not gated: only the symbol embedding waits.
    b.gate.open();
    let semantic = {
        let server = b.server.clone();
        tokio::spawn(async move { hybrid(&server, "send notification", 0.75).await })
    };
    symbols_entered.notified().await;

    let lexical = search(&b.server, "create_invoice").await;
    assert!(lexical.contains("create_invoice"), "{lexical}");

    std::fs::remove_file(b.root.join("src/notify.rs")).unwrap();
    reindex(&b.server).await;
    assert!(
        !b.timed_out.load(Ordering::SeqCst),
        "ordinary queries or the reindex waited for the symbol embedder: the index mutex was held"
    );

    symbol_gate.open();
    let reply = semantic.await.unwrap();
    assert!(
        !reply.contains("send_notification"),
        "ranked from the pre-reindex view:\n{reply}"
    );
    assert!(reply.contains("create_invoice"), "{reply}");

    let index = b.server.index_handle();
    let index = index.lock().await;
    let coverage = index.embedding_coverage(MODEL).unwrap();
    assert!(coverage.total > 0);
    assert_eq!(
        coverage.embedded, coverage.total,
        "every live symbol, and nothing else, has a vector"
    );
}

/// Real local model (`bge-small-en-v1.5` via fastembed): cold start, warm
/// queries, and ordinary-query latency while the cold `hybrid_search` runs.
/// Prints a table for `benchmarks/semantic-runtime.md`.
///
/// `cargo test --locked -p mct-mcp-server --features semantic --test semantic_audit \
///    -- --ignored --nocapture real_model`
#[cfg(feature = "semantic")]
#[ignore = "not a bug: downloads the model on first use and embeds this whole repository"]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn real_model_cold_warm_and_concurrent_latency() {
    use std::time::Instant;

    let repo = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap();
    // A freshly indexed server, so every cold start embeds all symbols.
    let fresh = || {
        let registry = mct_mcp_server::registry::build_registry();
        let mut index = Index::open_in_memory(&repo, ExcludeSet::default()).unwrap();
        let t = Instant::now();
        index.reindex(&registry, false).unwrap();
        eprintln!("index: {:?}", t.elapsed());
        MctServer::with_options(
            index,
            registry,
            ServerOptions {
                cache: CacheConfig::disabled(),
                embedder: None,
                shared_cache: None,
                tool_attention: false,
            },
        )
    };

    // Cold start with nothing else queued behind it: the wall time of one
    // first query, load plus embedding plus ranking.
    let quiet = fresh();
    let t = Instant::now();
    let reply = hybrid(&quiet, "load settings from disk", 0.75).await;
    eprintln!("cold hybrid_search, quiet: {:?}", t.elapsed());
    eprintln!("{}", reply.lines().next().unwrap_or_default());
    assert!(
        reply.contains("fastembed/bge-small-en-v1.5"),
        "the real model did not run: {}",
        reply.lines().next().unwrap_or_default()
    );
    drop(quiet);

    // The same cold start with an ordinary query looping alongside it: how
    // long any other tool waits while the model works.
    let server = fresh();
    let done = Arc::new(AtomicBool::new(false));
    let cold_started = Instant::now();
    let cold = {
        let (server, done) = (server.clone(), Arc::clone(&done));
        tokio::spawn(async move {
            let reply = hybrid(&server, "load settings from disk", 0.75).await;
            done.store(true, Ordering::SeqCst);
            (reply, cold_started.elapsed())
        })
    };
    let mut ordinary: Vec<(Duration, Duration)> = Vec::new();
    while !done.load(Ordering::SeqCst) {
        let at = cold_started.elapsed();
        let t = Instant::now();
        let _ = search(&server, "refresh_embeddings").await;
        ordinary.push((at, t.elapsed()));
    }
    let (reply, cold_total) = cold.await.unwrap();
    eprintln!("cold hybrid_search, with ordinary probe: {cold_total:?}");
    eprintln!("{}", reply.lines().next().unwrap_or_default());
    assert!(
        reply.contains("fastembed/bge-small-en-v1.5"),
        "the real model did not run: {}",
        reply.lines().next().unwrap_or_default()
    );
    let worst = ordinary.iter().map(|(_, l)| *l).max().unwrap_or_default();
    eprintln!(
        "ordinary search_symbols during the cold call: {} samples, worst {worst:?}",
        ordinary.len()
    );
    for (at, latency) in &ordinary {
        eprintln!("  at +{at:?}: {latency:?}");
    }

    let mut warm = Vec::new();
    for q in [
        "parse source into symbols",
        "walk directory tree",
        "rank search results",
        "write index to disk",
        "split identifier words",
    ] {
        let t = Instant::now();
        let _ = hybrid(&server, q, 0.75).await;
        warm.push(t.elapsed());
    }
    warm.sort();
    eprintln!("warm hybrid_search: median {:?}, all {warm:?}", warm[2]);

    // Eight queries at once on the warm server: wall time of the burst, and
    // each query's own latency (they overlap on the blocking pool).
    let burst = [
        "parse source into symbols",
        "walk directory tree",
        "rank search results",
        "write index to disk",
        "split identifier words",
        "load settings from disk",
        "refresh embeddings for changed files",
        "format tool output",
    ];
    let started = Instant::now();
    let mut set = tokio::task::JoinSet::new();
    for q in burst {
        let server = server.clone();
        set.spawn(async move {
            let t = Instant::now();
            let _ = hybrid(&server, q, 0.75).await;
            t.elapsed()
        });
    }
    let mut each = Vec::new();
    while let Some(latency) = set.join_next().await {
        each.push(latency.unwrap());
    }
    let wall = started.elapsed();
    each.sort();
    eprintln!(
        "8 parallel hybrid_search: wall {wall:?}, per query min {:?} max {:?}",
        each[0],
        each[each.len() - 1]
    );
}

