//! Bodies made only of macro invocations: logging and metrics.
//!
//! Labeled evaluation corpus for the duplicate report (see ../labels.toon).
//! Parsed by mct-cli, never compiled.

// Case rs-calls-identical: the same startup banner copied into two binaries.
fn print_server_banner(config: &ServerConfig) {
    info!("listening on {}", config.address);
    info!("workers: {}", config.workers);
    info!("tls: {}", config.tls_enabled);
    info!("data dir: {}", config.data_dir);
    info!("log level: {}", config.log_level);
}

fn print_worker_banner(settings: &ServerConfig) {
    info!("listening on {}", settings.address);
    info!("workers: {}", settings.workers);
    info!("tls: {}", settings.tls_enabled);
    info!("data dir: {}", settings.data_dir);
    info!("log level: {}", settings.log_level);
}

// Case rs-calls-sinks: logging the queue state versus exporting it as gauges.
fn log_queue_state(queue: &QueueStats) {
    debug!("queue depth", queue.depth, queue.name);
    debug!("queue lag", queue.lag_ms, queue.name);
    debug!("queue consumers", queue.consumers, queue.name);
    debug!("queue retries", queue.retries, queue.name);
    debug!("queue dropped", queue.dropped, queue.name);
    debug!("queue paused", queue.paused, queue.name);
}

fn export_queue_gauges(queue: &QueueStats) {
    gauge!("queue_depth", queue.depth, queue.name);
    gauge!("queue_lag_ms", queue.lag_ms, queue.name);
    gauge!("queue_consumers", queue.consumers, queue.name);
    gauge!("queue_retries", queue.retries, queue.name);
    gauge!("queue_dropped", queue.dropped, queue.name);
    gauge!("queue_paused", queue.paused, queue.name);
}

sources.crates/mct-lang-java/tests/corpus.rs:
//! Long, multi-file fixture corpus (issue #74): the core of a warehouse
//! service in modern Java — money and exchange rates, the order aggregate,
//! inventory reservations, JDBC repositories and the application service —
//! each file 300–600 lines, in separate packages that import each other. The
//! shared checks (size, line ranges, golden snapshot, index round trip,
//! malformed input) come from `mct-corpus`; the tests below pin the constructs
//! and cross-file relations Java is expected to extract, and the parser's
//! documented limits.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-java/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{RelationKind, SymbolKind};
use mct_lang_java::JavaParser;

mct_corpus::standard_tests!(JavaParser);

use RelationKind::{Calls, Extends, Implements, Imports};

fn parent<'a>(path: &str, name: &str, kind: SymbolKind) -> Option<&'a str> {
    corpus().symbol(path, name, kind).parent.as_deref()
}

#[test]
fn classes_interfaces_and_enums_of_every_nesting_are_extracted() {
    use SymbolKind::{Class, Enum, Interface};
    assert_eq!(parent("Money.java", "Money", Class), None);
    assert_eq!(parent("Money.java", "Currency", Enum), Some("Money"));
    assert_eq!(parent("Money.java", "Allocation", Class), Some("Money"));
    assert_eq!(
        parent("ExchangeRates.java", "ExchangeRates", Interface),
        None
    );
    assert_eq!(
        parent("ExchangeRates.java", "RateSource", Interface),
        Some("ExchangeRates")
    );
    assert_eq!(
        parent("ExchangeRates.java", "CachedRates", Class),
        Some("ExchangeRates")
    );
    assert_eq!(parent("Order.java", "State", Enum), Some("Order"));
    assert_eq!(
        parent("Inventory.java", "Listener", Interface),
        Some("Inventory")
    );
    assert_eq!(
        parent("Repository.java", "Orders", Class),
        Some("Repository")
    );
    // A local class declared inside a method body is still a class.
    assert_eq!(
        parent("Inventory.java", "Expired", Class),
        Some("Inventory")
    );
}

#[test]
fn methods_constructors_fields_and_enum_constants_attach_to_their_type() {
    use SymbolKind::{Field, Method};
    assert_eq!(parent("Money.java", "plus", Method), Some("Money"));
    assert_eq!(parent("Money.java", "scale", Field), Some("Currency"));
    assert_eq!(parent("Money.java", "JPY", Field), Some("Currency"));
    assert_eq!(parent("Order.java", "INVOICED", Field), Some("State"));
    assert_eq!(
        parent("Inventory.java", "tryReserve", Method),
        Some("StockLevel")
    );
    assert_eq!(parent("Inventory.java", "test", Method), Some("Expired"));
    assert_eq!(
        parent("ExchangeRates.java", "andThenMemo", Method),
        Some("Memo")
    );
    // Constructors are methods named after their class.
    let ctors: Vec<_> = corpus()
        .symbols_named("StockLevel")
        .into_iter()
        .map(|(_, s)| s.kind)
        .collect();
    assert_eq!(ctors, [SymbolKind::Class, Method]);
    // Overloads stay separate symbols.
    let overloads = corpus()
        .symbols_named("of")
        .into_iter()
        .filter(|(p, s)| p.ends_with("Money.java") && s.parent.as_deref() == Some("Money"))
        .count();
    assert_eq!(
        overloads, 3,
        "of(BigDecimal, …), of(String, …), of(long, …)"
    );
}

#[test]
fn enum_constant_bodies_belong_to_the_enum() {
    // `NEW { Set<State> next() { … } }`: each constant body overrides the
    // abstract `next()`; its methods, and the calls in them, belong to the
    // enum.
    let next: Vec<_> = corpus()
        .symbols_named("next")
        .into_iter()
        .filter(|(p, _)| p.ends_with("Order.java"))
        .map(|(_, s)| s.parent.as_deref())
        .collect();
    assert!(next.len() > 1, "{next:?}");
    assert!(next.iter().all(|p| *p == Some("State")), "{next:?}");
    assert!(corpus().has_relation("next", Calls, "of"));
    assert!(corpus().has_relation("next", Calls, "noneOf"));
}

#[test]
fn imports_name_the_imported_type_or_member() {
    let c = corpus();
    c.relation("Money.java", "Money", Imports, "BigDecimal");
    c.relation("Money.java", "Money", Imports, "requireNonNull");
    // Nested types are imported by their own name.
    c.relation("OrderService.java", "OrderService", Imports, "Currency");
    c.relation(
        "OrderService.java",
        "OrderService",
        Imports,
        "OutOfStockException",
    );
    c.relation(
        "OrderService.java",
        "OrderService",
        Imports,
        "Transactional",
    );
    c.relation("OrderService.java", "OrderService", Imports, "groupingBy");
}

#[test]
fn extends_and_implements_name_the_supertypes() {
    let c = corpus();
    c.relation("Money.java", "Money", Implements, "Comparable");
    c.relation(
        "Money.java",
        "CurrencyMismatchException",
        Extends,
        "IllegalArgumentException",
    );
    c.relation(
        "ExchangeRates.java",
        "CachedRates",
        Implements,
        "ExchangeRates",
    );
    c.relation(
        "ExchangeRates.java",
        "CachedRates",
        Implements,
        "AutoCloseable",
    );
    c.relation("Repository.java", "Orders", Extends, "Jdbc");
    c.relation("Repository.java", "Jdbc", Implements, "Repository");
    c.relation("Inventory.java", "Expired", Implements, "Predicate");
}

#[test]
fn calls_through_every_expression_shape_are_extracted() {
    let c = corpus();
    // Plain, qualified, chained and static calls.
    c.relation("Money.java", "plus", Calls, "requireSameCurrency");
    c.relation("Money.java", "parse", Calls, "isLetter");
    c.relation("Inventory.java", "reserveLine", Calls, "max");
    c.relation("Inventory.java", "reserveLine", Calls, "tryReserve");
    // Calls inside lambdas belong to the enclosing method.
    c.relation("Inventory.java", "reserve", Calls, "undo");
    c.relation("ExchangeRates.java", "withFallback", Calls, "eurRates");
    // Calls in a method of a local class belong to that method.
    c.relation("Inventory.java", "test", Calls, "isExpired");
}

#[test]
fn cross_file_calls_are_extracted() {
    let c = corpus();
    c.relation("Order.java", "total", Calls, "summing");
    c.relation("Order.java", "addLine", Calls, "currency");
    c.relation("Inventory.java", "reserve", Calls, "lines");
    c.relation("Repository.java", "save", Calls, "drainEvents");
    c.relation("OrderService.java", "place", Calls, "convert");
    c.relation("OrderService.java", "place", Calls, "place");
    c.relation("OrderService.java", "reserve", Calls, "reserve");
    c.relation("OrderService.java", "save", Calls, "describe");
    c.relation("OrderService.java", "demo", Calls, "identity");
    assert!(c.name_matched_relation_count() >= 100);
}

#[test]
fn records_annotation_types_and_object_creation() {
    let c = corpus();
    // `record`s are classes and `@interface`s interfaces…
    for name in ["Range", "Line", "Placed", "Reservation", "Page"] {
        assert!(
            c.symbols_named(name)
                .iter()
                .any(|(_, s)| s.kind == SymbolKind::Class),
            "record {name}"
        );
    }
    for name in ["ThreadSafe", "Transactional"] {
        assert!(
            c.symbols_named(name)
                .iter()
                .any(|(_, s)| s.kind == SymbolKind::Interface),
            "@interface {name}"
        );
    }
    // …so a record's methods attach to the record…
    assert_eq!(
        parent("Money.java", "contains", SymbolKind::Method),
        Some("Range")
    );
    assert_eq!(
        parent("Order.java", "subtotal", SymbolKind::Method),
        Some("Line")
    );
    // …and its `implements` is a relation.
    c.relation("Order.java", "Placed", Implements, "OrderEvent");
    // `new T(…)` calls the type.
    assert!(c.has_relation("place", Calls, "PendingApproval"));
    // Known limit (module doc): an anonymous class's methods attach to the
    // enclosing type, and a sealed interface's `permits` is no relation.
    assert_eq!(
        parent("OrderService.java", "run", SymbolKind::Method),
        Some("OrderService")
    );
}

#[test]
#[ignore = "bug, not filed yet: `this(…)`/`super(…)` and method references (`Money::plus`) leave no relation"]
fn constructor_chaining_and_method_references_are_relations() {
    assert!(corpus().has_relation("summing", Calls, "plus"));
}

#[test]
fn type_arguments_and_qualifiers_in_supertypes_are_not_supertypes() {
    let c = corpus();
    c.relation("Money.java", "Money", Implements, "Comparable");
    assert!(!c.has_relation("Money", Implements, "Money"));
    c.relation("Repository.java", "Orders", Extends, "Jdbc");
    assert!(!c.has_relation("Orders", Extends, "Order"));
    assert!(!c.has_relation("Memo", Implements, "K"));
}

#[test]
fn index_answers_cross_file_queries() {
    let index = corpus().index();
    let callers = index.find_callers("summing").unwrap();
    let mut files: Vec<_> = callers.iter().map(|h| h.relative_path.as_str()).collect();
    files.sort();
    files.dedup();
    for file in [
        "com/example/warehouse/money/Money.java",
        "com/example/warehouse/order/Order.java",
        "com/example/warehouse/persistence/Repository.java",
    ] {
        assert!(files.contains(&file), "summing should be called in {file}");
    }
    let calls = index.find_calls("place").unwrap();
    for callee in ["priceLines", "convert", "reserve", "save", "cancel"] {
        assert!(
            calls.iter().any(|h| h.to_name == callee),
            "place should call {callee}"
        );
    }
}

sources.crates/mct-lang-js-ts/tests/corpus.rs:
//! Long, multi-file fixture corpus (issue #74): the back office of a
//! warehouse in TypeScript, TSX, JSX and CommonJS — money, the order
//! aggregate, inventory and pick lists, a typed HTTP client, a React order
//! table, a plain-JavaScript picking board and a Node seeding script — each
//! file 300–600 lines and importing the others.
//! The shared checks (size, line ranges, golden snapshot, index round trip,
//! malformed input) come from `mct-corpus`; the tests below pin what the
//! JS/TS parser is expected to extract and its documented limits.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-js-ts/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{RelationKind, SymbolKind};
use mct_lang_js_ts::JsTsParser;

mct_corpus::standard_tests!(JsTsParser);

use RelationKind::{Calls, Extends, Implements, Imports, References};
use SymbolKind::{Class, Field, Function, Interface, Method, TypeAlias};

fn parent<'a>(path: &str, name: &str, kind: SymbolKind) -> Option<&'a str> {
    corpus().symbol(path, name, kind).parent.as_deref()
}

#[test]
fn declarations_of_every_kind_are_extracted() {
    assert_eq!(parent("money.ts", "Money", Class), None);
    assert_eq!(parent("money.ts", "Comparable", Interface), None);
    assert_eq!(parent("money.ts", "MoneyJson", TypeAlias), None);
    assert_eq!(parent("money.ts", "roundHalfEven", Function), None);
    assert_eq!(parent("order.ts", "OrderEvent", TypeAlias), None);
    assert_eq!(parent("order.ts", "Placed", Interface), None);
    assert_eq!(parent("inventory.ts", "Observable", Class), None);
    assert_eq!(parent("client.ts", "WarehouseClient", Class), None);
    // Generator functions and arrow functions bound to a `const`.
    assert_eq!(parent("order.ts", "pages", Function), None);
    assert_eq!(parent("money.ts", "sum", Function), None);
    assert_eq!(parent("OrderTable.tsx", "StatusPill", Function), None);
    assert_eq!(parent("seed.cjs", "parseArgs", Function), None);
}

#[test]
fn class_members_attach_to_their_class() {
    assert_eq!(parent("money.ts", "plus", Method), Some("Money"));
    assert_eq!(parent("money.ts", "ofMinor", Method), Some("Money"));
    // `#private` members keep their `#`.
    assert_eq!(
        parent("money.ts", "#requireSameCurrency", Method),
        Some("Money")
    );
    assert_eq!(parent("money.ts", "#minor", Field), Some("Money"));
    assert_eq!(parent("order.ts", "#record", Method), Some("Order"));
    // Getters are methods.
    assert_eq!(parent("money.ts", "isZero", Method), Some("Money"));
    // Async and async-generator methods.
    assert_eq!(
        parent("client.ts", "placeOrder", Method),
        Some("WarehouseClient")
    );
    assert_eq!(
        parent("client.ts", "orders", Method),
        Some("WarehouseClient")
    );
    assert_eq!(parent("inventory.ts", "#store", Method), Some("StockCache"));
    assert_eq!(parent("order.ts", "trackingNumber", Field), Some("Order"));
}

#[test]
fn heritage_clauses_are_extends_and_implements() {
    let c = corpus();
    c.relation("money.ts", "CurrencyMismatchError", Extends, "Error");
    c.relation("money.ts", "Money", Implements, "Comparable");
    c.relation("inventory.ts", "StockCache", Extends, "Observable");
    c.relation("client.ts", "WarehouseClient", Implements, "ExchangeRates");
    // Interface `extends`.
    c.relation("order.ts", "Placed", Extends, "EventBase");
}

#[test]
fn imports_record_the_local_names_and_required_modules() {
    let c = corpus();
    // Named, type-only, default, namespace and aliased imports.
    c.relation("order.ts", "order", Imports, "sum");
    c.relation("order.ts", "order", Imports, "MoneyJson");
    c.relation("order.ts", "order", Imports, "clock");
    c.relation("client.ts", "client", Imports, "Order");
    c.relation("client.ts", "client", Imports, "describeEvent");
    c.relation("OrderTable.tsx", "OrderTable", Imports, "useReducer");
    // CommonJS `require(…)`.
    c.relation("seed.cjs", "seed", Imports, "node:fs");
    c.relation("seed.cjs", "seed", Imports, "../package.json");
}

#[test]
fn exports_by_name_are_references() {
    let c = corpus();
    c.relation("order.ts", "order", References, "Order");
    c.relation("client.ts", "client", References, "asOrderId");
    c.relation(
        "OrderTable.tsx",
        "OrderTable",
        References,
        "validatePlaceOrder",
    );
}

#[test]
fn calls_through_every_expression_shape_are_extracted() {
    let c = corpus();
    // Plain, member, private-member, optional and static calls.
    c.relation("money.ts", "plus", Calls, "#requireSameCurrency");
    c.relation("money.ts", "of", Calls, "round");
    c.relation("client.ts", "#request", Calls, "onRequest");
    c.relation("order.ts", "place", Calls, "randomUUID");
    // Calls inside callbacks belong to the enclosing function.
    c.relation("money.ts", "sum", Calls, "plus");
    c.relation("OrderTable.tsx", "useOrders", Calls, "dispatch");
    // `new X(…)` is a call to X.
    c.relation("money.ts", "parse", Calls, "MoneyFormatError");
}

#[test]
fn cross_file_calls_are_extracted() {
    let c = corpus();
    c.relation("order.ts", "fromJSON", Calls, "fromJSON");
    c.relation("client.ts", "order", Calls, "fromJSON");
    c.relation("inventory.ts", "postCounts", Calls, "invalidate");
    c.relation("OrderTable.tsx", "applyFilters", Calls, "isLarge");
    c.relation(
        "OrderTable.tsx",
        "createOrderTable",
        Calls,
        "httpStockSource",
    );
    assert!(c.name_matched_relation_count() >= 60);
}

#[test]
fn documented_limits_of_the_parser() {
    let c = corpus();
    // Known limit: a namespace's functions are top-level functions.
    assert_eq!(parent("money.ts", "fromCents", Function), None);
    // Known limit: interface members are not symbols.
    assert!(c
        .symbols_named("compareTo")
        .iter()
        .all(|(_, s)| s.parent.as_deref() == Some("Money")));
    // Known limit: JSX elements are not calls of their component (see the
    // crate docs).
    assert!(!c.has_relation("OrderTable", Calls, "StockBadge"));
}

#[test]
fn ts_enums_and_namespaces_are_symbols() {
    assert_eq!(parent("money.ts", "Currency", SymbolKind::Enum), None);
    assert_eq!(parent("order.ts", "State", SymbolKind::Enum), None);
    assert_eq!(parent("money.ts", "Legacy", SymbolKind::Module), None);
}

#[test]
fn plain_javascript_class_fields_and_jsx_use_the_js_grammar() {
    let c = corpus();
    // `.jsx` goes through tree-sitter-javascript: `field_definition`, not
    // TS's `public_field_definition`. An arrow-valued field is a method…
    assert_eq!(
        parent("PickBoard.jsx", "handleScan", Method),
        Some("PickSession")
    );
    assert_eq!(
        parent("PickBoard.jsx", "retry", Method),
        Some("ScanErrorBoundary")
    );
    // …any other value a field, `static` and `#private` included.
    assert_eq!(
        parent("PickBoard.jsx", "state", Field),
        Some("ScanErrorBoundary")
    );
    assert_eq!(
        parent("PickBoard.jsx", "#nextId", Field),
        Some("PickSession")
    );
    assert_eq!(
        parent("PickBoard.jsx", "getDerivedStateFromError", Method),
        Some("ScanErrorBoundary")
    );
    c.relation("PickBoard.jsx", "ScanErrorBoundary", Extends, "Component");
    c.relation("PickBoard.jsx", "handleScan", Calls, "formatLocation");
    // A namespace import records its local name.
    c.relation("PickBoard.jsx", "PickBoard", Imports, "orders");
    // JSX elements are not calls here either.
    assert!(!c.has_relation("Board", Calls, "TaskCard"));
}

#[test]
fn object_literal_methods_and_nested_functions_are_parentless_functions() {
    // An object literal is not a type: its methods (getters included) are
    // functions, as in a CommonJS `module.exports = { … }`.
    assert_eq!(parent("inventory.ts", "levels", Function), None);
    assert_eq!(parent("money.ts", "rate", Function), None);
    assert_eq!(parent("seed.cjs", "sent", Function), None);
    // Calls inside them stay theirs.
    corpus().relation("inventory.ts", "levels", Calls, "parseLocation");
    // Nested functions are functions too, never members of the enclosing
    // class or function.
    assert_eq!(parent("order.ts", "waitedMinutes", Function), None);
    assert_eq!(parent("OrderTable.tsx", "showSlip", Function), None);
    let c = corpus();
    assert!(c
        .files
        .iter()
        .flat_map(|f| &f.parsed.symbols)
        .all(|s| s.kind != Method || s.parent.is_some()));
}

#[test]
fn index_answers_cross_file_queries() {
    let index = corpus().index();
    let callers = index.find_callers("fromJSON").unwrap();
    let mut files: Vec<_> = callers.iter().map(|h| h.relative_path.as_str()).collect();
    files.sort();
    files.dedup();
    assert_eq!(files, ["src/api/client.ts", "src/order.ts"]);
    let refs = index.find_references("WarehouseClient").unwrap();
    assert!(refs
        .iter()
        .any(|r| r.relative_path == "src/ui/OrderTable.tsx"));
    let component_refs = index.find_references("StockBadge").unwrap();
    assert!(component_refs
        .iter()
        .any(|r| r.relative_path == "src/ui/OrderTable.tsx" && r.kind == "references"));
}

sources.crates/mct-lang-kotlin/tests/corpus.rs:
//! Long, multi-file fixture corpus (issue #74): a warehouse service in
//! idiomatic Kotlin — money (value-like class, enum with bodies, operators,
//! extensions, delegation), the order aggregate (sealed events, data classes,
//! validation), inventory (coroutines, delegated properties), pricing (a DSL
//! with lambdas with receiver, sealed promotions) and the application wiring
//! (router, objects, `main`) — each file 300–600 lines and importing the
//! others. The shared checks (size, line ranges, golden snapshot, index round
//! trip, malformed input) come from `mct-corpus`; the tests below pin what
//! Kotlin is expected to extract and the parser's documented limits.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-kotlin/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{RelationKind, SymbolKind};
use mct_lang_kotlin::KotlinParser;

mct_corpus::standard_tests!(KotlinParser);

use RelationKind::{Calls, Extends, Implements, Imports};
use SymbolKind::{Class, Field, Function, Interface, Method, Module};

fn parent<'a>(path: &str, name: &str, kind: SymbolKind) -> Option<&'a str> {
    corpus().symbol(path, name, kind).parent.as_deref()
}

#[test]
fn package_headers_are_modules() {
    for (path, package) in [
        ("Money.kt", "com.example.warehouse.money"),
        ("Order.kt", "com.example.warehouse.order"),
        ("WarehouseApp.kt", "com.example.warehouse.app"),
    ] {
        let c = corpus();
        let m = c.symbol(path, package, Module);
        // Like Go's package clause, the package module spans the file.
        let lines = c
            .files
            .iter()
            .find(|f| f.path.ends_with(path))
            .unwrap()
            .line_count();
        assert_eq!(
            (m.location.line, m.location.end_line),
            (1, Some(lines as u32)),
            "{path}"
        );
    }
}

#[test]
fn classes_objects_and_interfaces_are_extracted() {
    assert_eq!(parent("Money.kt", "Money", Class), None);
    assert_eq!(parent("Money.kt", "MoneyRange", Class), None);
    assert_eq!(parent("Money.kt", "Currency", Class), None);
    assert_eq!(parent("Money.kt", "ExchangeRates", Interface), None);
    assert_eq!(parent("Order.kt", "OrderId", Class), None);
    assert_eq!(parent("Order.kt", "Placed", Class), Some("OrderEvent"));
    assert_eq!(parent("Inventory.kt", "InventoryListener", Interface), None);
    assert_eq!(parent("Pricing.kt", "BuyXGetY", Class), Some("Promotion"));
    // `object` declarations are classes too.
    assert_eq!(
        parent("Pricing.kt", "FreeShipping", Class),
        Some("Promotion")
    );
    assert_eq!(parent("WarehouseApp.kt", "OrderNumbers", Class), None);
}

#[test]
fn members_attach_to_their_type() {
    assert_eq!(parent("Money.kt", "plus", Method), Some("Money"));
    assert_eq!(parent("Money.kt", "amount", Field), Some("Money"));
    assert_eq!(
        parent("Inventory.kt", "tryReserve", Method),
        Some("StockLevel")
    );
    assert_eq!(
        parent("Pricing.kt", "volume", Method),
        Some("PricingBuilder")
    );
    assert_eq!(parent("WarehouseApp.kt", "handle", Method), Some("Router"));
    // Primary-constructor `val`/`var` parameters are fields.
    assert_eq!(
        parent("Inventory.kt", "orderId", Field),
        Some("Reservation")
    );
    assert_eq!(
        parent("Pricing.kt", "customerTier", Field),
        Some("PricingContext")
    );
}

#[test]
fn extension_functions_attach_to_their_receiver() {
    assert_eq!(parent("Money.kt", "toMoney", Method), Some("String"));
    // `fun Int.eur()` and `fun BigDecimal.eur()` are two symbols.
    let eur: Vec<_> = corpus()
        .symbols_named("eur")
        .into_iter()
        .map(|(_, s)| s.parent.as_deref().unwrap())
        .collect();
    assert_eq!(eur, ["Int", "BigDecimal"]);
    // The receiver is named without its type arguments.
    assert_eq!(
        parent("Order.kt", "countByState", Method),
        Some("Collection")
    );
    assert_eq!(parent("Inventory.kt", "pickingRoute", Method), Some("List"));
}

#[test]
fn delegation_specifiers_split_into_extends_and_implements() {
    let c = corpus();
    // A constructor call means a superclass…
    c.relation(
        "Money.kt",
        "CurrencyMismatchException",
        Extends,
        "IllegalArgumentException",
    );
    c.relation("Order.kt", "Placed", Extends, "OrderEvent");
    c.relation("Pricing.kt", "BuyXGetY", Extends, "Promotion");
    // …a bare type an interface, type arguments dropped.
    c.relation("Money.kt", "Money", Implements, "Comparable");
    c.relation("Inventory.kt", "Location", Implements, "Comparable");
    c.relation("WarehouseApp.kt", "Outbox", Implements, "EventSink");
    c.relation("WarehouseApp.kt", "Outbox", Implements, "InventoryListener");
    assert!(!c.has_relation("Money", Implements, "Money"));
}

#[test]
fn imports_name_the_imported_symbol_or_its_alias() {
    let c = corpus();
    c.relation("Order.kt", "Order", Imports, "sum");
    c.relation("WarehouseApp.kt", "WarehouseApp", Imports, "defaultEngine");
    // `import java.util.Currency as JavaCurrency`.
    c.relation("Money.kt", "Money", Imports, "JavaCurrency");
    c.relation("WarehouseApp.kt", "WarehouseApp", Imports, "renderSlip");
}

#[test]
fn calls_through_every_expression_shape_are_extracted() {
    let c = corpus();
    // Constructor calls, safe calls, trailing lambdas, scope functions.
    c.relation("Money.kt", "plus", Calls, "requireSameCurrency");
    c.relation("Money.kt", "plus", Calls, "Money");
    c.relation("Inventory.kt", "reserveLine", Calls, "tryReserve");
    c.relation("Inventory.kt", "reserveLine", Calls, "maxByOrNull");
    c.relation("Pricing.kt", "quote", Calls, "distributeDiscount");
    // Calls in a `suspend` function and inside `withLock { … }`.
    c.relation("Inventory.kt", "reserve", Calls, "reserveLine");
    c.relation("Inventory.kt", "reserve", Calls, "withLock");
}

#[test]
fn cross_file_calls_are_extracted() {
    let c = corpus();
    c.relation("Order.kt", "place", Calls, "random");
    c.relation("Pricing.kt", "quote", Calls, "convert");
    c.relation("Pricing.kt", "shelfPrice", Calls, "gross");
    c.relation("WarehouseApp.kt", "place", Calls, "quote");
    c.relation("WarehouseApp.kt", "reserveOrReject", Calls, "reserve");
    c.relation("WarehouseApp.kt", "demoService", Calls, "defaultEngine");
    assert!(c.name_matched_relation_count() >= 80);
}

#[test]
fn enum_class_bodies_are_visited() {
    // Entries are fields of the enum; methods and properties in its body,
    // and the overrides in entry bodies, are its members.
    let c = corpus();
    assert_eq!(parent("Money.kt", "EUR", Field), Some("Currency"));
    assert_eq!(parent("Pricing.kt", "GENERAL", Field), Some("VatCategory"));
    assert_eq!(parent("Order.kt", "canMoveTo", Method), Some("State"));
    assert_eq!(parent("Order.kt", "isTerminal", Field), Some("State"));
    assert!(c.has_relation("next", Calls, "setOf"));
    assert_eq!(parent("Money.kt", "scale", Field), Some("Currency"));
    assert_eq!(parent("Pricing.kt", "VatCategory", Class), None);
}

#[test]
fn top_level_and_local_functions_are_functions() {
    let c = corpus();
    let function = |path: &str, name: &str| c.symbol(path, name, Function).parent.as_deref();
    assert_eq!(function("Money.kt", "vat"), None);
    assert!(c
        .symbols_named("auditLine")
        .iter()
        .all(|(_, s)| s.kind == Function && s.parent.is_none()));
    // Local functions too, not methods of the enclosing type.
    assert_eq!(function("Order.kt", "rule"), None);
    assert_eq!(function("Inventory.kt", "stdDev"), None);
    // A local `val` is no field of the class (`Line.subtotal` in Order.kt
    // is a real property).
    assert!(c
        .symbols_named("subtotal")
        .iter()
        .all(|(p, _)| !p.ends_with("Pricing.kt")));
    let expires: Vec<_> = c
        .symbols_named("expiresAt")
        .into_iter()
        .map(|(_, s)| s.parent.as_deref())
        .collect();
    assert_eq!(expires, [Some("Reservation")]);
}

#[test]
fn documented_limits_of_the_parser() {
    let c = corpus();
    // Known limit (module doc): infix and operator calls (`a percentOf b`,
    // `a + b`) are no calls.
    assert!(!c.has_relation("vat", Calls, "percentOf"));
}

#[test]
#[ignore = "bug, not filed yet: companion objects and `typealias` leave no symbol"]
fn companion_objects_and_type_aliases_are_symbols() {
    for name in ["Factory", "Rate", "Handler"] {
        assert!(!corpus().symbols_named(name).is_empty(), "{name}");
    }
}

#[test]
fn index_answers_cross_file_queries() {
    let index = corpus().index();
    let callers = index.find_callers("sum").unwrap();
    let mut files: Vec<_> = callers.iter().map(|h| h.relative_path.as_str()).collect();
    files.sort();
    files.dedup();
    assert!(files.contains(&"order/Order.kt"), "{files:?}");
    assert!(files.contains(&"pricing/Pricing.kt"), "{files:?}");
    let calls = index.find_calls("place").unwrap();
    for callee in ["priceLines", "quote", "convert", "reserveOrReject"] {
        assert!(
            calls.iter().any(|h| h.to_name == callee),
            "place should call {callee}"
        );
    }
}

sources.crates/mct-lang-python/tests/tokens.rs:
//! Token extraction for Python (issue #207): kinds, literals, trivia, lines,
//! syntax errors and pathological nesting.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{TokenKind, TokenSource, TokenizedFile};
use mct_lang_python::PythonTokenSource;
use TokenKind::{BlockEnd, BlockStart, Identifier, Keyword, Literal, Punctuation};

fn tokenize(source: &str) -> TokenizedFile {
    PythonTokenSource.tokenize("pkg/mod.py", source).unwrap()
}

fn pairs(file: &TokenizedFile) -> Vec<(TokenKind, &str)> {
    file.tokens
        .iter()
        .map(|token| (token.kind, token.text.as_str()))
        .collect()
}

#[test]
fn language_id_matches_the_parser() {
    use mct_core::LanguageParser;
    assert_eq!(
        PythonTokenSource.language_id(),
        mct_lang_python::PythonParser.language_id()
    );
}

#[test]
fn structural_strings_keep_interpolation_expressions_and_format_expressions() {
    let source = "def format_value(value, width, precision):\n    return f\"{{escaped}} {value + value!r:{width}.{precision}f}\"\n";
    let structural = PythonTokenSource
        .tokenize_structural("sample.py", source)
        .unwrap();
    assert!(structural.error_lines.is_empty(), "{structural:?}");
    for expected in ["+", "width", "precision", "!r"] {
        assert!(
            structural.tokens.iter().any(|token| token.text == expected),
            "{expected}: {structural:?}"
        );
    }
    assert_eq!(
        tokenize(source)
            .tokens
            .iter()
            .filter(|token| token.kind == Literal)
            .count(),
        1
    );
    for token in &structural.tokens {
        assert_eq!(&source[token.start_byte..token.end_byte], token.text);
    }
}

#[test]
fn structural_plain_strings_stay_atomic_and_nested_strings_are_safe() {
    let source = "def plain():\n    return 'escaped\\ntext'\n";
    assert_eq!(
        tokenize(source),
        PythonTokenSource
            .tokenize_structural("sample.py", source)
            .unwrap()
    );
    for source in [
        "x = f'{call(\"a\")}'\n",
        "x = f'{value'\n",
        "x = f'{value:{width}}'\n",
    ] {
        let first = PythonTokenSource
            .tokenize_structural("sample.py", source)
            .unwrap();
        let second = PythonTokenSource
            .tokenize_structural("sample.py", source)
            .unwrap();
        assert_eq!(first, second);
    }
}

#[test]
fn keywords_are_told_apart_from_identifiers() {
    let source =
        "async def add(self, x):\n    if x and not self.done:\n        return await x\n    pass\n";
    let file = tokenize(source);
    assert!(file.error_lines.is_empty());
    let tokens = pairs(&file);
    for keyword in [
        "async", "def", "if", "and", "not", "return", "await", "pass",
    ] {
        assert!(tokens.contains(&(Keyword, keyword)), "{keyword}");
    }
    // `self` is an ordinary name in Python.
    for name in ["add", "self", "x", "done"] {
        assert!(tokens.contains(&(Identifier, name)), "{name}");
    }
    assert!(!tokens.contains(&(Keyword, "add")));
}

#[test]
fn operators_and_punctuation_are_kept() {
    let file = tokenize("def f(a, *b, **c) -> int:\n    return a[0] ** 2 // 3\n");
    let punctuation: Vec<&str> = file
        .tokens
        .iter()
        .filter(|token| token.kind == Punctuation)
        .map(|token| token.text.as_str())
        .collect();
    assert_eq!(
        punctuation,
        ["(", ",", "*", ",", "**", ")", "->", ":", "[", "]", "**", "//"]
    );
}

#[test]
fn every_kind_of_literal_is_a_single_token() {
    let source = concat!(
        "x = [1_000, 0x1F, 1.5e3, 2j, True, False, None, ...]\n",
        "y = ('cc', \"es\\n\\\"c\", r'raw\\d', b\"by\", f\"hi {a!r:>{w}} {{lit}}\")\n",
    );
    let file = tokenize(source);
    assert!(file.error_lines.is_empty());
    let literals: Vec<&str> = file
        .tokens
        .iter()
        .filter(|token| token.kind == Literal)
        .map(|token| token.text.as_str())
        .collect();
    assert_eq!(
        literals,
        [
            "1_000",
            "0x1F",
            "1.5e3",
            "2j",
            "True",
            "False",
            "None",
            "...",
            "'cc'",
            "\"es\\n\\\"c\"",
            "r'raw\\d'",
            "b\"by\"",
            "f\"hi {a!r:>{w}} {{lit}}\"",
        ]
    );
    // The interpolation's names are inside the f-string literal, not tokens.
    assert!(!file.tokens.iter().any(|token| token.text == "w"));
}

#[test]
fn implicit_concatenation_keeps_one_literal_per_string() {
    let file = tokenize("x = 'a' 'b'\n");
    assert_eq!(
        pairs(&file),
        [
            (Identifier, "x"),
            (Punctuation, "="),
            (Literal, "'a'"),
            (Literal, "'b'")
        ]
    );
}

#[test]
fn a_multi_line_string_is_one_token_spanning_its_lines() {
    let source = "def f():\n    \"\"\"doc\n    string\"\"\"\n    return 1\n";
    let file = tokenize(source);
    let doc = file
        .tokens
        .iter()
        .find(|token| token.kind == Literal && token.text.starts_with("\"\"\""))
        .unwrap();
    assert_eq!((doc.line, doc.end_line), (2, 3));
    assert_eq!(&source[doc.start_byte..doc.end_byte], doc.text);
    let one = file.tokens.iter().find(|token| token.text == "1").unwrap();
    assert_eq!((one.line, one.end_line), (4, 4));
}

#[test]
fn comments_line_continuations_and_whitespace_produce_no_tokens() {
    let source = "#!/usr/bin/env python\n# note\nx = (1 +  # why\n     2) \\\n    + 3\n\n\n";
    let file = tokenize(source);
    assert!(file.error_lines.is_empty());
    assert_eq!(
        pairs(&file),
        [
            (Identifier, "x"),
            (Punctuation, "="),
            (Punctuation, "("),
            (Literal, "1"),
            (Punctuation, "+"),
            (Literal, "2"),
            (Punctuation, ")"),
            (Punctuation, "+"),
            (Literal, "3"),
        ]
    );
    // `#` inside a string is part of the literal.
    let file = tokenize("s = '# not a comment'\n");
    assert!(file
        .tokens
        .iter()
        .any(|token| token.kind == Literal && token.text == "'# not a comment'"));
}

#[test]
fn indentation_width_does_not_change_the_tokens() {
    let four = tokenize("if a:\n    b()\n");
    let eight = tokenize("if a:\n        b()\n");
    assert_eq!(pairs(&four), pairs(&eight));
}

#[test]
fn every_block_is_bracketed_by_markers_around_its_statements() {
    let file = tokenize("if a:\n    b()\nc()\n");
    assert_eq!(
        pairs(&file),
        [
            (Keyword, "if"),
            (Identifier, "a"),
            (Punctuation, ":"),
            (BlockStart, ""),
            (Identifier, "b"),
            (Punctuation, "("),
            (Punctuation, ")"),
            (BlockEnd, ""),
            (Identifier, "c"),
            (Punctuation, "("),
            (Punctuation, ")"),
        ]
    );
    let lines: Vec<(TokenKind, u32)> = file
        .tokens
        .iter()
        .filter(|token| token.kind.is_block_marker())
        .map(|token| (token.kind, token.line))
        .collect();
    assert_eq!(lines, [(BlockStart, 2), (BlockEnd, 2)]);
}

#[test]
fn moving_a_statement_out_of_a_block_changes_the_tokens() {
    let inside = tokenize("if a:\n    b()\n    c()\n");
    let outside = tokenize("if a:\n    b()\nc()\n");
    let texts = |file: &TokenizedFile| -> Vec<String> {
        file.tokens
            .iter()
            .filter(|token| !token.kind.is_block_marker())
            .map(|token| token.text.clone())
            .collect()
    };
    // Same source tokens, different nesting: only the markers tell them apart.
    assert_eq!(texts(&inside), texts(&outside));
    assert_ne!(pairs(&inside), pairs(&outside));
}

#[test]
fn a_one_line_suite_matches_its_indented_form() {
    let one_line = tokenize("for x in y: f(x)\n");
    let indented = tokenize("for x in y:\n    f(x)\n");
    assert_eq!(pairs(&one_line), pairs(&indented));
}

#[test]
fn a_functions_markers_stay_within_its_own_lines() {
    let source = "def f(a):\n    if a:\n        return 1\n    return 2\n\n\ny = 3\n";
    let file = tokenize(source);
    let markers: Vec<(TokenKind, u32)> = file
        .tokens
        .iter()
        .filter(|token| token.kind.is_block_marker())
        .map(|token| (token.kind, token.line))
        .collect();
    assert_eq!(
        markers,
        [
            (BlockStart, 2),
            (BlockStart, 3),
            (BlockEnd, 3),
            (BlockEnd, 4)
        ]
    );
}

#[test]
fn token_offsets_are_in_order_and_index_the_source() {
    let source = "def \u{e9}t\u{e9}():\n    s = '\u{1f980}'\n";
    let file = tokenize(source);
    for token in &file.tokens {
        assert_eq!(&source[token.start_byte..token.end_byte], token.text);
    }
    assert!(file
        .tokens
        .windows(2)
        .all(|pair| pair[0].end_byte <= pair[1].start_byte));
    assert!(file
        .tokens
        .iter()
        .any(|token| token.kind == Identifier && token.text == "\u{e9}t\u{e9}"));
}

#[test]
fn a_syntax_error_is_reported_by_line_without_panicking() {
    let source = "def ok():\n    pass\n\ndef broken(:\n    pass\n\ndef also_ok():\n    pass\n";
    let file = tokenize(source);
    assert!(
        file.error_lines
            .iter()
            .any(|range| range.start <= 4 && range.end >= 4),
        "{:?}",
        file.error_lines
    );
    assert!(file.tokens.iter().any(|token| token.text == "ok"));
    assert!(tokenize("def ok():\n    pass\n").error_lines.is_empty());
}

#[test]
fn garbage_and_empty_input_never_panic() {
    assert!(tokenize("").tokens.is_empty());
    let file = tokenize("))) \u{0} $$ ?? \"unterminated\n  if\n");
    assert!(!file.error_lines.is_empty());
}

#[test]
fn pathologically_deep_nesting_does_not_overflow_the_stack() {
    let depth = 10_000;
    let source = format!("x = {}1{}\n", "(".repeat(depth), ")".repeat(depth));
    let handle = std::thread::Builder::new()
        .stack_size(512 * 1024)
        .spawn(move || tokenize(&source).tokens.len())
        .unwrap();
    assert!(handle.join().unwrap() > 2 * depth);
}

fn roles(file: &TokenizedFile) -> Vec<(&str, mct_core::TokenRole)> {
    file.tokens
        .iter()
        .filter(|token| matches!(token.kind, Identifier | Literal))
        .map(|token| (token.text.as_str(), token.role))
        .collect()
}

#[test]
fn identifier_roles_are_syntactic_positions() {
    use mct_core::TokenRole::{Callee, Declaration, Member, Parameter, Type, Unclassified};
    let source = "\
def load(user, limit: int, *rest, mode=None, flag: bool = True) -> Result:
    local = user.email
    send(local, retries=limit)
    user.mailer.notify(local)
    value: typing.Optional[int] = None
    return lambda item: item
";
    let file = tokenize(source);
    let roles = roles(&file);
    for expected in [
        ("load", Declaration),
        ("user", Parameter),
        ("limit", Parameter),
        ("mode", Parameter),
        ("flag", Parameter),
        ("int", Type),
        ("bool", Type),
        ("Result", Type),
        ("email", Member),
        ("notify", Member),
        ("retries", Member),
        ("send", Callee),
        ("typing", Type),
        ("Optional", Type),
        ("item", Parameter),
        ("rest", Parameter),
        // Locals and references are not classified.
        ("local", Unclassified),
        ("value", Unclassified),
    ] {
        assert!(roles.contains(&expected), "{expected:?} in {roles:?}");
    }
    // A later reference to a parameter is a reference, not a declaration.
    assert!(roles.contains(&("user", Unclassified)), "{roles:?}");
}

/// Every role a name takes, in source order.
fn roles_of(roles: &[(&str, mct_core::TokenRole)], name: &str) -> Vec<mct_core::TokenRole> {
    roles
        .iter()
        .filter(|(text, _)| *text == name)
        .map(|(_, role)| *role)
        .collect()
}

#[test]
fn splat_parameters_are_parameters_but_unpacking_and_splat_arguments_are_not() {
    use mct_core::TokenRole::{Parameter, Unclassified};
    let source = "\
def forward(first, *args, key, **kwargs):
    head, *tail = args
    for *init, last in pairs:
        pass
    pick = lambda *xs, **kw: xs
    return first(*args, **kwargs)


def typed(*values: int, **named: str):
    pass
";
    let structural = PythonTokenSource
        .tokenize_structural("pkg/mod.py", source)
        .unwrap();
    for file in [tokenize(source), structural] {
        let roles = roles(&file);
        // Declared, then read, then splatted into a call.
        assert_eq!(
            roles_of(&roles, "args"),
            [Parameter, Unclassified, Unclassified]
        );
        assert_eq!(roles_of(&roles, "kwargs"), [Parameter, Unclassified]);
        assert_eq!(roles_of(&roles, "key"), [Parameter]);
        assert_eq!(roles_of(&roles, "xs"), [Parameter, Unclassified]);
        assert_eq!(roles_of(&roles, "kw"), [Parameter]);
        assert_eq!(roles_of(&roles, "values"), [Parameter]);
        assert_eq!(roles_of(&roles, "named"), [Parameter]);
        // The same splat patterns as unpacking targets are locals.
        for local in ["head", "tail", "init", "last"] {
            assert_eq!(roles_of(&roles, local), [Unclassified], "{local}");
        }
    }
}

#[test]
fn literal_categories_include_interpolation_and_docstrings_in_both_modes() {
    use mct_core::LiteralCategory::{Docstring, InterpolatedString, Null, Number, String};
    use mct_core::TokenRole::Literal as Lit;
    let source = "\
def f(x):
    \"\"\"Doc.\"\"\"
    a = f\"{x + 1}\"
    b = \"plain\"
    return 2 if a else None
";
    let broad = tokenize(source);
    let roles = roles(&broad);
    for expected in [
        ("\"\"\"Doc.\"\"\"", Lit(Docstring)),
        ("f\"{x + 1}\"", Lit(InterpolatedString)),
        ("\"plain\"", Lit(String)),
        ("2", Lit(Number)),
        ("None", Lit(Null)),
    ] {
        assert!(roles.contains(&expected), "{expected:?} in {roles:?}");
    }
    // The structural stream expands the f-string; its fragments are strings
    // and its expression keeps ordinary roles.
    let structural = PythonTokenSource
        .tokenize_structural("pkg/mod.py", source)
        .unwrap();
    let roles = self::roles(&structural);
    assert!(
        !roles
            .iter()
            .any(|(_, role)| *role == Lit(InterpolatedString)),
        "{roles:?}"
    );
    assert!(roles.contains(&("1", Lit(Number))), "{roles:?}");
}

fn contexts(file: &TokenizedFile) -> Vec<(String, Vec<String>, Vec<String>)> {
    file.callables
        .as_ref()
        .unwrap()
        .iter()
        .map(|span| {
            (
                span.name.clone(),
                span.decorators.clone(),
                span.enclosing.clone(),
            )
        })
        .collect()
}

#[test]
fn callables_carry_decorators_and_enclosing_constructs() {
    let source = "\
@cache
@app.route(
    \"/x\",   # comment inside
)
def top(): pass

try:
    def guarded(): pass
except ImportError:
    def fallback(): pass

@dataclass
class Box:
    def method(self):
        def inner(): pass
    if DEBUG:
        def debug(self): pass
    else:
        with lock:
            def locked(self): pass
";
    for file in [
        tokenize(source),
        PythonTokenSource
            .tokenize_structural("pkg/mod.py", source)
            .unwrap(),
    ] {
        let strings = |items: &[&str]| -> Vec<String> {
            items.iter().map(|item| (*item).to_string()).collect()
        };
        assert_eq!(
            contexts(&file),
            [
                (
                    "top".to_string(),
                    strings(&["@cache", "@app.route( \"/x\", )"]),
                    strings(&[])
                ),
                ("guarded".to_string(), strings(&[]), strings(&["try"])),
                (
                    "fallback".to_string(),
                    strings(&[]),
                    strings(&["try", "except"])
                ),
                (
                    "method".to_string(),
                    strings(&[]),
                    strings(&["@dataclass class"])
                ),
                (
                    "inner".to_string(),
                    strings(&[]),
                    strings(&["@dataclass class", "function"])
                ),
                (
                    "debug".to_string(),
                    strings(&[]),
                    strings(&["@dataclass class", "if"])
                ),
                (
                    "locked".to_string(),
                    strings(&[]),
                    strings(&["@dataclass class", "if", "else", "with"])
                ),
            ]
        );
    }
}

fn body_shapes(file: &TokenizedFile) -> Vec<(String, Option<(usize, usize)>)> {
    file.callables
        .as_ref()
        .unwrap()
        .iter()
        .map(|span| {
            (
                span.name.clone(),
                span.body.map(|body| (body.statements, body.flat_calls)),
            )
        })
        .collect()
}

#[test]
fn body_shapes_count_flat_call_statements_without_reading_callee_names() {
    let source = "\
def logs(msg):
    \"\"\"Docstring, not a statement.\"\"\"
    log.info(msg)  # comment
    print(f\"{msg!r} done\", sep=\"\")
    assert_called(msg, *rest, key=VALUE)

def nested(msg):
    log.info(compute(msg))
    log.info(f\"{compute(msg)}\")
    print(lambda: msg)
    print([m for m in msg])
    print(a if msg else b)
    log.info(msg).flush()

def other(msg):
    await_me = log.info(msg)
    return print(msg)
    await notify(msg)
    if msg: print(msg)
    pass

def empty():
    \"\"\"Only a docstring.\"\"\"
";
    for file in [
        tokenize(source),
        PythonTokenSource
            .tokenize_structural("pkg/mod.py", source)
            .unwrap(),
    ] {
        assert_eq!(
            body_shapes(&file),
            [
                ("logs".to_string(), Some((3, 3))),
                ("nested".to_string(), Some((6, 0))),
                ("other".to_string(), Some((5, 0))),
                ("empty".to_string(), Some((0, 0))),
            ]
        );
    }
}

#[test]
fn primitive_spellings_require_complete_direct_annotations() {
    let source = r#"
def sample(a: int, b: str = "", c: Optional[int] = None,
           d: list[str] = [], e: int | str = 1, f: "int" = 1,
           g: pkg.int = 1, h: (int) = 1, i: Custom = 1) -> bool:
    local: float = 1.0
    return True
"#;
    for file in [
        tokenize(source),
        PythonTokenSource
            .tokenize_structural("t.py", source)
            .unwrap(),
    ] {
        assert!(file.error_lines.is_empty(), "{:?}", file.error_lines);
        let recognized: Vec<_> = file
            .tokens
            .iter()
            .filter(|token| token.primitive_spelling)
            .map(|token| token.text.as_str())
            .collect();
        assert_eq!(recognized, ["int", "str", "bool", "float"]);
        assert!(file
            .tokens
            .iter()
            .filter(|token| token.primitive_spelling)
            .all(|token| token.role == mct_core::TokenRole::Type));
    }
}

