//! Token extraction for Rust (issue #207): kinds, literals, trivia, lines,
//! syntax errors and pathological nesting.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{TokenKind, TokenSource, TokenizedFile};
use mct_lang_rust::RustTokenSource;
use TokenKind::{Identifier, Keyword, Literal, Punctuation};

fn tokenize(source: &str) -> TokenizedFile {
    RustTokenSource.tokenize("src/lib.rs", source).unwrap()
}

fn pairs(file: &TokenizedFile) -> Vec<(TokenKind, &str)> {
    file.tokens
        .iter()
        .map(|token| (token.kind, token.text.as_str()))
        .collect()
}

#[test]
fn language_id_matches_the_parser() {
    use mct_core::LanguageParser;
    assert_eq!(
        RustTokenSource.language_id(),
        mct_lang_rust::RustParser.language_id()
    );
}

#[test]
fn keywords_are_told_apart_from_identifiers() {
    let file = tokenize("pub fn add(self, x: i32) -> i32 { if x > 0 { return x; } x }\n");
    assert!(file.error_lines.is_empty());
    let tokens = pairs(&file);
    for keyword in ["fn", "self", "if", "return"] {
        assert!(tokens.contains(&(Keyword, keyword)), "{keyword}");
    }
    assert!(tokens.contains(&(Identifier, "add")));
    assert!(tokens.contains(&(Identifier, "x")));
    // A primitive type is a name, not a keyword.
    assert!(tokens.contains(&(Identifier, "i32")));
    assert!(!tokens.contains(&(Keyword, "add")));
}

#[test]
fn operators_and_punctuation_are_kept() {
    let file = tokenize("fn f() -> u8 { a::b(1) + 2 * c.d }\n");
    let punctuation: Vec<&str> = file
        .tokens
        .iter()
        .filter(|token| token.kind == Punctuation)
        .map(|token| token.text.as_str())
        .collect();
    assert_eq!(
        punctuation,
        ["(", ")", "->", "{", "::", "(", ")", "+", "*", ".", "}"]
    );
}

#[test]
fn every_kind_of_literal_is_a_single_token() {
    let source = concat!(
        "fn f() {\n",
        "    let _ = (1_000u32, 0xFF, 1.5e3f64, true, 'x', '\\n', b'a');\n",
        "    let _ = (\"es\\n\\\"c\", r#\"raw \"q\"\"#, b\"by\", br\"x\", c\"hi\");\n",
        "}\n"
    );
    let file = tokenize(source);
    let literals: Vec<&str> = file
        .tokens
        .iter()
        .filter(|token| token.kind == Literal)
        .map(|token| token.text.as_str())
        .collect();
    assert_eq!(
        literals,
        [
            "1_000u32",
            "0xFF",
            "1.5e3f64",
            "true",
            "'x'",
            "'\\n'",
            "b'a'",
            "\"es\\n\\\"c\"",
            "r#\"raw \"q\"\"#",
            "b\"by\"",
            "br\"x\"",
            "c\"hi\"",
        ]
    );
}

#[test]
fn a_multi_line_string_is_one_token_spanning_its_lines() {
    let source = "fn f() {\n    let s = \"a\nb\nc\";\n    let n = 1;\n}\n";
    let file = tokenize(source);
    let string = file
        .tokens
        .iter()
        .find(|token| token.kind == Literal && token.text.starts_with('"'))
        .unwrap();
    assert_eq!((string.line, string.end_line), (2, 4));
    assert_eq!(&source[string.start_byte..string.end_byte], string.text);
    let one = file.tokens.iter().find(|token| token.text == "1").unwrap();
    assert_eq!((one.line, one.end_line), (5, 5));
}

#[test]
fn comments_doc_comments_and_whitespace_produce_no_tokens() {
    let source = "#!/usr/bin/env run\n//! crate doc\n/// outer doc\n/* block\n   spanning */\nfn f() {} // trailing\n";
    let file = tokenize(source);
    assert!(file.error_lines.is_empty());
    assert_eq!(
        pairs(&file),
        [
            (Keyword, "fn"),
            (Identifier, "f"),
            (Punctuation, "("),
            (Punctuation, ")"),
            (Punctuation, "{"),
            (Punctuation, "}"),
        ]
    );
    // Comment-like text inside a string is part of the literal.
    let file = tokenize("fn f() { let s = \"// not a comment\"; }\n");
    assert!(file
        .tokens
        .iter()
        .any(|token| token.kind == Literal && token.text == "\"// not a comment\""));
}

#[test]
fn visibility_produces_no_tokens() {
    // A visibility decides who may use an item, not what it does: the same
    // function under any visibility is the same token sequence.
    let plain = tokenize("fn f(x: u8) -> u8 { x }\n");
    for source in [
        "pub fn f(x: u8) -> u8 { x }\n",
        "pub(crate) fn f(x: u8) -> u8 { x }\n",
        "pub(super) fn f(x: u8) -> u8 { x }\n",
        "pub(in crate::a) fn f(x: u8) -> u8 { x }\n",
    ] {
        let file = tokenize(source);
        assert!(file.error_lines.is_empty(), "{source}");
        assert_eq!(pairs(&file), pairs(&plain), "{source}");
    }
    // Inside a body as well: a nested item's or a field's visibility.
    let file = tokenize("fn f() { struct S { pub a: u8 } pub fn g() {} }\n");
    assert!(file.error_lines.is_empty());
    assert!(!pairs(&file).contains(&(Keyword, "pub")));
}

#[test]
fn lifetimes_labels_macros_and_paths_are_tokenized() {
    let source = "macro_rules! m { ($x:expr) => { $x }; }\nfn f<'a>(s: &'a str) { 'o: loop { println!(\"{}\", s); break 'o; } }\nuse crate::a::{self, super::b};\n";
    let file = tokenize(source);
    assert!(file.error_lines.is_empty());
    let tokens = pairs(&file);
    assert!(tokens.contains(&(Keyword, "macro_rules!")));
    assert!(tokens.contains(&(Identifier, "$x")));
    assert!(tokens.contains(&(Identifier, "println")));
    assert!(tokens.contains(&(Literal, "\"{}\"")));
    assert!(tokens.contains(&(Keyword, "crate")));
    assert!(tokens.contains(&(Keyword, "super")));
    assert!(tokens.contains(&(Keyword, "loop")));
    assert!(tokens.contains(&(Identifier, "o")));
}

#[test]
fn token_offsets_are_in_order_and_index_the_source() {
    let source = "fn \u{e9}t\u{e9}() { let s = \"\u{1f980}\"; }\n";
    let file = tokenize(source);
    for token in &file.tokens {
        assert_eq!(&source[token.start_byte..token.end_byte], token.text);
    }
    assert!(file
        .tokens
        .windows(2)
        .all(|pair| pair[0].end_byte <= pair[1].start_byte));
    assert!(file
        .tokens
        .iter()
        .any(|token| token.kind == Identifier && token.text == "\u{e9}t\u{e9}"));
}

#[test]
fn a_syntax_error_is_reported_by_line_without_panicking() {
    let source = "fn ok() {}\nfn broken( {\nfn also_ok() {}\n";
    let file = tokenize(source);
    assert!(
        file.error_lines
            .iter()
            .any(|range| range.start <= 2 && range.end >= 2),
        "{:?}",
        file.error_lines
    );
    assert!(file.tokens.iter().any(|token| token.text == "ok"));
    assert!(!tokenize("fn ok() {}\n").tokens.is_empty());
    assert!(tokenize("fn ok() {}\n").error_lines.is_empty());
}

#[test]
fn garbage_and_empty_input_never_panic() {
    assert!(tokenize("").tokens.is_empty());
    let file = tokenize("}}}} \u{0} ;;; @@@ \"unterminated\n");
    assert!(!file.error_lines.is_empty());
}

#[test]
fn pathologically_deep_nesting_does_not_overflow_the_stack() {
    let depth = 10_000;
    let source = format!(
        "fn f() {{ let _ = {}1{}; }}\n",
        "(".repeat(depth),
        ")".repeat(depth)
    );
    let handle = std::thread::Builder::new()
        .stack_size(512 * 1024)
        .spawn(move || tokenize(&source).tokens.len())
        .unwrap();
    assert!(handle.join().unwrap() > 2 * depth);
}

#[test]
fn identifier_roles_and_literal_categories_are_syntactic_positions() {
    use mct_core::LiteralCategory::{Boolean, Character, Number, String};
    use mct_core::TokenRole::{
        Callee, Declaration, Literal as Lit, Member, Parameter, Type, Unclassified,
    };
    let source = "\
pub fn load(order: &Order, scale: i64) -> Vec<u8> {
    let total = order.total.saturating_mul(scale);
    let Point { x, .. } = audit(total);
    println!(\"{}\", x);
    let f = |item| item;
    helpers::emit('c', true, 1.5)
}
";
    let file = tokenize(source);
    let roles: Vec<(&str, mct_core::TokenRole)> = file
        .tokens
        .iter()
        .filter(|token| matches!(token.kind, Identifier | Literal))
        .map(|token| (token.text.as_str(), token.role))
        .collect();
    for expected in [
        ("load", Declaration),
        ("order", Parameter),
        ("scale", Parameter),
        ("Order", Type),
        ("i64", Type),
        ("Vec", Type),
        ("u8", Type),
        ("Point", Type),
        ("total", Member),
        ("saturating_mul", Member),
        ("x", Member),
        ("audit", Callee),
        ("println", Callee),
        ("item", Parameter),
        // Paths and locals are not classified.
        ("helpers", Unclassified),
        ("emit", Unclassified),
        ("f", Unclassified),
        ("\"{}\"", Lit(String)),
        ("'c'", Lit(Character)),
        ("true", Lit(Boolean)),
        ("1.5", Lit(Number)),
    ] {
        assert!(roles.contains(&expected), "{expected:?} in {roles:?}");
    }
    assert!(roles.contains(&("total", Unclassified)), "{roles:?}");
}

#[test]
fn callables_carry_outer_attributes_and_enclosing_constructs() {
    let source = "\
#[inline]
/// docs between attributes
#[must_use]
pub fn top() -> u8 { 1 }

#[cfg(test)]
mod tests {
    #![allow(dead_code)]
    #[test]
    fn case() {}
}

impl Point {
    fn method(&self) {
        let _ = || { fn in_closure() {} };
    }
}

trait Shape { fn area(&self) -> f64; }
";
    let file = tokenize(source);
    let spans = file.callables.unwrap();
    let summary: Vec<(&str, Vec<&str>, Vec<&str>)> = spans
        .iter()
        .map(|span| {
            (
                span.name.as_str(),
                span.decorators.iter().map(String::as_str).collect(),
                span.enclosing.iter().map(String::as_str).collect(),
            )
        })
        .collect();
    assert_eq!(
        summary,
        [
            ("top", vec!["#[inline]", "#[must_use]"], vec![]),
            ("case", vec!["#[test]"], vec!["#[cfg(test)] mod"]),
            ("method", vec![], vec!["impl"]),
            ("in_closure", vec![], vec!["impl", "fn", "closure"]),
            ("area", vec![], vec!["trait"]),
        ]
    );
}

fn body_shapes(file: &TokenizedFile) -> Vec<(String, Option<(usize, usize)>)> {
    file.callables
        .as_ref()
        .unwrap()
        .iter()
        .map(|span| {
            (
                span.name.clone(),
                span.body.map(|body| (body.statements, body.flat_calls)),
            )
        })
        .collect()
}

#[test]
fn body_shapes_count_flat_call_statements_without_reading_callee_names() {
    let source = "\
fn flat(x: u8) {
    // a comment
    log(x);
    self.items.push(x);
    println!(\"{} {}\", x, \"y\");
    #[allow(unused)]
    assert_eq!(x, 1);
    done(&x, Kind::A)
}

fn nested(x: u8) {
    log(compute(x));
    self.items().push(x);
    println!(\"{}\", f(x));
    run(|| x);
    log(if x { 1 } else { 2 });
    send(x)?;
    send(x).await;
}

fn other(x: u8) -> u8 {
    let y = log(x);
    return log(y);
}

trait T {
    fn signature(&self);
}
";
    assert_eq!(
        body_shapes(&tokenize(source)),
        [
            ("flat".to_string(), Some((5, 5))),
            ("nested".to_string(), Some((7, 0))),
            ("other".to_string(), Some((2, 0))),
            ("signature".to_string(), None),
        ]
    );
}

#[test]
fn primitive_spellings_require_complete_direct_annotations() {
    let file = tokenize(
        r#"
type u32 = String;
fn sample(a: u32, b: bool, c: Option<u8>, d: &str,
          e: std::primitive::u16, f: String) -> usize {
    let local: i64 = 1;
    0
}
trait T { fn sample(x: char) -> f64; }
"#,
    );
    assert!(file.error_lines.is_empty(), "{:?}", file.error_lines);
    let recognized: Vec<_> = file
        .tokens
        .iter()
        .filter(|token| token.primitive_spelling)
        .map(|token| token.text.as_str())
        .collect();
    assert_eq!(recognized, ["u32", "bool", "usize", "i64", "char", "f64"]);
    assert!(file
        .tokens
        .iter()
        .filter(|token| token.primitive_spelling)
        .all(|token| token.role == mct_core::TokenRole::Type));
}

sources.benchmarks/token-twins-labels/rust/renam:
//! Wire-format and container helpers that were copied and renamed.
//!
//! Labeled evaluation corpus for the duplicate report (see ../labels.toon).
//! Parsed by mct-cli, never compiled.

// Case rs-real-checksum: one checksum rule for two frame sections.
pub fn header_checksum(bytes: &[u8]) -> u32 {
    let mut sum: u32 = 0;
    for (index, byte) in bytes.iter().enumerate() {
        let weight = (index as u32 % 7) + 1;
        sum = sum.wrapping_add(u32::from(*byte) * weight);
    }
    sum ^ 0xA5A5_A5A5
}

fn payload_checksum(data: &[u8]) -> u32 {
    let mut acc: u32 = 0;
    for (position, value) in data.iter().enumerate() {
        let factor = (position as u32 % 7) + 1;
        acc = acc.wrapping_add(u32::from(*value) * factor);
    }
    acc ^ 0xA5A5_A5A5
}

pub struct Item {
    pub weight: f64,
    pub quantity: u32,
}

pub struct Inventory {
    items: Vec<Item>,
}

pub struct Cart {
    items: Vec<Item>,
}

// Case rs-real-methods: one total-weight rule in two containers of the same items.
impl Inventory {
    pub fn total_weight(&self) -> f64 {
        let mut total = 0.0;
        for item in &self.items {
            total += item.weight * f64::from(item.quantity);
        }
        total
    }
}

impl Cart {
    pub fn total_weight(&self) -> f64 {
        let mut sum = 0.0;
        for entry in &self.items {
            sum += entry.weight * f64::from(entry.quantity);
        }
        sum
    }
}

sources.crates/mct-mcp-server/examples/cache_ben:
//! Query-cache benchmark (issue #16), separate from the functional tests in
//! `tests/query_cache.rs`: indexes a real project (this repository by
//! default), then measures, per path and never mixed,
//!
//! - **exact**: `search_symbols` and `hybrid_search` (lexical) repeated
//!   verbatim — uncached vs exact-hit tokens, and the cache's own lookup
//!   latency (validation included) against the <10 ms target;
//! - **semantic**: `hybrid_search` paraphrase pairs — uncached tokens of the
//!   paraphrase vs its semantic-hit reply, plus embedding and validation
//!   latency.
//!
//! Token reduction is `1 - cached / uncached` with the project's usual
//! `chars / 4` estimate. Exits non-zero when the exact p95 lookup is ≥10 ms or
//! a path's aggregate reduction is <90%.
//!
//! ```sh
//! cargo run --release -p mct-mcp-server --example cache_benchmark [-- <root>]
//! cargo run --release -p mct-mcp-server --features semantic --example cache_benchmark
//! ```
//!
//! Without `--features semantic` the semantic path runs on a deterministic
//! bag-of-words embedder (content words only, so a paraphrase differing in
//! stop words embeds identically) — it measures the cache's cost and token
//! accounting, not a model's notion of similarity. With the feature, the real
//! model decides which paraphrases clear the 0.95 threshold, and misses are
//! reported as such.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use mct_index::{Embedder, ExcludeSet, Index};
use mct_mcp_server::cache::{CacheConfig, CacheStats};
use mct_mcp_server::server::{HybridSearchArgs, MctServer, SearchSymbolsArgs, ServerOptions};
use rmcp::handler::server::wrapper::Parameters;

const REPEATS: usize = 30;
const STOP_WORDS: &[&str] = &[
    "a", "an", "the", "of", "to", "from", "for", "in", "on", "all",
];

const LEXICAL_QUERIES: &[&str] = &[
    "parse",
    "reindex",
    "search symbols",
    "embed query",
    "file tree",
    "context pack",
    "dead code",
    "tool catalog",
    "exclude set",
    "hybrid search",
];

const PARAPHRASES: &[(&str, &str)] = &[
    ("load settings from disk", "load the settings from disk"),
    ("find unused functions", "find all the unused functions"),
    ("parse a manifest file", "parse the manifest file"),
    ("walk the call graph", "walk a call graph"),
    (
        "split identifier into words",
        "split an identifier into the words",
    ),
    (
        "rank symbols by similarity",
        "rank the symbols by similarity",
    ),
];

/// Hashed bag of content words — see the module docs.
struct BagOfWords;

impl BagOfWords {
    fn vector(text: &str) -> Vec<f32> {
        let mut v = vec![0.0f32; 64];
        for word in text
            .split(|c: char| !c.is_alphanumeric())
            .map(str::to_lowercase)
            .filter(|w| !w.is_empty() && !STOP_WORDS.contains(&w.as_str()))
        {
            let h = word.bytes().fold(0xcbf2_9ce4_8422_2325u64, |h, b| {
                (h ^ b as u64).wrapping_mul(0x100_0000_01b3)
            });
            v[(h % 64) as usize] += 1.0;
        }
        v
    }
}

impl Embedder for BagOfWords {
    fn model_id(&self) -> &str {
        "bench/bag-of-words"
    }
    fn embed(&self, texts: &[String]) -> Result<Vec<Vec<f32>>, String> {
        Ok(texts.iter().map(|t| Self::vector(t)).collect())
    }
}

fn embedder() -> Option<Box<dyn Embedder>> {
    if cfg!(feature = "semantic") {
        None // the build's real model, loaded lazily
    } else {
        Some(Box::new(BagOfWords))
    }
}

fn build(root: &Path, cache: CacheConfig) -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(root, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::with_options(
        index,
        registry,
        ServerOptions {
            cache,
            embedder: embedder(),
            shared_cache: None,
            tool_attention: false,
        },
    )
}

fn search_args(query: &str) -> SearchSymbolsArgs {
    SearchSymbolsArgs {
        query: query.to_string(),
        path: None,
        language: None,
        limit: None,
        offset: None,
        snippet_lines: None,
        format: None,
        cache: None,
        detail: None,
        max_tokens: None,
    }
}

fn hybrid_args(query: &str, alpha: f64) -> HybridSearchArgs {
    HybridSearchArgs {
        query: query.to_string(),
        alpha: Some(alpha),
        path: None,
        language: None,
        top_k: None,
        offset: None,
        snippet_lines: None,
        format: None,
        cache: None,
        detail: None,
        max_tokens: None,
    }
}

fn text(result: rmcp::model::CallToolResult) -> String {
    result
        .content
        .first()
        .and_then(|b| b.as_text())
        .map(|t| t.text.clone())
        .unwrap_or_default()
}

fn tokens(text: &str) -> f64 {
    text.chars().count() as f64 / 4.0
}

fn ms(d: Duration) -> f64 {
    d.as_secs_f64() * 1e3
}

fn percentile(samples: &mut [Duration], p: f64) -> Duration {
    samples.sort();
    let i = ((samples.len() as f64 - 1.0) * p).round() as usize;
    samples.get(i).copied().unwrap_or_default()
}

/// The lookup latency one call added to the cache's counters.
fn lookup_delta(before: &CacheStats, after: &CacheStats) -> Option<Duration> {
    (after.lookup_latency.count > before.lookup_latency.count)
        .then(|| after.lookup_latency.total - before.lookup_latency.total)
}

#[derive(Default)]
struct PathReport {
    uncached_tokens: f64,
    cached_tokens: f64,
    hits: usize,
    misses: Vec<String>,
    uncached_call: Vec<Duration>,
    hit_call: Vec<Duration>,
    lookup: Vec<Duration>,
}

impl PathReport {
    fn reduction(&self) -> f64 {
        if self.uncached_tokens == 0.0 {
            0.0
        } else {
            1.0 - self.cached_tokens / self.uncached_tokens
        }
    }

    fn print(&mut self, name: &str) {
        println!("\n## {name} cache");
        println!(
            "hits {}/{}{}",
            self.hits,
            self.hits + self.misses.len(),
            if self.misses.is_empty() {
                String::new()
            } else {
                format!(" — misses: {}", self.misses.join(", "))
            }
        );
        println!(
            "tokens (valid hits only): uncached {:.0}, cached {:.0} → reduction {:.1}%",
            self.uncached_tokens,
            self.cached_tokens,
            self.reduction() * 100.0
        );
        for (label, samples) in [
            ("uncached call", &mut self.uncached_call),
            ("cache-hit call (end to end)", &mut self.hit_call),
            ("cache lookup (incl. validation)", &mut self.lookup),
        ] {
            if samples.is_empty() {
                continue;
            }
            println!(
                "{label}: p50 {:.3} ms, p95 {:.3} ms, max {:.3} ms (n={})",
                ms(percentile(samples, 0.50)),
                ms(percentile(samples, 0.95)),
                ms(percentile(samples, 1.0)),
                samples.len()
            );
        }
    }
}

#[tokio::main]
async fn main() {
    let root = std::env::args()
        .nth(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../.."))
        .canonicalize()
        .unwrap();
    println!("# Query cache benchmark — {}", root.display());
    let start = Instant::now();
    let cached = build(&root, CacheConfig::default());
    let uncached = build(&root, CacheConfig::disabled());
    println!(
        "indexed twice in {:.1} s; semantic side: {}",
        start.elapsed().as_secs_f64(),
        if cfg!(feature = "semantic") {
            "the build's embedding model"
        } else {
            "deterministic bag-of-words embedder (no --features semantic)"
        }
    );

    // ---- exact ----
    let mut exact = PathReport::default();
    for &query in LEXICAL_QUERIES {
        for lexical_hybrid in [false, true] {
            let call = |server: &MctServer| {
                let server = server.clone();
                async move {
                    if lexical_hybrid {
                        text(
                            server
                                .hybrid_search(Parameters(hybrid_args(query, 0.0)))
                                .await
                                .unwrap(),
                        )
                    } else {
                        text(
                            server
                                .search_symbols(Parameters(search_args(query)))
                                .await
                                .unwrap(),
                        )
                    }
                }
            };
            let t = Instant::now();
            let full = call(&cached).await;
            exact.uncached_call.push(t.elapsed());
            for i in 0..REPEATS {
                let before = cached.cache_stats();
                let t = Instant::now();
                let reply = call(&cached).await;
                exact.hit_call.push(t.elapsed());
                let after = cached.cache_stats();
                exact.lookup.extend(lookup_delta(&before, &after));
                if i == 0 {
                    if after.exact_hit > before.exact_hit {
                        exact.hits += 1;
                        exact.uncached_tokens += tokens(&full);
                        exact.cached_tokens += tokens(&reply);
                    } else {
                        exact.misses.push(query.to_string());
                    }
                }
            }
        }
    }

    // ---- semantic ----
    let mut semantic = PathReport::default();
    for &(source, paraphrase) in PARAPHRASES {
        let _ = cached
            .hybrid_search(Parameters(hybrid_args(source, 0.75)))
            .await
            .unwrap();
        let t = Instant::now();
        let full = text(
            uncached
                .hybrid_search(Parameters(hybrid_args(paraphrase, 0.75)))
                .await
                .unwrap(),
        );
        semantic.uncached_call.push(t.elapsed());
        let before = cached.cache_stats();
        let t = Instant::now();
        let reply = text(
            cached
                .hybrid_search(Parameters(hybrid_args(paraphrase, 0.75)))
                .await
                .unwrap(),
        );
        semantic.hit_call.push(t.elapsed());
        let after = cached.cache_stats();
        // The semantic lookup is the second lookup of the call (after the
        // exact miss); the delta covers both, which is what the call paid.
        semantic.lookup.extend(lookup_delta(&before, &after));
        if after.semantic_hit > before.semantic_hit {
            semantic.hits += 1;
            semantic.uncached_tokens += tokens(&full);
            semantic.cached_tokens += tokens(&reply);
        } else {
            semantic.misses.push(format!("`{paraphrase}`"));
        }
    }

    exact.print("Exact");
    semantic.print("Semantic");
    let stats = cached.cache_stats();
    println!("\n## Counters\n{stats}");

    let exact_p95 = percentile(&mut exact.lookup, 0.95);
    let mut failures = Vec::new();
    if exact_p95 >= Duration::from_millis(10) {
        failures.push(format!("exact lookup p95 {:.3} ms ≥ 10 ms", ms(exact_p95)));
    }
    if exact.hits > 0 && exact.reduction() < 0.90 {
        failures.push(format!(
            "exact reduction {:.1}% < 90%",
            exact.reduction() * 100.0
        ));
    }
    if semantic.hits > 0 && semantic.reduction() < 0.90 {
        failures.push(format!(
            "semantic reduction {:.1}% < 90%",
            semantic.reduction() * 100.0
        ));
    }
    if failures.is_empty() {
        println!(
            "\nPASS: exact p95 lookup < 10 ms, ≥90% token reduction on each path's valid hits"
        );
    } else {
        println!("\nFAIL: {}", failures.join("; "));
        std::process::exit(1);
    }
}

