//! MCP compatibility of `detail` / `max_tokens`: the published input schema
//! keeps both optional on every tool that has them, a payload written for the
//! previous schema still works unchanged, and unknown extras are not the
//! server's business to reject.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};

use mct_index::{ExcludeSet, Index};
use mct_mcp_server::server::MctServer;
use serde_json::{json, Value};

const TOOLS: [&str; 5] = [
    "build_context_pack",
    "search_symbols_like",
    "search_symbols",
    "hybrid_search_like",
    "hybrid_search",
];

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/context-pack-app")
}

async fn server() -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(&fixture(), ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::new(index, registry)
}

async fn call(server: &MctServer, tool: &str, args: Value) -> Result<String, String> {
    match server
        .call_read_only_tool(tool, args.as_object().cloned())
        .await
    {
        Ok(r) => Ok(r
            .content
            .iter()
            .filter_map(|b| b.as_text())
            .map(|t| t.text.clone())
            .collect::<Vec<_>>()
            .join("\n")),
        Err(e) => Err(e.message.to_string()),
    }
}

#[tokio::test]
async fn both_arguments_are_published_and_never_required() {
    let server = server().await;
    let catalog = server.tool_catalog();
    for name in TOOLS {
        let tool = catalog
            .iter()
            .find(|t| t.name == name)
            .unwrap_or_else(|| panic!("`{name}` missing from the catalog"));
        let props = tool
            .input_schema
            .get("properties")
            .and_then(Value::as_object)
            .unwrap();
        let required: Vec<&str> = tool
            .input_schema
            .get("required")
            .and_then(Value::as_array)
            .map(|r| r.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        for field in ["detail", "max_tokens"] {
            assert!(props.contains_key(field), "`{name}` lacks `{field}`");
            assert!(!required.contains(&field), "`{name}` requires `{field}`");
        }
        // `max_tokens` is documented as an estimate, never as a model limit.
        let doc = props["max_tokens"]["description"]
            .as_str()
            .unwrap_or("")
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ");
        assert!(
            doc.to_lowercase().contains("estimated") && doc.contains("not a model limit"),
            "`{name}`: {doc}"
        );
    }
}

#[tokio::test]
async fn payloads_written_for_the_previous_schema_still_work_in_both_formats() {
    let server = server().await;
    let old_payloads = [
        ("build_context_pack", json!({"symbol": "place_order"})),
        (
            "search_symbols_like",
            json!({"query": "order", "limit": 3, "snippet_lines": 2, "cache": false}),
        ),
        (
            "hybrid_search_like",
            json!({"query": "order", "alpha": 0.0, "top_k": 3, "cache": false}),
        ),
    ];
    for (tool, payload) in old_payloads {
        for format in ["toon", "text"] {
            let mut args = payload.clone();
            args["format"] = json!(format);
            let text = call(&server, tool, args).await.unwrap();
            assert!(
                !text.is_empty() && !text.contains("Budget:"),
                "{tool} {format}"
            );
            assert!(
                text.contains("place_order") || text.contains("order"),
                "{tool}"
            );
        }
    }
}

#[tokio::test]
async fn a_client_that_sends_the_new_arguments_gets_a_response_in_the_format_it_asked() {
    let server = server().await;
    for (tool, base) in [
        ("build_context_pack", json!({"symbol": "place_order"})),
        ("search_symbols_like", json!({"query": "order"})),
        (
            "hybrid_search_like",
            json!({"query": "order", "alpha": 0.0}),
        ),
    ] {
        let mut toon = base.clone();
        toon["detail"] = json!("summary");
        toon["max_tokens"] = json!(400);
        let toon_text = call(&server, tool, toon.clone()).await.unwrap();
        assert!(
            toon_text.contains("]{"),
            "{tool}: TOON table expected\n{toon_text}"
        );
        toon["format"] = json!("text");
        let plain = call(&server, tool, toon).await.unwrap();
        assert!(
            !plain.contains("]{"),
            "{tool}: plain text expected\n{plain}"
        );
    }
}

#[tokio::test]
async fn an_unknown_field_is_ignored_and_a_wrong_type_is_an_invalid_argument() {
    let server = server().await;
    let ok = call(
        &server,
        "search_symbols_like",
        json!({"query": "order", "from_a_future_client": true}),
    )
    .await;
    assert!(ok.is_ok(), "{ok:?}");
    for bad in [json!({"max_tokens": "many"}), json!({"detail": 3})] {
        let mut args = json!({"query": "order"});
        args.as_object_mut()
            .unwrap()
            .extend(bad.as_object().unwrap().clone());
        assert!(
            call(&server, "search_symbols_like", args).await.is_err(),
            "{bad}"
        );
    }
}

sources.crates/mct-mcp-server/tests/reindex_dela:
//! Black-box checks of `mct-mcp-server --reindex-delay <VALUE>` (issue #196):
//! the real binary over stdio, a real temp project and real filesystem events.
//!
//! Run them with `scripts/unix/reindex-delay-smoke.sh`.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior (see crates/mct-mcp-server/src/ for the
// production policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, Command, Stdio};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::mpsc::{self, Receiver};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use serde_json::{json, Value};

/// Generous so a loaded CI runner does not flake the "appears eventually" checks.
const SETTLE_MARGIN: Duration = Duration::from_secs(30);

/// A fresh canonical temp project (macOS temp dirs are symlinks, and FSEvents
/// reports resolved paths).
fn tempdir() -> PathBuf {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64;
    let dir = std::env::temp_dir().join(format!(
        "mct-reindex-delay-e2e-{}",
        nanos.wrapping_add(COUNTER.fetch_add(1, Ordering::Relaxed))
    ));
    fs::create_dir_all(&dir).unwrap();
    dir.canonicalize().unwrap()
}

struct StdioServer {
    child: Child,
    stdin: ChildStdin,
    lines: Receiver<String>,
    next_id: u64,
}

impl StdioServer {
    fn start(root: &Path, extra_args: &[&str]) -> Self {
        let mut child = Command::new(env!("CARGO_BIN_EXE_mct-mcp-server"))
            .arg("--root")
            .arg(root)
            .args(extra_args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .unwrap();
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        let (tx, lines) = mpsc::channel();
        std::thread::spawn(move || {
            for line in BufReader::new(stdout).lines().map_while(Result::ok) {
                if tx.send(line).is_err() {
                    break;
                }
            }
        });
        let mut server = Self {
            child,
            stdin,
            lines,
            next_id: 0,
        };
        let init = server.request(
            "initialize",
            json!({
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "reindex-delay-e2e", "version": "0"}
            }),
        );
        assert!(init["error"].is_null(), "initialize failed: {init}");
        server.send(&json!({"jsonrpc": "2.0", "method": "notifications/initialized"}));
        server
    }

    fn send(&mut self, message: &Value) {
        writeln!(self.stdin, "{message}").unwrap();
        self.stdin.flush().unwrap();
    }

    fn request(&mut self, method: &str, params: Value) -> Value {
        self.next_id += 1;
        let id = self.next_id;
        self.send(&json!({"jsonrpc": "2.0", "id": id, "method": method, "params": params}));
        loop {
            let line = self
                .lines
                .recv_timeout(Duration::from_secs(120))
                .expect("the server answered in time");
            let message: Value = serde_json::from_str(&line).unwrap();
            if message["id"] == json!(id) {
                return message;
            }
        }
    }

    /// Whether `find_symbol` currently reports a function `name` (a "not found" reply also contains the name, so match the definition line).
    fn finds(&mut self, name: &str) -> bool {
        let response = self.request(
            "tools/call",
            json!({"name": "find_symbol", "arguments": {"name": name, "format": "text"}}),
        );
        response["result"]["content"]
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|block| block["text"].as_str())
            .any(|text| text.contains(&format!("] function {name}")))
    }
}

impl Drop for StdioServer {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// Runs the server expecting it to refuse its arguments; returns stderr.
fn run_rejected(args: &[&str]) -> String {
    let dir = tempdir();
    let output = Command::new(env!("CARGO_BIN_EXE_mct-mcp-server"))
        .arg("--root")
        .arg(&dir)
        .args(args)
        .stdin(Stdio::null())
        .output()
        .unwrap();
    assert!(
        !output.status.success(),
        "{args:?} must exit non-zero, got {:?}",
        output.status
    );
    String::from_utf8_lossy(&output.stderr).into_owned()
}

#[test]
fn a_saved_file_becomes_searchable_only_after_the_delay() {
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn delay_one() {}\n").unwrap();
    let mut server = StdioServer::start(&dir, &["--reindex-delay", "500ms"]);
    assert!(server.finds("delay_one"), "the startup index must be ready");

    let saved = Instant::now();
    fs::write(
        dir.join("lib.rs"),
        "pub fn delay_one() {}\npub fn delay_two() {}\n",
    )
    .unwrap();
    // Not before the delay: asked right after the save, well inside 500 ms.
    if saved.elapsed() < Duration::from_millis(300) {
        assert!(
            !server.finds("delay_two"),
            "the file must not be indexed before the delay elapsed"
        );
    }
    let mut found = false;
    while saved.elapsed() < SETTLE_MARGIN {
        if server.finds("delay_two") {
            found = true;
            break;
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    assert!(
        found,
        "expected the saved file to be indexed after the delay"
    );
    assert!(
        saved.elapsed() >= Duration::from_millis(400),
        "indexed after only {:?}, before the 500ms delay",
        saved.elapsed()
    );
}

#[test]
fn off_never_auto_updates_a_saved_file() {
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn off_one() {}\n").unwrap();
    let mut server = StdioServer::start(&dir, &["--reindex-delay", "off"]);
    assert!(server.finds("off_one"), "the startup index must be ready");

    fs::write(
        dir.join("lib.rs"),
        "pub fn off_one() {}\npub fn off_two() {}\n",
    )
    .unwrap();
    let start = Instant::now();
    while start.elapsed() < Duration::from_secs(5) {
        assert!(
            !server.finds("off_two"),
            "`off` must never auto-index a saved file"
        );
        std::thread::sleep(Duration::from_millis(250));
    }
}

#[test]
fn invalid_delay_values_are_rejected_with_a_clear_message() {
    for value in ["0s", "abc", "-5s", "10x"] {
        // `=` form so a leading `-` is read as the value, not a flag.
        let arg = format!("--reindex-delay={value}");
        let stderr = run_rejected(&[&arg]);
        assert!(
            stderr.contains("reindex-delay") && stderr.contains(value),
            "message for {value:?} must name the flag and the value: {stderr}"
        );
        assert!(
            !stderr.contains("unexpected argument") && !stderr.contains("unrecognized"),
            "{value:?} was rejected as an unknown flag, not as a bad value: {stderr}"
        );
    }
}

#[test]
fn reindex_delay_conflicts_with_the_debounce_flag() {
    let stderr = run_rejected(&["--reindex-delay", "30s", "--reindex-debounce-ms", "100"]);
    assert!(
        stderr.contains("cannot be used with") && stderr.contains("reindex-debounce-ms"),
        "expected a clap conflict message naming both flags: {stderr}"
    );
}

