  plus: ["M12 5v14", "M5 12h14"],
  trash: ["M3 6h18", "M8 6V4h8v2", "M6 6l1 14h10l1-14"],
  edit: ["M12 20h9", "M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"],
  panel: ["M3 4h18v16H3z", "M9 4v16"],
  clock: [dot(12, 12, 10), "M12 7v5l3 2"],
