const cycleTheme = () => { const order = ["dark", "light", "system"]; const next = order[(order.indexOf(store.get("theme", "dark")) + 1) % order.length]; setTheme(next); toast(t("theme.changed", { name: t(`theme.${next}`) })); };

function renderNav() {
