//! Library-pattern regression tests for the shared CSS parser.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::sync::{Arc, LazyLock};

use mct_core::SymbolKind;
use mct_corpus::Corpus;

mod bootstrap;
mod tailwind;

fn corpus() -> &'static Corpus {
    static CORPUS: LazyLock<Corpus> =
        LazyLock::new(|| Corpus::load(Arc::new(crate::CssParser), env!("CARGO_MANIFEST_DIR")));
    &CORPUS
}

/// Every `(line, end_line)` of the `Rule` symbols named `name` in `path`,
/// in file order — a selector may be written many times in one file.
fn rules(path: &str, name: &str) -> Vec<(u32, u32)> {
    let mut out: Vec<_> = corpus()
        .symbols_named(name)
        .into_iter()
        .filter(|(p, s)| p.ends_with(path) && s.kind == SymbolKind::Rule)
        .map(|(_, s)| {
            let line = s.location.line;
            (line, s.location.end_line.unwrap_or(line))
        })
        .collect();
    out.sort_unstable();
    out
}

sources.crates/mct-lang-css/tests/corpus.rs:
//! Long, multi-file fixture corpus (issue #74): the Harbor UI kit — design
//! tokens, a base layer, the page layout, two component files and the
//! dashboard's `app.css` that `@import`s them all — each 300–700 lines. The
//! shared checks (size, line ranges, golden snapshot, index round trip,
//! malformed input) come from `mct-corpus`; the tests below pin the
//! constructs and relations this language is expected to extract.
//!
//! Issue #114 adds one directory per framework scenario, each the app's own
//! CSS with the framework kept as a versioned external dependency:
//! `bootstrap-shop/` (Bootstrap 5.3.8), `tailwind-v3-app/` (the v3.4 input
//! file) and `tailwind-v4-app/` (v4.1 CSS-first configuration). Each
//! scenario's header comment says what the parser is expected to extract.
//! Focused framework assertions live in `src/libraries/{bootstrap,tailwind}/`;
//! this suite retains the shared corpus and index-integration checks.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-css/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{RelationKind, SymbolKind};
use mct_lang_css::CssParser;

mct_corpus::standard_tests!(CssParser);

/// Every `(line, end_line)` of the `Rule` symbols named `name` in `path`,
/// in file order — a selector may be written many times in one file.
fn rules(path: &str, name: &str) -> Vec<(u32, u32)> {
    let mut out: Vec<_> = corpus()
        .symbols_named(name)
        .into_iter()
        .filter(|(p, s)| p.ends_with(path) && s.kind == SymbolKind::Rule)
        .map(|(_, s)| {
            let line = s.location.line;
            (line, s.location.end_line.unwrap_or(line))
        })
        .collect();
    out.sort_unstable();
    out
}

#[test]
fn a_rule_spans_its_declaration_block() {
    // `:root { … }` with 55 custom properties.
    assert_eq!(rules("styles/tokens.css", ":root")[0], (67, 126));
    // Inside `@media (prefers-color-scheme: dark) { … }`.
    assert_eq!(
        rules("styles/tokens.css", ":root:not([data-theme=\"light\"])"),
        [(131, 150)]
    );
    // Every selector of a comma-separated list runs from its own line to
    // the shared closing brace.
    assert_eq!(rules("styles/base.css", "body")[0], (26, 37));
    assert_eq!(rules("styles/base.css", "h1")[0], (27, 37));
    assert_eq!(rules("styles/base.css", "dd")[0], (35, 37));
    assert_eq!(rules("styles/components/controls.css", ".btn")[0], (12, 36));
    // The file-level module ends on the file's last line.
    let tokens = corpus().symbol("styles/tokens.css", "tokens", SymbolKind::Module);
    assert_eq!(
        (tokens.location.line, tokens.location.end_line),
        (1, Some(353))
    );
    let app = corpus().symbol("app.css", "app", SymbolKind::Module);
    assert_eq!((app.location.line, app.location.end_line), (1, Some(361)));
}

#[test]
fn compound_selectors_add_their_atoms_on_the_selector_line() {
    let path = "styles/components/controls.css";
    assert_eq!(rules(path, "input[type=\"search\"].input")[0], (217, 222));
    // The atoms keep their own one-token range.
    assert!(rules(path, "input").contains(&(217, 217)));
    assert!(rules(path, "input[type=\"search\"]").contains(&(217, 217)));
    assert!(rules(path, ".input").contains(&(217, 217)));
    // `.kpi.card` is `.kpi` and `.card` too.
    assert_eq!(rules("app.css", ".kpi.card"), [(92, 94)]);
    assert!(rules("app.css", ".kpi").contains(&(92, 92)));
    assert!(rules("app.css", ".card").contains(&(92, 92)));
    // The grammar applies `[attr]` to the whole descendant chain before
    // it; every atom of that chain is still extracted.
    let path = "app.css";
    let full = ".dashboard__toolbar .btn-group .btn[aria-pressed=\"true\"]";
    assert_eq!(rules(path, full), [(75, 78)]);
    for atom in [".dashboard__toolbar", ".btn-group", ".btn"] {
        assert!(rules(path, atom).contains(&(75, 75)), "{atom}");
    }
    assert!(rules(path, ".data-table").contains(&(223, 223)));
    // A pseudo-class with selector arguments keeps its full text.
    assert_eq!(
        rules(
            "app.css",
            ".onboarding__step:is(.is-current, :focus-within)"
        ),
        [(320, 322)]
    );
}

#[test]
fn escaped_class_names_are_unescaped() {
    // `.md\:hidden` in `@layer utilities` and again in `@media`.
    assert_eq!(
        rules("styles/base.css", ".md:hidden"),
        [(336, 338), (354, 356)]
    );
    assert_eq!(rules("styles/base.css", ".w-1/2"), [(340, 342)]);
    assert!(corpus().symbols_named(".md\\:hidden").is_empty());
}

#[test]
fn a_namespace_prefix_is_not_an_element() {
    // `.chart svg|text` (after `@namespace svg url(…)`) selects `<text>`.
    assert_eq!(rules("app.css", ".chart svg|text"), [(150, 153)]);
    assert_eq!(rules("app.css", "text"), [(150, 150)]);
    assert!(rules("app.css", "svg").is_empty());
    // The only `svg` rule is the real element in the reset.
    let svg: Vec<_> = corpus()
        .symbols_named("svg")
        .into_iter()
        .map(|(p, _)| p)
        .collect();
    assert_eq!(svg, ["styles/base.css"]);
}

#[test]
fn rules_inside_conditional_at_rules_are_extracted() {
    // `@container (min-width: …)` twice.
    assert_eq!(
        rules("styles/layout.css", ".panel__body"),
        [(281, 285), (293, 295)]
    );
    // `@supports not (display: grid)`.
    assert!(rules("styles/layout.css", ".grid").contains(&(230, 233)));
    assert_eq!(rules("styles/layout.css", ".grid > *"), [(235, 238)]);
    // `@media (min-width: 64em)`.
    assert!(rules("styles/layout.css", ".app-shell").contains(&(102, 108)));
    // `@layer reset { … }`.
    assert_eq!(rules("styles/base.css", "*::before"), [(15, 18)]);
}

#[test]
fn at_rule_preludes_and_keyframe_steps_are_not_rules() {
    let c = corpus();
    for name in [
        "from",
        "to",
        "0%",
        "50%",
        "100%",
        "harbor-spin",
        "@keyframes",
        "@font-face",
        "@property",
        "--harbor-progress",
        "Inter",
    ] {
        assert!(
            c.symbols_named(name).is_empty(),
            "`{name}` should not be a symbol: {:?}",
            c.symbols_named(name)
        );
    }
    // tokens.css is almost all at-rules and `:root`: only these selectors.
    let names: Vec<_> = c
        .files
        .iter()
        .filter(|f| f.path == "styles/tokens.css")
        .flat_map(|f| f.parsed.symbols.iter())
        .filter(|s| s.kind == SymbolKind::Rule && s.name != ":root")
        .map(|s| s.name.as_str())
        .collect();
    assert_eq!(
        names,
        [
            ":root:not([data-theme=\"light\"])",
            ":root[data-theme=\"dark\"]",
            ".theme-dark",
            ".theme-light",
        ]
    );
}

#[test]
fn every_import_form_is_an_import_of_the_path_as_written() {
    let c = corpus();
    // `@import "…";`
    let r = c.relation("app.css", "app", RelationKind::Imports, "styles/tokens.css");
    assert_eq!(r.line, 8);
    // `@import url("…");`
    c.relation("app.css", "app", RelationKind::Imports, "styles/layout.css");
    // `@import url("…") screen;` — the media query is not part of the path.
    c.relation(
        "app.css",
        "app",
        RelationKind::Imports,
        "styles/components/surfaces.css",
    );
    // `@import url(base.css);` — unquoted.
    c.relation(
        "styles/layout.css",
        "layout",
        RelationKind::Imports,
        "base.css",
    );
    // `@import "../base.css" screen;` and `./` paths are kept verbatim.
    c.relation(
        "styles/components/controls.css",
        "controls",
        RelationKind::Imports,
        "../base.css",
    );
    c.relation(
        "styles/components/surfaces.css",
        "surfaces",
        RelationKind::Imports,
        "./controls.css",
    );
    // `@namespace svg url(…)` is not an import.
    assert!(!c.has_relation("app", RelationKind::Imports, "http://www.w3.org/2000/svg"));
    // Imports are the only relation CSS produces: 12 in the Harbor kit,
    // 4 in `bootstrap-shop/` and Tailwind v4's `@import "tailwindcss"`, each
    // as written — plus one file-level relation per local `.css` import
    // (15: 11 + 4), named after the imported stylesheet's module.
    assert!(c
        .relations()
        .iter()
        .all(|r| r.kind == RelationKind::Imports));
    assert_eq!(c.relations().len(), 32);
}

#[test]
fn index_finds_a_class_in_every_file_that_styles_it() {
    let index = corpus().index();
    let mut files: Vec<_> = index
        .find_symbol(".btn")
        .unwrap()
        .into_iter()
        .map(|h| h.relative_path)
        .collect();
    files.sort();
    files.dedup();
    assert_eq!(
        files,
        [
            "app.css",
            "bootstrap-shop/catalog.css",
            "bootstrap-shop/checkout.css",
            "styles/components/controls.css",
            "styles/components/surfaces.css",
        ]
    );
    let card: Vec<_> = index
        .find_symbol(".card")
        .unwrap()
        .into_iter()
        .map(|h| (h.relative_path, h.line, h.end_line))
        .collect();
    assert!(card.contains(&("styles/components/surfaces.css".to_string(), 12, Some(20))));
    assert!(card.contains(&("app.css".to_string(), 92, Some(92))));
    let imports = index.find_references("styles/base.css").unwrap();
    assert_eq!(imports.len(), 1);
    assert_eq!(imports[0].relative_path, "app.css");
    assert_eq!(imports[0].line, 9);
}

sources.crates/mct-lang-md/tests/corpus.rs:
//! Long, multi-file fixture corpus (issue #74): the engineering notes of a
//! warehouse team as an Obsidian-style vault — a handbook, an architecture
//! overview and decision log, an operations runbook, an API reference and a
//! glossary — each file 300–600 lines and linking the others by wiki link,
//! section anchor, alias, relative path and embed. The shared checks (size,
//! line ranges, golden snapshot, index round trip, malformed input) come from
//! `mct-corpus`; the tests below pin the note graph Markdown is expected to
//! produce and its documented limits.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-lang-md/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use mct_core::{RelationKind, SymbolKind};
use mct_lang_md::MarkdownParser;

mct_corpus::standard_tests!(
    MarkdownParser,
    malformed_may_parse = "Markdown accepts any input; a malformed note is still a note"
);

use RelationKind::{Imports, References};

fn heading<'a>(path: &str, name: &str) -> &'a mct_core::SymbolRecord {
    corpus().symbol(path, name, SymbolKind::Element)
}

fn parent<'a>(path: &str, name: &str) -> Option<&'a str> {
    heading(path, name).parent.as_deref()
}

fn lines(path: &str, name: &str) -> (u32, Option<u32>) {
    let h = heading(path, name);
    (h.location.line, h.location.end_line)
}

#[test]
fn every_note_is_a_module_named_after_its_file() {
    for (path, name) in [
        ("handbook.md", "handbook"),
        ("glossary.md", "glossary"),
        ("architecture/overview.md", "overview"),
        ("architecture/decisions.md", "decisions"),
        ("operations/runbook.md", "runbook"),
        ("api/reference.md", "reference"),
    ] {
        let note = corpus().symbol(path, name, SymbolKind::Module);
        assert_eq!(
            (note.location.line, note.parent.as_deref()),
            (1, None),
            "{path}"
        );
    }
}

#[test]
fn headings_nest_by_level() {
    assert_eq!(
        parent("handbook.md", "Warehouse engineering handbook"),
        None
    );
    assert_eq!(
        parent("handbook.md", "Who we are"),
        Some("Warehouse engineering handbook")
    );
    assert_eq!(parent("handbook.md", "Team members"), Some("Who we are"));
    assert_eq!(
        parent("handbook.md", "Configuration"),
        Some("Development environment")
    );
    assert_eq!(
        parent("runbook.md", "Orders stuck in RESERVED"),
        Some("Common symptoms")
    );
    assert_eq!(
        parent("glossary.md", "Reservation expiry"),
        Some("Reservation")
    );
    // Headings record the level they were written at.
    assert_eq!(heading("runbook.md", "Common symptoms").level, Some(3));
    assert_eq!(
        heading("runbook.md", "Orders stuck in RESERVED").level,
        Some(4)
    );
}

#[test]
fn setext_and_atx_headings_share_one_hierarchy() {
    // `====` and `----` underlines are levels 1 and 2…
    assert_eq!(
        heading("decisions.md", "Architecture decision log").level,
        Some(1)
    );
    assert_eq!(
        parent("decisions.md", "Decision log"),
        Some("Architecture decision log")
    );
    // …and an ATX `###` under a setext `----` nests inside it.
    assert_eq!(
        parent("decisions.md", "ADR-001 Modular monolith"),
        Some("Decision log")
    );
    // Every ADR has its own `#### Context`, one symbol per ADR.
    let owners: Vec<_> = corpus()
        .symbols_named("Context")
        .into_iter()
        .filter(|(p, _)| p.ends_with("decisions.md"))
        .map(|(_, s)| s.parent.as_deref().unwrap())
        .collect();
    assert_eq!(owners.len(), 10);
    assert!(owners.iter().all(|o| o.starts_with("ADR-")), "{owners:?}");
    // A setext heading after ATX sections closes them.
    assert_eq!(
        parent("handbook.md", "Glossary of acronyms"),
        Some("Warehouse engineering handbook")
    );
}

#[test]
fn a_section_runs_to_the_next_heading_of_the_same_or_higher_level() {
    let (start, end) = lines("handbook.md", "Who we are");
    let (next, _) = lines("handbook.md", "Getting started");
    assert_eq!(end, Some(next - 1));
    assert!(next - start > 30, "the section contains its subsections");
    // The last section runs to the end of the note.
    let (_, end) = lines("glossary.md", "Spanish ↔ English");
    assert_eq!(end, Some(316));
}

#[test]
fn wiki_links_reference_notes_and_their_sections() {
    let c = corpus();
    let from = "Warehouse engineering handbook";
    // `[[architecture/overview|architecture overview]]`: the alias is dropped.
    c.relation("handbook.md", from, References, "overview");
    c.relation("handbook.md", from, References, "glossary");
    // `[[operations/runbook#Post-incident review]]`: note and section.
    c.relation("handbook.md", "Rituals", References, "runbook");
    c.relation("handbook.md", "Rituals", References, "Post-incident review");
    // `[[#Planning]]`: a section of the same note.
    c.relation("handbook.md", "Rituals", References, "Planning");
    // Relative paths resolve against the note's folder.
    c.relation(
        "overview.md",
        "Architecture overview",
        References,
        "decisions",
    );
    c.relation(
        "overview.md",
        "Architecture overview",
        References,
        "runbook",
    );
    // A link to a note that does not exist yet is still a reference.
    c.relation(
        "handbook.md",
        "Notes about these notes",
        References,
        "roadmap-2027",
    );
    // `[[#ADR-008 Canary releases|ADR-008]]` keeps the section, not the alias.
    c.relation(
        "decisions.md",
        "Superseded decisions",
        References,
        "ADR-008 Canary releases",
    );
    assert!(!c.has_relation("Superseded decisions", References, "ADR-008"));
}

#[test]
fn embeds_are_imports() {
    let c = corpus();
    c.relation("handbook.md", "Embedding", Imports, "runbook");
    c.relation("handbook.md", "Embedding", Imports, "On-call rota");
    c.relation("handbook.md", "Embedding", Imports, "context-diagram.svg");
    c.relation("overview.md", "Context", Imports, "context-diagram.svg");
}

#[test]
fn frontmatter_and_inline_tags_are_tag_references() {
    let c = corpus();
    for tag in ["tag:home", "tag:team/warehouse", "tag:onboarding"] {
        c.relation("handbook.md", "handbook", References, tag);
    }
    c.relation(
        "handbook.md",
        "handbook",
        References,
        "alias:Manual de ingeniería",
    );
    c.relation(
        "handbook.md",
        "handbook",
        References,
        "title:Warehouse engineering handbook",
    );
    c.relation("glossary.md", "glossary", References, "alias:Glosario");
    // `#domain` quoted in YAML; the bare `2026` is a number, not a tag.
    c.relation("glossary.md", "glossary", References, "tag:domain");
    assert!(!c.has_relation("glossary", References, "tag:2026"));
    // Inline tags, Unicode included, attach to the enclosing section.
    c.relation(
        "handbook.md",
        "Getting started",
        References,
        "tag:onboarding",
    );
    c.relation(
        "glossary.md",
        "Spanish ↔ English",
        References,
        "tag:almacén",
    );
}

#[test]
fn code_tables_and_look_alikes_are_not_links_or_tags() {
    let c = corpus();
    let targets: Vec<_> = c.relations().into_iter().map(|r| r.to).collect();
    for absent in [
        // Inline code spans and fenced blocks.
        "not-a-link",
        "this-is-not-a-link",
        "tag:not-a-tag",
        "tag:this-is-not-a-tag",
        "note",
        // All-digit tags and URL fragments.
        "tag:1234",
        "tag:install",
    ] {
        assert!(!targets.contains(&absent), "{absent} was extracted");
    }
    // Table cells are not scanned: the team table links the overview, but
    // its section has no relation.
    assert!(!c.has_relation("Team members", References, "overview"));
}

#[test]
fn notes_link_each_other_across_files() {
    let c = corpus();
    assert!(c.name_matched_relation_count() >= 100);
    // A section anchor in another note is resolved by name.
    c.relation(
        "runbook.md",
        "Orders stuck in RESERVED",
        References,
        "ADR-003 Reserve before payment",
    );
    c.relation(
        "reference.md",
        "Carrier webhooks",
        References,
        "ADR-006 One adapter per carrier",
    );
}

#[test]
fn index_answers_note_graph_queries() {
    let index = corpus().index();
    let refs = index.find_references("runbook").unwrap();
    let mut files: Vec<_> = refs.iter().map(|r| r.relative_path.as_str()).collect();
    files.sort();
    files.dedup();
    for file in [
        "api/reference.md",
        "architecture/decisions.md",
        "architecture/overview.md",
        "glossary.md",
        "handbook.md",
    ] {
        assert!(files.contains(&file), "{file} links the runbook: {files:?}");
    }
    let refs = index.find_references("tag:money").unwrap();
    assert!(refs.len() >= 5);
}

