// 06 · Búsqueda inteligente (keyword search over every indexed surface)
import { h, clear, api, isAbort, patchQuery, onQuery, parseHash, listParam, fmt, store, highlight, toast, forget } from "./core.js";
import { icon, pageHead, tabsBar, badge, stateBadge, pager, selectBox, filterGroup, activeChips, emptyState, loading, errorBox, note, drawerButton, kindIcon, noResults } from "./components.js";
import { openSource } from "./code.js";
import { targetOf } from "./palette.js";
import { t } from "./i18n.js";

const SCOPES = ["all", "code", "symbols", "files", "duplicates", "deadCode", "obsidian", "dependencies"];
const TYPE_ICON = { symbol: "func", file: "file", dependency: "graph", code: "code", duplicate: "copy", "dead-code": "skull", note: "note" };
const PAGE_SIZE = 20;

function resultCard(item, query) {
  const where = item.path ? `${item.path}${item.line ? `:${item.line}` : ""}` : "";
  return h("article", { class: "card", style: { display: "flex", gap: "14px", alignItems: "center", marginBottom: "10px" } },
    item.kind ? kindIcon(item.kind) : h("span", { class: "kind-ico tone-primary" }, icon(TYPE_ICON[item.type] || "file", 16)),
    h("div", { style: { minWidth: 0, flex: 1 } },
      h("h3", { class: "ellipsis" }, highlight(item.title, query)),
      where && h("div", { class: "mono muted small ellipsis" }, highlight(where, query)),
      item.snippet && item.snippet !== item.path && h("div", { class: "muted ellipsis" }, highlight(item.snippet, query))),
    h("div", { class: "row hide-sm", style: { justifyContent: "flex-end" } },
      h("span", { class: "badge" }, t(`search.type.${item.type}`)), item.language && badge(item.language),
      item.state && stateBadge(item.state, item.type), item.refs !== undefined && badge(t("search.refs", { n: item.refs })),
      (item.tags || []).slice(0, 2).map((tag) => badge(`#${tag}`, "primary"))),
    h("div", { class: "row" },
      item.path && item.line && h("button", { class: "btn sm", "aria-label": `${t("code.viewSource")}: ${item.title}`, onclick: () => openSource({ path: item.path, line: item.line, language: item.language }) }, icon("code", 14)),
      h("a", { class: "btn sm primary", href: targetOf(item) }, t("search.open"))));
}

export async function render({ root, params: initial, summary }) {
  const input = h("input", { class: "input wide", type: "search", value: initial.get("q") || "", placeholder: t("search.pagePlaceholder"), "aria-label": t("search.pagePlaceholder"), style: { border: 0, background: "transparent", fontSize: "15px" } });
  const results = h("div", {}), tabsHost = h("div", {}), chipsHost = h("div", {}), filtersHost = h("div", {}), meta = h("div", {});
  const drawer = { current: null };
  let sortMode = "relevance", data = null;
  const q = () => parseHash().params;

  const submit = () => {
    const query = input.value.trim();
    if (query) { const r = store.get("recent-searches", []).filter((x) => x !== query); r.unshift(query); store.set("recent-searches", r.slice(0, 8)); }
    patchQuery({ q: query || null, page: null });
  };
  const bar = h("div", { class: "row", style: { background: "var(--surface)", border: "1px solid var(--border)", borderRadius: "10px", padding: "4px 6px 4px 12px", marginBottom: "12px", flexWrap: "nowrap" } },
    icon("search", 20), input, h("button", { class: "icon-btn", "aria-label": t("search.clear"), onclick: () => { input.value = ""; submit(); } }, icon("x", 16)),
    h("button", { class: "btn primary", onclick: submit }, t("search.button")));
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") submit(); });

  const clearFilters = () => { forget("busqueda"); patchQuery({ language: null, kind: null }); };
  function drawFilters(params) {
    const langs = (summary.languages || []).map((l) => ({ value: l.language, label: l.language, count: l.symbols }));
    const kinds = (summary.kinds || []).map((k) => ({ value: k.kind, label: k.kind, count: k.count }));
    clear(filtersHost).append(h("div", { class: "card filters" },
      h("div", { class: "head" }, h("h2", {}, t("filters.title")), h("div", { class: "row" }, h("button", { class: "btn ghost sm", onclick: clearFilters }, t("filters.clear")),
        h("button", { class: "icon-btn only-mobile", "aria-label": t("common.close"), onclick: () => drawer.current?.classList.remove("open") }, icon("x")))),
      filterGroup({ id: "language", label: t("filters.language"), options: langs, selected: listParam(params, "language"), onChange: (v) => patchQuery({ language: v }) }),
      filterGroup({ id: "kind", label: t("filters.symbolKind"), options: kinds, selected: listParam(params, "kind"), onChange: (v) => patchQuery({ kind: v }), search: true, open: false }),
      h("p", { class: "logic" }, t("filters.logic")), note(t("search.unsupported"), "", "info")));
  }

  async function run(params = q()) {
    const query = (params.get("q") || "").trim();
    const scope = params.get("scope") || "all";
    drawFilters(params);
    const values = [...listParam(params, "language"), ...listParam(params, "kind")];
    clear(chipsHost).append(activeChips(values.map((value) => ({ label: value, remove: () => patchQuery({ language: listParam(params, "language").filter((v) => v !== value), kind: listParam(params, "kind").filter((v) => v !== value) }) })), clearFilters) || "");
    clear(tabsHost); clear(meta);
    clear(results).append(loading(t(query ? "search.searching" : "search.loadingAll")));
    const filters = { q: query, language: listParam(params, "language"), kind: listParam(params, "kind") };
    try {
      const [all, scoped] = await Promise.all([api("search", { ...filters, scope: "all" }, "search-all"), scope === "all" ? null : api("search", { ...filters, scope }, "search-scope")]);
      data = all;
      drawTabs(scope);
      const groups = scope === "all" ? all.groups : scoped.groups;
      const total = Object.values(all.groups).reduce((n, g) => n + g.total, 0);
      clear(meta).append(h("div", { class: "row spread", style: { marginBottom: "10px" } },
        h("span", { class: "muted", role: "status" }, t("search.summary", { n: fmt(scope === "all" ? total : all.groups[scope]?.total || 0), ms: all.tookMs })),
        h("div", { class: "row" }, selectBox({ label: t("search.sort"), value: sortMode, options: [["relevance", t("search.sort.relevance")], ["path", t("search.sort.path")], ["title", t("search.sort.title")]], onChange: (v) => { sortMode = v; drawResults(params, scope, groups); } }),
          h("button", { class: "btn sm", onclick: () => { const saved = store.get("saved-searches", []); if (!saved.includes(query)) { saved.unshift(query); store.set("saved-searches", saved.slice(0, 12)); } toast(t("search.savedOk"), "ok"); } }, icon("star", 14), t("search.save")))));
      drawResults(params, scope, groups);
      if (!query) results.prepend(...idleLists());
    } catch (error) { if (!isAbort(error)) clear(results).append(errorBox(error, () => run(params))); }
  }

  function drawTabs(scope) {
    clear(tabsHost).append(tabsBar({ label: t("search.scopes"), active: scope, onSelect: (id) => patchQuery({ scope: id === "all" ? null : id }),
      tabs: SCOPES.map((id) => ({ id, label: t(`search.scope.${id}`), count: id === "all" ? Object.values(data.groups).reduce((n, g) => n + g.total, 0) : data.groups[id]?.total ?? 0 })) }));
  }

  function drawResults(params, scope, groups) {
    const query = params.get("q") || "";
    clear(results);
    if (scope === "all") {
      let any = false;
      for (const id of ["symbols", "files", "code", "duplicates", "deadCode", "obsidian", "dependencies"]) {
        const g = groups[id];
        if (!g?.items.length) continue;
        any = true;
        results.append(h("div", { class: "row spread", style: { margin: "14px 0 8px" } }, h("h2", {}, `${t(`search.scope.${id}`)} (${fmt(g.total)})`),
          g.total > g.items.length && h("button", { class: "btn ghost sm", onclick: () => patchQuery({ scope: id }) }, t("search.seeAll"))),
          g.items.map((item) => resultCard(item, query)));
      }
      if (!any) results.append(emptyState({ title: t("search.noneTitle"), text: t("search.noneText", { q: query }), actions: [h("button", { class: "btn", onclick: () => { input.value = ""; patchQuery({ q: null, language: null, kind: null }); } }, t("search.modify"))] }));
      return;
    }
    let items = groups[scope]?.items || [];
    if (sortMode === "path") items = [...items].sort((a, b) => (a.path || "").localeCompare(b.path || ""));
    if (sortMode === "title") items = [...items].sort((a, b) => a.title.localeCompare(b.title));
    if (!items.length) { results.append(noResults({ onClear: () => patchQuery({ scope: null, language: null, kind: null }) })); return; }
    const page = Math.min(Number(params.get("page") || 0), Math.ceil(items.length / PAGE_SIZE) - 1);
    results.append(items.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE).map((item) => resultCard(item, query)),
      pager({ page, size: PAGE_SIZE, total: items.length, onPage: (p) => patchQuery({ page: p }) }));
    if ((groups[scope]?.total || 0) > items.length) results.append(note(t("search.capped", { n: items.length }), "", "info"));
  }

  function idleLists() {
    const recent = store.get("recent-searches", []), saved = store.get("saved-searches", []);
    const list = (title, values, removable) => (values.length ? h("section", { class: "card", style: { marginBottom: "12px" } }, h("h2", {}, title),
      h("div", { class: "chips" }, values.map((v) => h("span", { class: "chip" }, h("button", { style: { width: "auto", padding: "0 4px" }, onclick: () => { input.value = v; submit(); } }, v),
        removable && h("button", { "aria-label": t("search.removeSaved", { q: v }), onclick: () => { store.set("saved-searches", saved.filter((x) => x !== v)); run(); } }, icon("x", 11)))))) : null);
    return [list(t("search.recent"), recent, false), list(t("search.savedTitle"), saved, true)].filter(Boolean);
  }

  const layout = h("div", { class: "workbench" }, h("aside", { class: "filters-col" }, filtersHost), h("div", {}, bar, h("div", { class: "toolbar" }, drawerButton(() => drawer.current)), chipsHost, tabsHost, meta, results));
  drawer.current = layout.querySelector("aside");
  root.append(pageHead(t("search.title"), t("search.subtitle")), layout);
  await run(initial);
  let last = initial.toString();
  const off = onQuery((params) => { const sig = params.toString(); if (sig !== last) { last = sig; if ((params.get("q") || "") !== input.value.trim()) input.value = params.get("q") || ""; run(params); } });
  return () => off();
}

// 02 · Código indexado: file tree and filters | symbol table | symbol inspector
import { h, clear, api, cancelApi, isAbort, patchQuery, onQuery, parseHash, listParam, fmt, copy, hrefTo, go, forget } from "./core.js";
import { symbolText, symbolTemplate, findingKinds, listText } from "./ai.js";
import { icon, pageHead, tabsBar, segmented, dataTable, pager, kindIcon, kindGroup, kindGroups, badge, searchBox, selectBox, filterGroup, activeChips, noResults,
  emptyState, loading, errorBox, buildTree, treeView, drawerButton, note, stateBadge } from "./components.js";
import { codeBlock, openSource } from "./code.js";
import { t } from "./i18n.js";

const REFS = { any: {}, zero: { maxRefs: 0 }, some: { minRefs: 1 }, many: { minRefs: 5 } };
const FINDINGS = ["any", "duplicate", "dead-code", "anyFinding", "none"];

export async function render({ root, params: initial }) {
  const files = (await api("files")).files;
  const tree = buildTree(files);
  const expanded = new Set();
  const results = h("div", {});
  const inspector = h("div", { class: "inspector-col sticky", hidden: true });
  const filtersHost = h("div", {});
  const tabsHost = h("div", {});
  const chipsHost = h("div", {});
  const quickHost = h("div", { class: "quick-filters" });
  const drawer = { current: null };
  let facets = { kind: [], language: [], ext: [] };
  let selectedId = null, origin = null, originKey = null, disposed = false;
  const compact = matchMedia("(max-width: 1280px)");
  const slot = document.createComment("symbol inspector");
  const dialog = h("dialog", { class: "symbol-dialog", "aria-label": t("code.symbolDetails"), oncancel: (event) => { event.preventDefault(); patchQuery({ sel: null }); } });
  document.body.append(dialog);
  const closeModal = (restore = true) => {
    if (!dialog.open) return;
    dialog.close();
    slot.after(inspector);
    if (restore) {
      const target = origin?.isConnected && origin !== document.body
        ? origin
        : [...root.querySelectorAll("tbody tr")].find((row) => row.dataset.key === originKey);
      target?.focus();
    }
  };
  const positionInspector = () => {
    if (selectedId === null) { closeModal(); return; }
    if (compact.matches) {
      if (!dialog.open) {
        const active = document.activeElement;
        originKey = String(selectedId);
        origin = active?.matches?.("tbody tr") ? active : [...root.querySelectorAll("tbody tr")].find((row) => row.dataset.key === originKey) || active;
        dialog.append(inspector);
        dialog.showModal();
        (inspector.querySelector("button") || dialog).focus();
      }
    } else closeModal();
  };
  compact.addEventListener("change", positionInspector);

  const q = () => parseHash().params;
  const queryFor = (params) => {
    const tab = params.get("tab") || "all";
    const kinds = tab === "all" ? [] : kindGroups().find((group) => group.id === tab)?.kinds || [];
    const finding = params.get("finding") || "any";
    return {
      q: params.get("q") || "", dir: params.get("dir") || "", kind: kinds, language: listParam(params, "language"), ext: listParam(params, "ext"),
      ...REFS[params.get("refs") || "any"], finding: finding === "anyFinding" ? "any" : finding === "any" ? "" : finding,
      sort: params.get("sort") || "name", order: params.get("order") || "asc", page: Number(params.get("page") || 0), size: 50,
    };
  };

  const clearAll = () => { forget("codigo"); patchQuery({ q: null, tab: null, language: null, ext: null, dir: null, refs: null, finding: null, sort: null, order: null }); };

  function drawFilters(params) {
    const dir = params.get("dir") || "";
    clear(filtersHost).append(
      h("div", { class: "card filters" },
        h("div", { class: "head" }, h("h2", {}, t("code.files")), h("button", { class: "icon-btn only-mobile", "aria-label": t("common.close"), onclick: () => drawer.current?.classList.remove("open") }, icon("x"))),
        h("div", {},
          h("button", { class: "btn ghost sm", style: { marginBottom: "4px" }, onclick: () => patchQuery({ dir: null }) }, dir ? t("code.allFiles") : h("strong", {}, t("code.allFiles"))),
          treeView({ root: tree, current: dir, expanded, onSelect: (path) => { patchQuery({ dir: path }); } }))),
      h("div", { class: "card filters", style: { marginTop: "12px" } },
        h("div", { class: "head" }, h("h2", {}, t("filters.title")), h("button", { class: "btn ghost sm", onclick: clearAll }, t("filters.clear"))),
        filterGroup({ id: "language", label: t("filters.language"), options: facets.language.map(([value, count]) => ({ value, label: value, count })), selected: listParam(params, "language"), onChange: (v) => patchQuery({ language: v }) }),
        filterGroup({ id: "ext", label: t("filters.extension"), options: facets.ext.map(([value, count]) => ({ value, label: `.${value || "—"}`, count })), selected: listParam(params, "ext"), onChange: (v) => patchQuery({ ext: v }), search: true, open: false }),
        h("details", { class: "fgroup", open: true }, h("summary", {}, t("filters.references")),
          selectBox({ label: t("filters.references"), value: params.get("refs") || "any", options: Object.keys(REFS).map((id) => [id, t(`filters.refs.${id}`)]), onChange: (v) => patchQuery({ refs: v === "any" ? null : v }), cls: "wide" })),
        h("details", { class: "fgroup", open: true }, h("summary", {}, t("filters.findings")),
          selectBox({ label: t("filters.findings"), value: params.get("finding") || "any", options: FINDINGS.map((id) => [id, t(`filters.finding.${id}`)]), onChange: (v) => patchQuery({ finding: v === "any" ? null : v }), cls: "wide" })),
        h("p", { class: "logic" }, t("filters.logic")),
        note(t("code.unsupported"), "", "info")));
  }

  function drawTabs(params) {
    const present = new Set(facets.kind.map(([kind]) => kindGroup(kind)));
    if (params.get("tab")) present.add(params.get("tab")); // the open tab stays, even when the filters leave it empty
    const groups = kindGroups().filter((group) => present.has(group.id));
    const counts = Object.fromEntries(groups.map((g) => [g.id, facets.kind.filter(([k]) => kindGroup(k) === g.id).reduce((n, [, c]) => n + c, 0)]));
    const total = facets.kind.reduce((n, [, c]) => n + c, 0);
    clear(tabsHost).append(tabsBar({ label: t("code.kinds"), active: params.get("tab") || "all", onSelect: (id) => patchQuery({ tab: id === "all" ? null : id }),
      tabs: [{ id: "all", label: t("code.tab.all"), count: total }, ...groups.map((g) => ({ id: g.id, label: t(`code.tab.${g.id}`), count: counts[g.id] }))] }));
  }

  // Always-visible filters: the same query parameters as the side panel, one click away.
  function drawQuick(params) {
    const pick = (key, label, all, options) => {
      const selected = listParam(params, key);
      const choices = [["", selected.length > 1 ? t("quick.several", { n: selected.length }) : all], ...options.map(([value]) => [value, value])];
      return h("label", { class: "quick-select" }, h("span", { class: "muted small" }, label),
        selectBox({ label, value: selected.length === 1 ? selected[0] : "", options: choices, onChange: (v) => patchQuery({ [key]: v ? [v] : null }) }));
    };
    clear(quickHost).append(
      segmented({ label: t("filters.findings"), value: params.get("finding") || "any", options: FINDINGS.map((id) => [id, t(`quick.finding.${id}`)]), onSelect: (v) => patchQuery({ finding: v === "any" ? null : v }) }),
      segmented({ label: t("filters.references"), value: params.get("refs") || "any", options: Object.keys(REFS).map((id) => [id, t(`quick.refs.${id}`)]), onSelect: (v) => patchQuery({ refs: v === "any" ? null : v }) }),
      pick("language", t("filters.language"), t("quick.allLanguages"), facets.language),
      pick("ext", t("filters.extension"), t("quick.allExtensions"), facets.ext.filter(([value]) => value).map(([value]) => [value])));
  }

  function drawChips(params) {
    const chips = [];
    const add = (key, label, value) => chips.push({ label, remove: () => patchQuery({ [key]: value }) });
    if (params.get("q")) add("q", `“${params.get("q")}”`, null);
    if (params.get("dir")) add("dir", `${t("code.dir")}: ${params.get("dir")}`, null);
    for (const key of ["language", "ext"]) for (const value of listParam(params, key)) chips.push({ label: value, remove: () => patchQuery({ [key]: listParam(params, key).filter((v) => v !== value) }) });
    if (params.get("refs")) add("refs", t(`filters.refs.${params.get("refs")}`), null);
    if (params.get("finding")) add("finding", t(`filters.finding.${params.get("finding")}`), null);
    clear(chipsHost).append(activeChips(chips, clearAll) || "");
  }

  async function refresh(params = q(), full = true) {
    const query = queryFor(params);
    if (full) { drawChips(params); clear(results).append(loading()); }
    try {
      const data = await api("symbols", query, "symbols");
      facets = data.facets;
      drawTabs(params); drawQuick(params); drawFilters(params);
      clear(results);
      if (!data.total) { results.append(noResults({ onClear: clearAll })); return; }
      results.append(h("div", { class: "row", style: { justifyContent: "flex-end", margin: "0 0 8px" } },
        h("button", { class: "btn sm", onclick: () => copy(listText({ title: t("code.tableCaption"), total: data.total, columns: [(r) => r.id, (r) => r.name, (r) => r.kind, (r) => `${r.path}:${r.line}${r.endLine ? `-${r.endLine}` : ""}`], rows: data.items, idKey: "id" }), t("ai.listCopied")) }, icon("copy", 14), t("ai.copyList"))));
      results.append(
        dataTable({
          caption: t("code.tableCaption"), rows: data.items, rowKey: (r) => String(r.id), selected: selectedId === null ? null : String(selectedId), sort: query.sort, order: query.order,
          onSort: (sort, order) => patchQuery({ sort, order }), onSelect: (row) => patchQuery({ sel: row.id }),
          columns: [
            { key: "name", label: t("code.col.name"), sortable: true, render: (r) => h("span", { class: "name" }, kindIcon(r.kind), h("span", { class: "ellipsis" }, r.name)) },
            { key: "kind", label: t("code.col.kind"), sortable: true, render: (r) => r.kind, cls: "hide-sm hide-insp" },
            { key: "language", label: t("code.col.language"), sortable: true, render: (r) => badge(r.language), cls: "hide-sm hide-insp" },
            { key: "path", label: t("code.col.path"), sortable: true, render: (r) => h("span", { class: "path", title: r.path }, r.path) },
            { key: "line", label: t("code.col.line"), sortable: true, num: true, render: (r) => r.line, cls: "hide-sm hide-insp" },
            { key: "refs", label: t("code.col.refs"), sortable: true, num: true, render: (r) => r.refs, cls: "hide-sm hide-insp" },
            { key: "findings", label: t("code.col.findings"), render: (r) => h("span", { class: "row", style: { gap: "4px" } }, r.duplicateGroups > 0 && badge(t("common.duplicate"), "warning"), r.deadCandidate && badge(t("common.deadCode"), "danger")) },
            { key: "actions", label: t("code.col.actions"), render: (r) => h("button", { class: "btn sm", "aria-label": `${t("code.viewSource")}: ${r.name}`, onclick: () => openSource({ path: r.path, line: r.line, language: r.language }) }, icon("code", 14), t("code.view")) },
          ],
        }),
        pager({ page: data.page, size: data.size, total: data.total, onPage: (page) => patchQuery({ page }) }));
    } catch (error) { if (!isAbort(error)) clear(results).append(errorBox(error, () => refresh(params))); }
  }

  async function showSymbol(id) {
    selectedId = id;
    cancelApi("symbol");
    if (id === null) { closeModal(); inspector.hidden = true; root.querySelector(".workbench")?.classList.remove("inspect"); return; }
    root.querySelector(".workbench")?.classList.add("inspect");
    inspector.hidden = false;
    clear(inspector).append(h("div", { class: "card inspector" }, h("button", { class: "btn", onclick: () => patchQuery({ sel: null }) }, t("common.close")), loading()));
    positionInspector();
    try {
      const data = await api("symbol", { id }, "symbol");
      if (disposed || selectedId !== id) return;
      const s = data.symbol;
      const select = (row) => patchQuery({ sel: row.id });
      clear(inspector).append(h("div", { class: "card inspector" },
        h("header", {}, h("div", {}, h("h3", {}, s.name), h("div", { class: "row", style: { marginTop: "6px" } }, kindIcon(s.kind), badge(s.kind), badge(s.language))),
