        assert!(!site
            .navigation
            .files
            .iter()
            .any(|file| file.relative_path == "src/b.rs"));
        assert!(!site
            .navigation
            .symbols
            .iter()
            .any(|symbol| symbol.relative_path == "src/b.rs"));
        assert!(site.navigation.imports.is_empty());
        assert!(site.duplicates.groups.is_empty() && site.duplicates.skipped.is_empty());
