//! Exercises `mct_mcp_server::background::spawn_watcher` directly against a
//! real temp directory and real filesystem events (notify has no mockable
//! clock, so this uses a short debounce and a small real sleep — the
//! accepted pattern for notify-based tests).

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior — this is not production code parsing
// untrusted repo content (see crates/mct-mcp-server/src/ for that policy).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use mct_index::{ExcludeSet, Index};
use mct_mcp_server::background;
use tokio::sync::Mutex;

/// A fresh temp directory, matching the hand-rolled convention already used
/// by `crates/mct-index/tests/reindex.rs` (no `tempfile` dependency needed
/// for a single throwaway dir per test). Canonicalized because on macOS
/// `std::env::temp_dir()` is under `/var/folders/...`, a symlink to
/// `/private/var/folders/...` — FSEvents reports the resolved path, so the
/// watcher's `strip_prefix` against an uncanonicalized root would never
/// match and every event would be (wrongly) filtered out as irrelevant.
fn tempdir() -> std::path::PathBuf {
    let dir = std::env::temp_dir().join(format!("mct-mcp-server-test-{}", uuid_like()));
    fs::create_dir_all(&dir).unwrap();
    dir.canonicalize().unwrap()
}

fn uuid_like() -> u64 {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64;
    nanos.wrapping_add(COUNTER.fetch_add(1, Ordering::Relaxed))
}

const DEBOUNCE: Duration = Duration::from_millis(100);
/// Real filesystem watcher backends (FSEvents/inotify/ReadDirectoryChangesW)
/// add their own OS-level latency on top of the debounce timeout, so tests
/// give it a generous window rather than racing the debounce value exactly.
/// 5s proved too tight on shared/loaded `ubuntu-latest` GitHub Actions
/// runners (inotify event delivery can lag well past the debounce timeout
/// under CPU contention) — 20s keeps the same "poll until true" shape while
/// giving CI enough headroom not to flake.
const SETTLE_MARGIN: Duration = Duration::from_secs(20);

/// Polls `condition` until it's true or `SETTLE_MARGIN` (from `start`)
/// elapses — a single fixed sleep before asserting "it happened" is flaky
/// against real OS watcher latency, so this retries instead.
async fn wait_until(mut condition: impl FnMut() -> bool) -> bool {
    let deadline = tokio::time::Instant::now() + SETTLE_MARGIN;
    loop {
        if condition() {
            return true;
        }
        if tokio::time::Instant::now() >= deadline {
            return false;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

/// A negative check ("nothing happens") cannot poll for its outcome, so it
/// waits a multiple of the latency a real change just showed, never less
/// than this floor and never more than `SETTLE_MARGIN`. The floor covers a
/// probe taken while the machine was still quiet: loaded CI runners have shown
/// notification lag beyond 5 s, so a shorter window could miss a late reindex.
const QUIET_FLOOR: Duration = Duration::from_secs(5);
const LATENCY_MULTIPLE: u32 = 10;

fn unix_seconds() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64
}

/// How long a real change takes to reach the index on this machine right
/// now (it scales with load, like the wait it sizes): a probe file in a
/// scratch project with its own watcher, so the project under test is not
/// disturbed.
async fn watcher_latency() -> Duration {
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    let index = Arc::new(Mutex::new(index));
    let _watcher = background::spawn_watcher(
        Arc::clone(&index),
        registry,
        dir.clone(),
        ExcludeSet::default(),
        DEBOUNCE,
    )
    .unwrap();

    let started = tokio::time::Instant::now();
    fs::write(dir.join("probe.rs"), "pub fn probe_marker() {}\n").unwrap();
    let seen = wait_until(|| {
        index
            .try_lock()
            .map(|guard| !guard.find_symbol("probe_marker").unwrap().is_empty())
            .unwrap_or(false)
    })
    .await;
    assert!(seen, "the probe change never reached the index");
    started.elapsed()
}

#[tokio::test]
async fn watcher_reindexes_after_a_file_change_settles() {
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();

    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    assert!(index.find_symbol("two").unwrap().is_empty());

    let index = Arc::new(Mutex::new(index));
    let _watcher = background::spawn_watcher(
        Arc::clone(&index),
        registry,
        dir.clone(),
        ExcludeSet::default(),
        DEBOUNCE,
    )
    .unwrap();

    fs::write(dir.join("lib.rs"), "pub fn one() {}\npub fn two() {}\n").unwrap();

    let found = wait_until(|| {
        index
            .try_lock()
            .map(|guard| !guard.find_symbol("two").unwrap().is_empty())
            .unwrap_or(false)
    })
    .await;
    assert!(
        found,
        "expected the watcher to have auto-reindexed and picked up `two`"
    );
}

#[tokio::test]
async fn a_change_under_an_excluded_path_does_not_trigger_a_reindex() {
    let quiet_window =
        (watcher_latency().await * LATENCY_MULTIPLE).clamp(QUIET_FLOOR, SETTLE_MARGIN);
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();
    fs::create_dir_all(dir.join("node_modules")).unwrap();

    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    let last_indexed_before = index.status().unwrap().last_indexed_at;
    // `last_indexed_at` has one-second resolution: a reindex in the same
    // second as the setup would leave it unchanged and go unnoticed. Let the
    // clock move on first, so any reindex from here on is visible.
    let setup_second = last_indexed_before.unwrap();
    assert!(
        wait_until(|| unix_seconds() > setup_second).await,
        "the clock did not advance past the setup second"
    );

    let index = Arc::new(Mutex::new(index));
    let _watcher = background::spawn_watcher(
        Arc::clone(&index),
        registry,
        dir.clone(),
        ExcludeSet::default(),
        DEBOUNCE,
    )
    .unwrap();

    // node_modules/** is excluded by default (crates/mct-index/src/exclude.rs)
    // — a change only here must never trigger a reindex, or writing the
    // index's own `.mct-index/` database back to itself would loop forever.
    fs::write(dir.join("node_modules/x.js"), "function ignored() {}\n").unwrap();
    tokio::time::sleep(quiet_window).await;

    let last_indexed_after = index.lock().await.status().unwrap().last_indexed_at;
    assert_eq!(
        last_indexed_before, last_indexed_after,
        "an excluded-only change must not trigger an auto-reindex"
    );
}

#[tokio::test]
async fn watcher_drops_a_deleted_file_and_follows_a_rename_incrementally() {
    let dir = tempdir();
    fs::write(dir.join("keep.rs"), "pub fn keep() {}\n").unwrap();
    fs::write(dir.join("gone.rs"), "pub fn gone() {}\n").unwrap();
    fs::write(dir.join("old.rs"), "pub fn moved() {}\n").unwrap();

    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();

    let index = Arc::new(Mutex::new(index));
    let _watcher = background::spawn_watcher(
        Arc::clone(&index),
        registry,
        dir.clone(),
        ExcludeSet::default(),
        DEBOUNCE,
    )
    .unwrap();

    fs::remove_file(dir.join("gone.rs")).unwrap();
    fs::rename(dir.join("old.rs"), dir.join("new.rs")).unwrap();

    let settled = wait_until(|| {
        index
            .try_lock()
            .map(|guard| {
                guard.find_symbol("gone").unwrap().is_empty()
                    && guard
                        .find_symbol("moved")
                        .unwrap()
                        .iter()
                        .map(|h| h.relative_path.as_str())
                        .eq(["new.rs"])
            })
            .unwrap_or(false)
    })
    .await;
    assert!(
        settled,
        "expected the deletion and the rename to be indexed"
    );
    // An unrelated file is untouched (its function and its file-level module).
    assert_eq!(index.lock().await.find_symbol("keep").unwrap().len(), 2);
}

/// F03: a rule written to `.mctignore` while the server runs drops the file
/// from the index, and removing it brings the file back — though the
/// un-excluded file itself never changes and reports no event.
#[tokio::test]
async fn watcher_applies_ignore_file_edits_without_a_restart() {
    let dir = tempdir();
    fs::write(dir.join("hidden.rs"), "pub fn audit_hidden_symbol() {}\n").unwrap();

    let registry = mct_mcp_server::registry::build_registry();
    // As `main` does: one project rule set, shared by index and watcher.
    let exclude = ExcludeSet::for_project(&dir);
    let mut index = Index::open_in_memory(&dir, exclude.clone()).unwrap();
    index.reindex(&registry, false).unwrap();
    assert!(!index.find_symbol("audit_hidden_symbol").unwrap().is_empty());

    let index = Arc::new(Mutex::new(index));
    let _watcher =
        background::spawn_watcher(Arc::clone(&index), registry, dir.clone(), exclude, DEBOUNCE)
            .unwrap();
    let hidden_is_indexed = |index: &Arc<Mutex<Index>>| {
        index
            .try_lock()
            .ok()
            .map(|guard| !guard.find_symbol("audit_hidden_symbol").unwrap().is_empty())
    };

    fs::write(dir.join(".mctignore"), "hidden.rs\n").unwrap();
    assert!(
        wait_until(|| hidden_is_indexed(&index) == Some(false)).await,
        "expected the new rule to drop hidden.rs"
    );

    fs::write(dir.join(".mctignore"), "# nothing excluded\n").unwrap();
    assert!(
        wait_until(|| hidden_is_indexed(&index) == Some(true)).await,
        "expected the removed rule to bring hidden.rs back"
    );
}

mod changed_paths {
    use std::path::{Path, PathBuf};
    use std::time::Instant;

    use mct_index::ExcludeSet;
    use mct_mcp_server::background::{changed_paths, Changed, MAX_INCREMENTAL_PATHS};
    use notify::event::{AccessKind, CreateKind, Flag, ModifyKind, RemoveKind};
    use notify::{Event, EventKind};
    use notify_debouncer_full::DebouncedEvent;

    fn event(kind: EventKind, paths: &[&str]) -> DebouncedEvent {
        let event = paths
            .iter()
            .fold(Event::new(kind), |e, p| e.add_path(PathBuf::from(p)));
        DebouncedEvent::new(event, Instant::now())
    }

    fn changed(events: &[DebouncedEvent]) -> Changed {
        changed_paths(events, Path::new("/repo"), &ExcludeSet::default())
    }

    #[test]
    fn collects_every_changed_path_once() {
        let events = [
            event(EventKind::Modify(ModifyKind::Any), &["/repo/src/a.rs"]),
            event(EventKind::Create(CreateKind::File), &["/repo/src/b.rs"]),
            event(EventKind::Remove(RemoveKind::File), &["/repo/src/a.rs"]),
            // A rename carries both ends.
            event(
                EventKind::Modify(ModifyKind::Any),
                &["/repo/old.rs", "/repo/new.rs"],
            ),
        ];
        assert_eq!(
            changed(&events),
            Changed::Paths(
                [
                    "/repo/new.rs",
                    "/repo/old.rs",
                    "/repo/src/a.rs",
                    "/repo/src/b.rs"
                ]
                .map(PathBuf::from)
                .to_vec()
            )
        );
    }

    #[test]
    fn reads_excluded_and_outside_paths_are_nothing() {
        let events = [
            event(EventKind::Access(AccessKind::Any), &["/repo/src/a.rs"]),
            event(EventKind::Modify(ModifyKind::Any), &["/repo/target/x.rs"]),
            event(
                EventKind::Modify(ModifyKind::Any),
                &["/repo/.mct-index/index.sqlite3"],
            ),
            event(EventKind::Modify(ModifyKind::Any), &["/elsewhere/a.rs"]),
        ];
        assert_eq!(changed(&events), Changed::Nothing);
    }

    #[test]
    fn a_rescan_request_or_a_huge_batch_is_a_full_reindex() {
        let mut rescan = event(EventKind::Other, &[]);
        rescan.event = rescan.event.clone().set_flag(Flag::Rescan);
        assert_eq!(changed(&[rescan]), Changed::Rescan);

        let many: Vec<DebouncedEvent> = (0..=MAX_INCREMENTAL_PATHS)
            .map(|i| {
                event(
                    EventKind::Modify(ModifyKind::Any),
                    &[&format!("/repo/f{i}.rs")],
                )
            })
            .collect();
        assert_eq!(changed(&many), Changed::Rescan);
    }

    #[test]
    fn an_ignore_file_edit_is_a_full_reindex_only_when_the_rules_change() {
        let dir = super::tempdir();
        std::fs::write(dir.join(".mctignore"), "@import-gitignore\n").unwrap();
        let exclude = ExcludeSet::for_project(&dir);
        let gitignore = dir.join(".gitignore");
        let edit = |path: &Path| {
            let batch = [event(
                EventKind::Modify(ModifyKind::Any),
                &[path.to_str().unwrap()],
            )];
            changed_paths(&batch, &dir, &exclude)
        };

        // The imported `.gitignore` gains a rule: the index must re-walk.
        std::fs::write(&gitignore, "hidden.rs\n").unwrap();
        assert_eq!(edit(&gitignore), Changed::Rescan);
        assert!(exclude.is_excluded("hidden.rs"));

        // Touched again with the same rules: an ordinary, incremental edit.
        assert_eq!(edit(&gitignore), Changed::Paths(vec![gitignore.clone()]));

        // The index's own writes never reload rules or loop.
        assert_eq!(
            edit(&dir.join(".mct-index/index.sqlite3")),
            Changed::Nothing
        );
    }
}

/// `BatchState` (what the watcher thread carries between batches) against a
/// real index, with a failure injected into one incremental update.
mod batch_state {
    use std::fs;
    use std::path::PathBuf;
    use std::time::Duration;

    use mct_core::LanguageRegistry;
    use mct_index::{ExcludeSet, Index, IndexError, ReindexReport};
    use mct_mcp_server::background::{BatchState, Changed, Reindexer};

    /// Applies the first of the paths it's given, then fails — a batch cut
    /// short midway (a locked database, an I/O error) — once.
    struct FailsOnce<'a> {
        index: &'a mut Index,
        armed: bool,
        full_walks: usize,
    }

    impl Reindexer for FailsOnce<'_> {
        fn reindex_paths(
            &mut self,
            registry: &LanguageRegistry,
            paths: &[PathBuf],
        ) -> mct_index::Result<ReindexReport> {
            if std::mem::take(&mut self.armed) {
                self.index.reindex_paths(registry, &paths[..1])?;
                return Err(IndexError::Embedding("injected failure".into()));
            }
            self.index.reindex_paths(registry, paths)
        }

        fn reindex(&mut self, registry: &LanguageRegistry) -> mct_index::Result<ReindexReport> {
            self.full_walks += 1;
            self.index.reindex(registry, false)
        }
    }

    fn names(index: &Index, name: &str) -> usize {
        index.find_symbol(name).unwrap().len()
    }

    #[test]
    fn a_failed_batch_is_recovered_by_the_next_change() {
        let dir = super::tempdir();
        fs::write(dir.join("a.rs"), "pub fn a_old() {}\n").unwrap();
        fs::write(dir.join("b.rs"), "pub fn b_old() {}\n").unwrap();
        let registry = mct_mcp_server::registry::build_registry();
        let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
        index.reindex(&registry, false).unwrap();

        let mut state = BatchState::default();
        let mut target = FailsOnce {
            index: &mut index,
            armed: true,
            full_walks: 0,
        };

        // Both files change; the update fails after applying only `a.rs`.
        fs::write(dir.join("a.rs"), "pub fn a_new() {}\n").unwrap();
        fs::write(dir.join("b.rs"), "pub fn b_new() {}\n").unwrap();
        let batch = Changed::Paths(vec![dir.join("a.rs"), dir.join("b.rs")]);
        assert!(matches!(
            state.apply(&mut target, &registry, batch),
            Some(Err(_))
        ));
        assert!(state.rescan_pending());
        assert_eq!(names(target.index, "b_old"), 1, "b.rs was left stale");

        // The next change names only an unrelated file, yet must bring
        // `b.rs` up to date too: it runs as a full walk.
        fs::write(dir.join("c.rs"), "pub fn c_fn() {}\n").unwrap();
        let batch = Changed::Paths(vec![dir.join("c.rs")]);
        let (mode, _) = state.apply(&mut target, &registry, batch).unwrap().unwrap();
        assert_eq!((mode, target.full_walks), ("full", 1));
        assert!(!state.rescan_pending());
        for (gone, present) in [("a_old", "a_new"), ("b_old", "b_new"), ("x", "c_fn")] {
            assert_eq!(names(target.index, gone), 0, "{gone}");
            assert_eq!(names(target.index, present), 1, "{present}");
        }

        // Back to incremental updates afterwards.
        fs::write(dir.join("c.rs"), "pub fn c2() {}\n").unwrap();
        let batch = Changed::Paths(vec![dir.join("c.rs")]);
        let (mode, _) = state.apply(&mut target, &registry, batch).unwrap().unwrap();
        assert_eq!((mode, target.full_walks), ("incremental", 1));
    }

    #[test]
    fn an_owed_walk_runs_even_without_a_new_change() {
        let dir = super::tempdir();
        fs::write(dir.join("a.rs"), "pub fn a_old() {}\n").unwrap();
        let registry = mct_mcp_server::registry::build_registry();
        let mut index = Index::open_in_memory(&dir, ExcludeSet::default()).unwrap();
        index.reindex(&registry, false).unwrap();
        let mut state = BatchState::default();
        let mut target = FailsOnce {
            index: &mut index,
            armed: true,
            full_walks: 0,
        };

        fs::write(dir.join("a.rs"), "pub fn a_new() {}\n").unwrap();
        fs::write(dir.join("b.rs"), "pub fn b() {}\n").unwrap();
        let batch = Changed::Paths(vec![dir.join("b.rs"), dir.join("a.rs")]);
        assert!(state.apply(&mut target, &registry, batch).unwrap().is_err());

        // What the watcher thread passes when its retry timer fires.
        let (mode, _) = state
            .apply(&mut target, &registry, Changed::Nothing)
            .unwrap()
            .unwrap();
        assert_eq!(mode, "full");
        assert_eq!(names(target.index, "a_new"), 1);
        // Nothing owed any more: an empty batch is a no-op again.
        assert!(state
            .apply(&mut target, &registry, Changed::Nothing)
            .is_none());
    }

    #[test]
    fn retries_back_off_up_to_a_minute() {
        let registry = mct_mcp_server::registry::build_registry();
        struct AlwaysFails;
        impl Reindexer for AlwaysFails {
            fn reindex_paths(
                &mut self,
                _: &LanguageRegistry,
                _: &[PathBuf],
            ) -> mct_index::Result<ReindexReport> {
                Err(IndexError::Embedding("down".into()))
            }
            fn reindex(&mut self, _: &LanguageRegistry) -> mct_index::Result<ReindexReport> {
                Err(IndexError::Embedding("down".into()))
            }
        }
        let mut target = AlwaysFails;
        let mut state = BatchState::default();
        let debounce = Duration::from_millis(1000);
        let mut delays = Vec::new();
        for _ in 0..8 {
            state.apply(&mut target, &registry, Changed::Rescan);
            delays.push(state.retry_delay(debounce).as_millis());
        }
        assert_eq!(delays, [1000, 2000, 4000, 8000, 16000, 32000, 60000, 60000]);
    }
}

sources.crates/mct-mcp-server/tests/reindex_dela:
//! Timing contract of the background watcher (issue #196): an automatic
//! index update runs only after a *quiet period* with no file changes, a new
//! change inside that period restarts it, a burst of saves is one update, and
//! ignored files never cause one.
//!
//! `background::spawn_watcher` takes a concrete `Index` (not a `Reindexer`),
//! so updates are observed two ways: through the index contents (polled with
//! deadlines) and through the watcher's own `tracing` event
//! ("auto-reindex after file changes settled"), captured by a process-wide
//! subscriber that records one timestamp per completed update. The tests
//! share that recorder, so they run one at a time behind `SERIAL`.
//!
//! Real OS watcher backends add latency on top of the debounce, so every
//! "must not have happened yet" check leaves a wide margin before the
//! deadline it protects, and every "must have happened" check polls up to
//! `SETTLE_MARGIN`.

// Test code: an unwrap()/expect() here means a broken test precondition, and
// panicking is the correct behavior (same policy as tests/background_watcher.rs).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex as StdMutex, OnceLock};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use mct_index::{ExcludeSet, Index};
use mct_mcp_server::background;
use tokio::sync::Mutex;
use tracing::field::{Field, Visit};
use tracing::{Event, Subscriber};
use tracing_subscriber::layer::{Context, SubscriberExt};
use tracing_subscriber::{EnvFilter, Layer};

/// The quiet period under test: long enough that the margins below dwarf
/// scheduling noise, short enough to keep the file fast.
const QUIET: Duration = Duration::from_secs(2);
/// Upper bound for "this must eventually happen" polls (CI watcher latency).
const SETTLE_MARGIN: Duration = Duration::from_secs(20);
/// Slack for clock reads taken on either side of an OS event.
const TOLERANCE: Duration = Duration::from_millis(100);

const UPDATE_MSG: &str = "auto-reindex after file changes settled";
const FAILED_MSG: &str = "auto-reindex failed";

// ---------------------------------------------------------------------------
// Update recorder: a global tracing layer (the watcher logs from its own
// `std::thread`, so a thread-local default would not see it).
// ---------------------------------------------------------------------------

static UPDATES: StdMutex<Vec<Instant>> = StdMutex::new(Vec::new());
static FAILURES: StdMutex<usize> = StdMutex::new(0);
static SERIAL: Mutex<()> = Mutex::const_new(());

struct Recorder;

struct MessageOf(String);

impl Visit for MessageOf {
    fn record_debug(&mut self, field: &Field, value: &dyn std::fmt::Debug) {
        if field.name() == "message" {
            self.0 = format!("{value:?}");
        }
    }
}

impl<S: Subscriber> Layer<S> for Recorder {
    fn on_event(&self, event: &Event<'_>, _ctx: Context<'_, S>) {
        let mut message = MessageOf(String::new());
        event.record(&mut message);
        if message.0.contains(UPDATE_MSG) {
            UPDATES.lock().unwrap().push(Instant::now());
        } else if message.0.contains(FAILED_MSG) {
            *FAILURES.lock().unwrap() += 1;
        }
    }
}

fn install_recorder() {
    static ONCE: OnceLock<()> = OnceLock::new();
    ONCE.get_or_init(|| {
        let subscriber = tracing_subscriber::registry()
            .with(Recorder)
            .with(EnvFilter::new("mct_mcp_server=debug"));
        tracing::subscriber::set_global_default(subscriber).unwrap();
    });
}

/// Takes the file-wide lock, resets the recorder and returns the guard.
async fn begin() -> tokio::sync::MutexGuard<'static, ()> {
    let guard = SERIAL.lock().await;
    install_recorder();
    UPDATES.lock().unwrap().clear();
    *FAILURES.lock().unwrap() = 0;
    guard
}

fn updates() -> Vec<Instant> {
    UPDATES.lock().unwrap().clone()
}

fn failures() -> usize {
    *FAILURES.lock().unwrap()
}

// ---------------------------------------------------------------------------
// Helpers copied from tests/background_watcher.rs.
// ---------------------------------------------------------------------------

/// Canonicalized because on macOS the temp dir is a symlink and FSEvents
/// reports resolved paths (see background_watcher.rs).
fn tempdir() -> PathBuf {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64;
    let id = nanos.wrapping_add(COUNTER.fetch_add(1, Ordering::Relaxed));
    let dir = std::env::temp_dir().join(format!("mct-reindex-delay-{id}"));
    fs::create_dir_all(&dir).unwrap();
    dir.canonicalize().unwrap()
}

/// Polls `condition` every 50 ms until true or `SETTLE_MARGIN` elapses.
async fn wait_until(mut condition: impl FnMut() -> bool) -> bool {
    let deadline = tokio::time::Instant::now() + SETTLE_MARGIN;
    loop {
        if condition() {
            return true;
        }
        if tokio::time::Instant::now() >= deadline {
            return false;
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

type Watcher = notify_debouncer_full::Debouncer<
    notify::RecommendedWatcher,
    notify_debouncer_full::RecommendedCache,
>;

struct Fixture {
    dir: PathBuf,
    index: Arc<Mutex<Index>>,
    _watcher: Watcher,
}

/// Indexes `dir` as it is, then starts the watcher with the `QUIET` period.
fn start(dir: &Path, exclude: ExcludeSet) -> Fixture {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(dir, exclude.clone()).unwrap();
    index.reindex(&registry, false).unwrap();
    let index = Arc::new(Mutex::new(index));
    let watcher = background::spawn_watcher(
        Arc::clone(&index),
        registry,
        dir.to_path_buf(),
        exclude,
        QUIET,
    )
    .unwrap();
    Fixture {
        dir: dir.to_path_buf(),
        index,
        _watcher: watcher,
    }
}

impl Fixture {
    /// `Some(true/false)` if `name` is indexed; `None` while an update holds
    /// the index lock.
    fn has(&self, name: &str) -> Option<bool> {
        self.index
            .try_lock()
            .ok()
            .map(|guard| !guard.find_symbol(name).unwrap().is_empty())
    }

    async fn indexed(&self, name: &str) -> bool {
        wait_until(|| self.has(name) == Some(true)).await
    }

    fn save(&self, file: &str, body: &str) {
        let path = self.dir.join(file);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        fs::write(path, body).unwrap();
    }
}

/// The instant of the first completed update that is not before `since`.
fn first_update_after(since: Instant) -> Option<Instant> {
    updates().into_iter().find(|at| *at >= since)
}

// ---------------------------------------------------------------------------
// a) nothing happens before the quiet period elapses.
// ---------------------------------------------------------------------------

#[tokio::test]
async fn no_update_runs_before_the_quiet_period_elapses() {
    let _serial = begin().await;
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();
    let fx = start(&dir, ExcludeSet::default());

    let saved_at = Instant::now();
    fx.save("lib.rs", "pub fn one() {}\npub fn two() {}\n");

    // Halfway through the quiet period: still the old index, no update.
    tokio::time::sleep(QUIET / 2).await;
    assert_eq!(
        fx.has("two"),
        Some(false),
        "index changed before the quiet period elapsed"
    );
    assert!(
        updates().is_empty(),
        "an update ran before the quiet period"
    );

    // Then it does update, and not earlier than the quiet period after the save.
    assert!(fx.indexed("two").await, "the save was never indexed");
    let done = first_update_after(saved_at).expect("update event not recorded");
    assert!(
        done.duration_since(saved_at) + TOLERANCE >= QUIET,
        "update finished {:?} after the save, before the {:?} quiet period",
        done.duration_since(saved_at),
        QUIET
    );
    assert_eq!(failures(), 0);
}

// ---------------------------------------------------------------------------
// b) a second save inside the period restarts it.
// ---------------------------------------------------------------------------

#[tokio::test]
async fn a_second_save_inside_the_period_resets_it() {
    let _serial = begin().await;
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();
    let fx = start(&dir, ExcludeSet::default());

    let first_at = Instant::now();
    fx.save("lib.rs", "pub fn one() {}\npub fn first_save() {}\n");
    tokio::time::sleep(QUIET / 2).await;
    let second_at = Instant::now();
    fx.save(
        "lib.rs",
        "pub fn one() {}\npub fn first_save() {}\npub fn second_save() {}\n",
    );

    // Past the ORIGINAL deadline (first_at + QUIET) but well before the reset
    // one (second_at + QUIET): without a reset the index would be fresh now.
    let original_deadline = first_at + QUIET;
    let probe = original_deadline + QUIET / 4;
    tokio::time::sleep_until(tokio::time::Instant::from_std(probe)).await;
    assert_eq!(
        fx.has("second_save"),
        Some(false),
        "the second save did not reset the quiet period"
    );
    assert_eq!(fx.has("first_save"), Some(false));
    assert!(
        updates().is_empty(),
        "an update ran at the original deadline"
    );

    assert!(fx.indexed("second_save").await, "second save never indexed");
    let done = first_update_after(first_at).expect("update event not recorded");
    assert!(
        done.duration_since(second_at) + TOLERANCE >= QUIET,
        "update ran {:?} after the second save, before the reset period {:?}",
        done.duration_since(second_at),
        QUIET
    );
    assert_eq!(failures(), 0);
}

// ---------------------------------------------------------------------------
// c) a burst of saves is a single update.
// ---------------------------------------------------------------------------

#[tokio::test]
async fn a_burst_of_saves_yields_a_single_update() {
    const SAVES: usize = 8;
    let _serial = begin().await;
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();
    let fx = start(&dir, ExcludeSet::default());

    // 8 saves, 150 ms apart (~1.2 s total, inside one quiet period), spread
    // over a rewritten file and several new files.
    let mut body = String::from("pub fn one() {}\n");
    for n in 0..SAVES {
        body.push_str(&format!("pub fn burst_{n}() {{}}\n"));
        fx.save("lib.rs", &body);
        fx.save(
            &format!("extra_{n}.rs"),
            &format!("pub fn extra_{n}() {{}}\n"),
        );
        tokio::time::sleep(Duration::from_millis(150)).await;
    }

    let last = format!("burst_{}", SAVES - 1);
    let last_extra = format!("extra_{}", SAVES - 1);
    assert!(fx.indexed(&last).await, "burst never indexed");
    assert!(fx.indexed(&last_extra).await, "burst files never indexed");
    // Let any (wrongly) separate follow-up update surface.
    tokio::time::sleep(QUIET * 2).await;

    for n in 0..SAVES {
        assert_eq!(fx.has(&format!("burst_{n}")), Some(true), "burst_{n} lost");
        assert_eq!(fx.has(&format!("extra_{n}")), Some(true), "extra_{n} lost");
    }
    assert_eq!(
        updates().len(),
        1,
        "a burst of {SAVES} saves must produce exactly one update"
    );
    assert_eq!(failures(), 0);
}

// ---------------------------------------------------------------------------
// d) changes arriving while an update is running are applied afterwards.
// ---------------------------------------------------------------------------

/// An update needs the index lock, so holding it from the test stands in for
/// an update in progress (the real one is too fast to race reliably): the
/// watcher must neither run alongside it nor drop what arrives meanwhile.
#[tokio::test]
async fn changes_during_a_running_update_are_applied_afterwards() {
    let _serial = begin().await;
    let dir = tempdir();
    fs::write(dir.join("a.rs"), "pub fn a_old() {}\n").unwrap();
    fs::write(dir.join("b.rs"), "pub fn b_old() {}\n").unwrap();
    let fx = start(&dir, ExcludeSet::default());

    let busy = fx.index.lock().await; // "an update is running"

    // First change settles while the lock is held: the watcher blocks on it.
    fx.save("a.rs", "pub fn a_new() {}\n");
    tokio::time::sleep(QUIET + QUIET / 2).await;
    // A second change arrives while that first update is still waiting/running.
    fx.save("b.rs", "pub fn b_new() {}\n");
    fx.save("c.rs", "pub fn c_new() {}\n");
    tokio::time::sleep(QUIET + QUIET / 2).await;

    assert!(
        updates().is_empty(),
        "an update completed while another held the index"
    );
    assert!(
        busy.find_symbol("a_new").unwrap().is_empty(),
        "index changed while locked"
    );
    drop(busy);

    for name in ["a_new", "b_new", "c_new"] {
        assert!(fx.indexed(name).await, "{name} was lost");
    }
    // Let the queue drain, then check nothing stale survived and no update failed.
    tokio::time::sleep(QUIET * 2).await;
    for gone in ["a_old", "b_old"] {
        assert_eq!(fx.has(gone), Some(false), "{gone} still indexed");
    }
    assert!(!updates().is_empty());
    assert_eq!(failures(), 0);
}

// ---------------------------------------------------------------------------
// e) ignored files never trigger an update.
// ---------------------------------------------------------------------------

#[tokio::test]
async fn files_excluded_by_ignore_rules_never_trigger_an_update() {
    let _serial = begin().await;
    let dir = tempdir();
    fs::write(dir.join("lib.rs"), "pub fn one() {}\n").unwrap();
    fs::write(dir.join(".mctignore"), "@import-gitignore\nsecret.rs\n").unwrap();
    fs::write(dir.join(".gitignore"), "generated/\n").unwrap();
    let exclude = ExcludeSet::for_project(&dir);
    let fx = start(&dir, exclude);

    // One lone event is not enough: write several ignored files, one by one,
    // across more than a full quiet period.
    fx.save("secret.rs", "pub fn secret_one() {}\n");
    fx.save("generated/out.rs", "pub fn generated_one() {}\n");
    tokio::time::sleep(QUIET).await;
    fx.save("secret.rs", "pub fn secret_two() {}\n");
    fx.save("generated/deep/more.rs", "pub fn generated_two() {}\n");
    tokio::time::sleep(QUIET * 2).await;

    assert!(updates().is_empty(), "an ignored file triggered an update");
    for name in ["secret_one", "secret_two", "generated_one", "generated_two"] {
        assert_eq!(fx.has(name), Some(false), "{name} was indexed");
    }

    // Positive control: the watcher is alive, and a normal file does update.
    fx.save("visible.rs", "pub fn visible() {}\n");
    assert!(fx.indexed("visible").await, "control file never indexed");
    assert_eq!(
        updates().len(),
        1,
        "control save must be exactly one update"
    );
    assert_eq!(fx.has("secret_two"), Some(false));
    assert_eq!(failures(), 0);
}

//! `build_context_pack` with `detail` and `max_tokens`: default-compatibility,
//! the three levels, the estimated budget over the whole rendered response,
//! degradation reporting, the minimal response and TOON validity.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};

use mct_index::{EstimatedCounter, ExcludeSet, Index, TokenCounter};
use mct_mcp_server::server::MctServer;
use mct_mcp_server::toon::decode_table;
use serde_json::{json, Value};

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/context-pack-app")
}

async fn server() -> MctServer {
    let registry = mct_mcp_server::registry::build_registry();
    let mut index = Index::open_in_memory(&fixture(), ExcludeSet::default()).unwrap();
    index.reindex(&registry, false).unwrap();
    MctServer::new(index, registry)
}

async fn try_pack(server: &MctServer, args: Value) -> Result<String, String> {
    let args = args.as_object().cloned();
    match server.call_read_only_tool("build_context_pack", args).await {
        Ok(result) => Ok(result
            .content
            .iter()
            .filter_map(|block| block.as_text())
            .map(|t| t.text.clone())
            .collect::<Vec<_>>()
            .join("\n")),
        Err(error) => Err(error.message.to_string()),
    }
}

async fn pack(server: &MctServer, args: Value) -> String {
    try_pack(server, args).await.unwrap()
}

fn est(text: &str) -> usize {
    EstimatedCounter.count(text).value
}

/// Everything before the `Budget:` line the new arguments add.
fn without_budget_line(text: &str) -> String {
    match text.find("\nBudget:") {
        Some(at) => text[..at].to_string(),
        None => text.to_string(),
    }
}

#[tokio::test]
async fn omitting_the_new_arguments_keeps_the_pack_unchanged() {
    let server = server().await;
    for format in ["text", "toon"] {
        let old = pack(
            &server,
            json!({ "symbol": "place_order", "format": format }),
        )
        .await;
