//! Lexical symbol search: identifier word-splitting plus a BM25-ranked FTS5
//! match over the split words, so `parse request` (or `parseRequest`, or
//! `parse_req`) finds `parseRequestBody`/`parse_request_body` — names
//! `find_symbol`'s exact/prefix/fuzzy modes all miss.
//!
//! The split words live in the `symbol_words_fts` table (see `schema.rs`),
//! kept in sync with `symbols` by triggers that call the `mct_split_words`
//! SQL function this module registers on every connection *before*
//! migrations run — the migration's backfill and every later write go
//! through the exact same [`split_identifier`] this module queries with.

use std::collections::HashSet;

use rusqlite::functions::FunctionFlags;
use rusqlite::Connection;

use crate::queries::{push_scope, symbol_hit, BoundValues, ResolvedScope, SymbolHit};
use crate::Result;

/// Name of the scalar SQL function the `symbol_words_fts` triggers call.
pub(crate) const SPLIT_WORDS_FUNCTION: &str = "mct_split_words";

/// Upper bound on the terms taken from one query — every term is one more
/// FTS5 prefix scan, and no real identifier search needs more than a few.
const MAX_QUERY_TERMS: usize = 16;

/// English function words dropped from the any-word fallback only. In the
/// all-words match they are harmless (and sometimes meaningful — `is_test`),
/// but OR-ed in as prefixes (`"a"*`, `"the"*`) they match most of the index
/// and bury the real hits of a plain-language query.
const FALLBACK_STOPWORDS: &[&str] = &[
    "a", "an", "and", "are", "as", "at", "be", "by", "can", "do", "does", "each", "for", "from",
    "has", "have", "how", "in", "into", "is", "it", "its", "of", "on", "or", "that", "the",
    "their", "this", "to", "was", "were", "what", "when", "where", "which", "who", "with",
];

/// Splits an identifier into lowercase words at camelCase, PascalCase,
/// snake_case, kebab-case, whitespace/punctuation and acronym boundaries:
/// `parseRequestBody` → `parse request body`, `HTTPServer` → `http server`,
/// `IOError` → `io error`, `HTTP2Server` → `http2 server`. Digits stay
/// attached to the word they follow (`base64Encode` → `base64 encode`).
/// Pure and total: any input, including an empty or all-punctuation one,
/// yields a (possibly empty) list, never a panic.
pub fn split_identifier(name: &str) -> Vec<String> {
    let chars: Vec<char> = name.chars().collect();
    let mut words = Vec::new();
    let mut current = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if !c.is_alphanumeric() {
            flush(&mut current, &mut words);
            continue;
        }
        if c.is_uppercase() && !current.is_empty() {
            let prev = i.checked_sub(1).and_then(|p| chars.get(p)).copied();
            let next = chars.get(i + 1).copied();
            let after_lower_or_digit = prev.is_some_and(|p| p.is_lowercase() || p.is_numeric());
            let acronym_end =
                prev.is_some_and(char::is_uppercase) && next.is_some_and(char::is_lowercase);
            if after_lower_or_digit || acronym_end {
                flush(&mut current, &mut words);
            }
        }
        current.extend(c.to_lowercase());
    }
    flush(&mut current, &mut words);
    words
}

fn flush(current: &mut String, words: &mut Vec<String>) {
    if !current.is_empty() {
        words.push(std::mem::take(current));
    }
}

/// What gets indexed for `name`: its split words, plus — when it splits into
/// more than one — the words glued back together, so a query typed as one
/// run-together token (`httpserver`, `parserequ`) still prefix-matches.
pub fn search_words(name: &str) -> String {
    let words = split_identifier(name);
    let mut out = words.join(" ");
    if words.len() > 1 {
        out.push(' ');
        out.push_str(&words.concat());
    }
    out
}

/// Registers [`SPLIT_WORDS_FUNCTION`] on `conn`. Must run before
/// `schema::migrations()` (the migration backfills through it) and on every
/// connection that writes `symbols` (the sync triggers call it).
pub(crate) fn register_functions(conn: &Connection) -> rusqlite::Result<()> {
    conn.create_scalar_function(
        SPLIT_WORDS_FUNCTION,
        1,
        FunctionFlags::SQLITE_UTF8 | FunctionFlags::SQLITE_DETERMINISTIC,
        |ctx| {
            let name: Option<String> = ctx.get(0)?;
            Ok(search_words(name.as_deref().unwrap_or_default()))
        },
    )
}

/// Builds the FTS5 `MATCH` expression for `query`, or `None` when it holds no
/// searchable word. Every term comes out of [`split_identifier`] (so it is
/// purely alphanumeric) and is still quoted as an FTS5 phrase — user input
/// can never inject an FTS5 operator (`NEAR`, `OR`, `:`, `^`, `(`...), and a
/// malformed query is simply one with fewer terms, never a syntax error.
fn fts_expression(query: &str, joiner: &str) -> Option<String> {
    fts_terms(split_identifier(query), joiner)
}

/// The any-word fallback's expression: [`fts_expression`] joined by `OR`,
/// minus [`FALLBACK_STOPWORDS`] and single-character words.
fn fallback_expression(query: &str) -> Option<String> {
    let words = split_identifier(query)
        .into_iter()
        .filter(|w| w.chars().count() > 1 && !FALLBACK_STOPWORDS.contains(&w.as_str()))
        .collect();
    fts_terms(words, " OR ")
}

fn fts_terms(words: Vec<String>, joiner: &str) -> Option<String> {
    fts_terms_with(words, joiner, false)
}

/// [`fts_terms`], optionally turning each word of a [`SYNONYM_GROUPS`] group
/// into an `OR` of the whole group: `get file` → `("get"* OR "fetch"* OR
/// "read"*) "file"*`.
fn fts_terms_with(words: Vec<String>, joiner: &str, synonyms: bool) -> Option<String> {
    let quote = |t: &str| format!("\"{}\"*", t.replace('"', "\"\""));
    let terms: Vec<String> = words
        .into_iter()
        .take(MAX_QUERY_TERMS)
        .map(|t| match synonyms.then(|| synonym_group(&t)).flatten() {
            Some(group) => format!(
                "({})",
                group
                    .iter()
                    .map(|s| quote(s))
                    .collect::<Vec<_>>()
                    .join(" OR ")
            ),
            None => quote(&t),
        })
        .collect();
    (!terms.is_empty()).then(|| terms.join(joiner))
}

/// The text inside a `"double-quoted"` query — `hybrid_search`'s
/// exact-phrase mode — or `None` when `query` isn't one: it must start and
/// end with `"` and hold something besides whitespace.
pub fn exact_phrase(query: &str) -> Option<&str> {
    let inner = query.trim().strip_prefix('"')?.strip_suffix('"')?.trim();
    (!inner.is_empty()).then_some(inner)
}

/// The FTS5 expression for an exact phrase: its split words as one quoted
/// FTS5 phrase with no prefix `*` (`"parse request"`), so only names holding
/// those words consecutively, in that order, match. Operators are
/// neutralised exactly as in [`fts_expression`].
fn phrase_expression(phrase: &str) -> Option<String> {
    let words: Vec<String> = split_identifier(phrase)
        .into_iter()
        .take(MAX_QUERY_TERMS)
        .collect();
    (!words.is_empty()).then(|| format!("\"{}\"", words.join(" ").replace('"', "\"\"")))
}

/// Where a hit sits in an exact-phrase ranking, lower is better: 0 when its
/// name *is* the phrase up to case (`"parse_request"` → `parse_request`), 1
/// when it holds the same words in another style (`ParseRequest`), 2 when
/// the phrase appears literally inside it (`parse_request_body`), 3 when
/// only the word sequence matches (`ParseRequestBody`). Punctuation around
/// the phrase is ignored, so a pasted `parse_request()` still ranks
/// `parse_request` at 0.
pub(crate) fn phrase_tier(name: &str, phrase: &str) -> u8 {
    let name_lower = name.to_lowercase();
    let phrase_lower = phrase
        .trim_matches(|c: char| !c.is_alphanumeric() && c != '_')
        .to_lowercase();
    if name_lower == phrase_lower {
        0
    } else if split_identifier(name) == split_identifier(phrase) {
        1
    } else if name_lower.contains(&phrase_lower) {
        2
    } else {
        3
    }
}

/// Verbs developers use interchangeably in names. Only `hybrid_search`'s
/// lexical side expands them (see [`LexicalOptions::synonyms`]);
/// `search_symbols` stays literal.
const SYNONYM_GROUPS: &[&[&str]] = &[
    &["get", "fetch", "read"],
    &["set", "update", "write"],
    &["delete", "remove"],
];

fn synonym_group(word: &str) -> Option<&'static [&'static str]> {
    SYNONYM_GROUPS.iter().copied().find(|g| g.contains(&word))
}

/// Extra behaviour for the lexical ranking `hybrid_search` fuses; the
/// default (all off) is exactly [`search_symbols`].
#[derive(Debug, Clone, Copy, Default)]
pub(crate) struct LexicalOptions {
    /// Also match [`SYNONYM_GROUPS`] alternatives of each query word.
    /// Literal matches still rank before synonym-only ones in their tier.
    pub synonyms: bool,
    /// Read `Type::method` / `module.function` as "`method`, preferably
    /// inside `Type`" — see [`qualified_parts`].
    pub qualified: bool,
}

/// Splits a qualified name (`Index::hybrid_search`, `toon.decode_table`,
/// `a->b`) into its qualifier words and its last segment, or `None` when
/// `query` isn't one: it must be a single whitespace-free token of
/// identifier segments.
pub(crate) fn qualified_parts(query: &str) -> Option<(Vec<String>, &str)> {
    let query = query.trim();
    if query.is_empty() || query.contains(char::is_whitespace) {
        return None;
    }
    let segments: Vec<&str> = query
        .split("::")
        .flat_map(|s| s.split("->"))
        .flat_map(|s| s.split('.'))
        .collect();
    let (last, qualifiers) = segments.split_last()?;
    let is_ident = |s: &&str| !s.is_empty() && s.chars().all(|c| c.is_alphanumeric() || c == '_');
    if qualifiers.is_empty() || !is_ident(last) || !qualifiers.iter().all(is_ident) {
        return None;
    }
    let words = qualifiers
        .iter()
        .flat_map(|q| split_identifier(q))
        .collect();
    Some((words, last))
}

/// How well a hit's name matches the query, before BM25 is consulted:
/// lower is better. Guarantees an exact name always ranks first.
fn match_tier(name: &str, query_lower: &str, query_compact: &str) -> u8 {
    let name_lower = name.to_lowercase();
    let name_compact = split_identifier(name).concat();
    if name_lower == query_lower {
        0
    } else if !query_compact.is_empty() && name_compact == query_compact {
        1
    } else if name_lower.starts_with(query_lower)
        || (!query_compact.is_empty() && name_compact.starts_with(query_compact))
    {
        2
    } else {
        3
    }
}

/// Every symbol whose split name matches `query`, narrowed to `scope`, best
/// match first: exact (case-insensitive) name, then the same words in any
/// casing/separator style, then a name prefix, then the rest — each tier
/// ordered by BM25, ties broken by path and line. Every query word must
/// prefix-match one of the name's words; when that finds nothing and the
/// query has several words, any-word matching is tried instead.
pub fn search_symbols(
    conn: &Connection,
    query: &str,
    scope: ResolvedScope<'_>,
) -> Result<Vec<SymbolHit>> {
    search_symbols_with(conn, query, scope, LexicalOptions::default())
}

/// [`search_symbols`] with the [`LexicalOptions`] `hybrid_search` uses.
/// With a qualified query, only its last segment is searched for, and hits
/// whose parent or path contains every qualifier word rank first in their
/// tier; with synonyms, literal matches rank before synonym-only ones.
pub(crate) fn search_symbols_with(
    conn: &Connection,
    query: &str,
    scope: ResolvedScope<'_>,
    options: LexicalOptions,
) -> Result<Vec<SymbolHit>> {
    let (qualifier, query) = match options.qualified.then(|| qualified_parts(query)).flatten() {
        Some((words, last)) => (words, last),
        None => (Vec::new(), query),
    };
    let Some(all_terms) = fts_expression(query, " ") else {
        return Ok(Vec::new());
    };
    // (bm25, synonym-only, hit)
    let mut ranked: Vec<(f64, bool, SymbolHit)> = run_match(conn, &all_terms, scope)?
        .into_iter()
        .map(|(score, hit)| (score, false, hit))
        .collect();
    let all_expanded = fts_terms_with(split_identifier(query), " AND ", true)
        .filter(|e| options.synonyms && e.contains(" OR "));
    if let Some(all_expanded) = all_expanded {
        let mut seen: HashSet<(String, u32, u32)> = ranked
            .iter()
            .map(|(_, _, h)| (h.relative_path.clone(), h.line, h.column))
            .collect();
        for (score, hit) in run_match(conn, &all_expanded, scope)? {
            if seen.insert((hit.relative_path.clone(), hit.line, hit.column)) {
                ranked.push((score, true, hit));
            }
        }
    }
    if ranked.is_empty() {
        let fallback_words: Vec<String> = split_identifier(query)
            .into_iter()
            .filter(|w| w.chars().count() > 1 && !FALLBACK_STOPWORDS.contains(&w.as_str()))
            .collect();
        let any_term = if options.synonyms {
            fts_terms_with(fallback_words, " OR ", true)
        } else {
            fallback_expression(query)
        };
        if let Some(any_term) = any_term.filter(|e| *e != all_terms) {
            ranked = run_match(conn, &any_term, scope)?
                .into_iter()
                .map(|(score, hit)| (score, false, hit))
                .collect();
        }
    }

    let query_lower = query.trim().to_lowercase();
    let query_compact = split_identifier(query).concat();
    let mut tiered: Vec<(u8, bool, bool, f64, SymbolHit)> = ranked
        .into_iter()
        .map(|(score, synonym_only, hit)| {
            (
                match_tier(&hit.name, &query_lower, &query_compact),
                outside_qualifier(&qualifier, &hit),
                synonym_only,
                score,
                hit,
            )
        })
        .collect();
    tiered.sort_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| a.1.cmp(&b.1))
            .then_with(|| a.2.cmp(&b.2))
            .then_with(|| a.3.total_cmp(&b.3))
            .then_with(|| a.4.relative_path.cmp(&b.4.relative_path))
            .then_with(|| a.4.line.cmp(&b.4.line))
    });
    Ok(tiered.into_iter().map(|t| t.4).collect())
}

/// Whether `hit` lies outside a qualified query's qualifier: some qualifier
/// word is in neither its path nor its parent. Never, with no qualifier.
fn outside_qualifier(qualifier: &[String], hit: &SymbolHit) -> bool {
    if qualifier.is_empty() {
        return false;
    }
    let mut context = split_identifier(&hit.relative_path);
    context.extend(
        hit.parent
            .as_deref()
            .map(split_identifier)
            .unwrap_or_default(),
    );
    !qualifier.iter().all(|w| context.contains(w))
}

/// `hybrid_search`'s exact-phrase lexical side: every symbol whose split
/// name holds `phrase`'s words consecutively and in order (no prefix
/// matching, no synonyms, no any-word fallback), narrowed to `scope`, ranked
/// by [`phrase_tier`], then — for a qualified phrase (`Index::open`) — hits
/// inside the qualifier first, then BM25, path and line.
pub(crate) fn search_phrase(
    conn: &Connection,
    phrase: &str,
    scope: ResolvedScope<'_>,
) -> Result<Vec<SymbolHit>> {
    let (qualifier, phrase) = match qualified_parts(phrase) {
        Some((words, last)) => (words, last),
        None => (Vec::new(), phrase),
    };
    let Some(expression) = phrase_expression(phrase) else {
        return Ok(Vec::new());
    };
    let mut tiered: Vec<(u8, bool, f64, SymbolHit)> = run_match(conn, &expression, scope)?
        .into_iter()
        .map(|(score, hit)| {
            (
                phrase_tier(&hit.name, phrase),
                outside_qualifier(&qualifier, &hit),
                score,
                hit,
            )
        })
        .collect();
    tiered.sort_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| a.1.cmp(&b.1))
            .then_with(|| a.2.total_cmp(&b.2))
            .then_with(|| a.3.relative_path.cmp(&b.3.relative_path))
            .then_with(|| a.3.line.cmp(&b.3.line))
    });
    Ok(tiered.into_iter().map(|t| t.3).collect())
}

/// Most string-literal hits [`search_literals`] returns.
pub const MAX_LITERAL_HITS: usize = 200;

/// A prose string literal holding an exact phrase.
#[derive(Debug, Clone)]
pub struct LiteralHit {
    pub relative_path: String,
    pub language: String,
    pub line: u32,
    /// The literal's stored text (normalised, at most
    /// `mct_core::MAX_LITERAL_CHARS` chars).
    pub text: String,
    /// Name and kind of the innermost symbol enclosing the literal, if any.
    pub symbol: Option<(String, String)>,
}

/// Every indexed string literal holding `phrase`'s words consecutively and
/// in order — case- and diacritic-insensitive, punctuation ignored (the
/// `literals_fts` tokenizer) — narrowed to `scope`, best BM25 first, then
/// path and line. At most [`MAX_LITERAL_HITS`].
pub(crate) fn search_literals(
    conn: &Connection,
    phrase: &str,
    scope: ResolvedScope<'_>,
) -> Result<Vec<LiteralHit>> {
    if !phrase.chars().any(char::is_alphanumeric) {
        return Ok(Vec::new());
    }
    let mut sql = String::from(
        "SELECT f.relative_path, f.language, l.line, l.text, s.name, s.kind
         FROM literals_fts
         JOIN literals l ON l.id = literals_fts.rowid
         JOIN files f ON f.id = l.file_id
         LEFT JOIN symbols s ON s.id = l.symbol_id
         WHERE literals_fts MATCH ?1",
    );
    let mut bound: BoundValues = vec![Box::new(format!("\"{}\"", phrase.replace('"', "\"\"")))];
    push_scope(&mut sql, &mut bound, scope);
    sql.push_str(&format!(
        " ORDER BY bm25(literals_fts), f.relative_path, l.line LIMIT {MAX_LITERAL_HITS}"
    ));

    let mut stmt = conn.prepare_cached(&sql)?;
    let params: Vec<&dyn rusqlite::ToSql> = bound.iter().map(|b| b.as_ref()).collect();
    let rows = stmt
        .query_map(params.as_slice(), |row| {
            let name: Option<String> = row.get(4)?;
            let kind: Option<String> = row.get(5)?;
            Ok(LiteralHit {
                relative_path: row.get(0)?,
                language: row.get(1)?,
                line: row.get(2)?,
                text: row.get(3)?,
                symbol: name.zip(kind),
            })
        })?
        .collect::<rusqlite::Result<_>>()?;
    Ok(rows)
}

fn run_match(
    conn: &Connection,
    fts_query: &str,
    scope: ResolvedScope<'_>,
) -> Result<Vec<(f64, SymbolHit)>> {
    let mut sql = String::from(
        "SELECT s.name, s.kind, f.language, f.relative_path, s.line, s.column, s.parent, s.end_line, s.level, s.id,
                bm25(symbol_words_fts)
         FROM symbol_words_fts
         JOIN symbols s ON s.id = symbol_words_fts.rowid
         JOIN files f ON f.id = s.file_id
         WHERE symbol_words_fts MATCH ?1",
    );
    let mut bound: BoundValues = vec![Box::new(fts_query.to_string())];
    push_scope(&mut sql, &mut bound, scope);

    let mut stmt = conn.prepare_cached(&sql)?;
    let params: Vec<&dyn rusqlite::ToSql> = bound.iter().map(|b| b.as_ref()).collect();
    let rows = stmt
        .query_map(params.as_slice(), |row| {
            Ok((row.get::<_, f64>(10)?, symbol_hit(row)?))
        })?
        .collect::<rusqlite::Result<_>>()?;
    Ok(rows)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn split(name: &str) -> String {
        split_identifier(name).join(" ")
    }

    #[test]
    fn splits_every_identifier_convention() {
        assert_eq!(split("parseRequestBody"), "parse request body");
        assert_eq!(split("ParseRequestBody"), "parse request body");
        assert_eq!(split("parse_request_body"), "parse request body");
        assert_eq!(split("parse-request-body"), "parse request body");
        assert_eq!(split("PARSE_REQUEST_BODY"), "parse request body");
        assert_eq!(split("parse request  body"), "parse request body");
    }

    #[test]
    fn splits_acronyms_and_digits() {
        assert_eq!(split("HTTPServer"), "http server");
        assert_eq!(split("IOError"), "io error");
        assert_eq!(split("getHTTPResponse"), "get http response");
        assert_eq!(split("HTTP2Server"), "http2 server");
        assert_eq!(split("base64Encode"), "base64 encode");
        assert_eq!(split("utf8"), "utf8");
    }

    #[test]
    fn degenerate_input_yields_no_words_not_a_panic() {
        assert!(split_identifier("").is_empty());
        assert!(split_identifier("__").is_empty());
        assert!(split_identifier("+=").is_empty());
        assert_eq!(split("ÄrgerÖl"), "ärger öl");
    }

    #[test]
    fn indexed_words_include_the_glued_form_only_for_multi_word_names() {
        assert_eq!(search_words("HTTPServer"), "http server httpserver");
        assert_eq!(search_words("main"), "main");
        assert_eq!(search_words(""), "");
    }

    #[test]
    fn fts_expression_neutralises_operators() {
        assert_eq!(
            fts_expression("a OR b NEAR(c) \"d\" e:f ^g *", " ").as_deref(),
            Some("\"a\"* \"or\"* \"b\"* \"near\"* \"c\"* \"d\"* \"e\"* \"f\"* \"g\"*")
        );
        assert_eq!(fts_expression("\"*():^", " "), None);
    }

    #[test]
    fn fallback_drops_stopwords_and_single_letters() {
        assert_eq!(
            fallback_expression("is this a test file").as_deref(),
            Some("\"test\"* OR \"file\"*")
        );
        assert_eq!(fallback_expression("the a of"), None);
        // All-words matching keeps them: `is_test` is a real name.
        assert_eq!(
            fts_expression("is test", " ").as_deref(),
            Some("\"is\"* \"test\"*")
        );
    }

    #[test]
    fn synonym_expansion_ors_the_whole_group_and_stays_quoted() {
        assert_eq!(
            fts_terms_with(split_identifier("getFile"), " AND ", true).as_deref(),
            Some("(\"get\"* OR \"fetch\"* OR \"read\"*) AND \"file\"*")
        );
        assert_eq!(
            fts_terms_with(split_identifier("remove x"), " ", false).as_deref(),
            Some("\"remove\"* \"x\"*")
        );
    }

    #[test]
    fn qualified_names_split_into_qualifier_words_and_last_segment() {
        let parts = |q| qualified_parts(q).map(|(w, last)| (w.join(" "), last.to_string()));
        assert_eq!(
            parts("Index::hybrid_search"),
            Some(("index".into(), "hybrid_search".into()))
        );
        assert_eq!(
            parts("mct_core::SymbolRecord"),
            Some(("mct core".into(), "SymbolRecord".into()))
        );
        assert_eq!(
            parts("toon.decode_table"),
            Some(("toon".into(), "decode_table".into()))
        );
        assert_eq!(parts("self->visit"), Some(("self".into(), "visit".into())));
        for not_qualified in [
            "hybrid_search",
            "Index hybrid",
            "a::",
            "::a",
            "a..b",
            "e.g.",
            "",
        ] {
            assert_eq!(parts(not_qualified), None, "{not_qualified:?}");
        }
    }

    #[test]
    fn only_a_fully_quoted_query_is_an_exact_phrase() {
        assert_eq!(exact_phrase("\"parse request\""), Some("parse request"));
        assert_eq!(exact_phrase("  \" Index::open \" "), Some("Index::open"));
        for not_phrase in [
            "parse request",
            "\"parse",
            "parse\"",
            "\"\"",
            "\"  \"",
            "\"",
            "",
        ] {
            assert_eq!(exact_phrase(not_phrase), None, "{not_phrase:?}");
        }
    }

    #[test]
    fn phrase_expression_is_one_unprefixed_fts5_phrase() {
        assert_eq!(
            phrase_expression("Error: DB connection NEAR(x) \"lost\"*").as_deref(),
            Some("\"error db connection near x lost\"")
        );
        assert_eq!(phrase_expression("\"*():^"), None);
    }

    #[test]
    fn phrase_tiers_put_the_literal_name_first() {
        let p = "parse_request";
        assert_eq!(phrase_tier("parse_request", p), 0);
        assert_eq!(phrase_tier("PARSE_REQUEST", p), 0);
        assert_eq!(phrase_tier("parse_request", "parse_request();"), 0);
        assert_eq!(phrase_tier("ParseRequest", "parse_request();"), 1);
        assert_eq!(phrase_tier("ParseRequest", p), 1);
        assert_eq!(phrase_tier("parse_request_body", p), 2);
        assert_eq!(phrase_tier("ParseRequestBody", p), 3);
    }

    #[test]
    fn tiers_put_exact_before_compact_before_prefix() {
        let q = "parserequest";
        assert_eq!(match_tier("ParseRequest", q, "parserequest"), 0);
        assert_eq!(
            match_tier("parse_request", "parse request", "parserequest"),
            1
        );
        assert_eq!(
            match_tier("parse_request_body", "parse request", "parserequest"),
            2
        );
        assert_eq!(
            match_tier("request_parser", "parse request", "parserequest"),
            3
        );
    }
}

