"use client";
import {
  Component,
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { motion, useInView } from "motion/react";
import { useTranslation } from "react-i18next";
import Link from "next/link";
import { ArrowUpRight, Maximize2, Minimize2 } from "lucide-react";

import {
  examples,
  layerKeys,
  storyStages,
  tourStages,
  type AtlasLayers,
  type Cue,
} from "./atlas-data";
import { fileSymbols } from "./atlas-symbols";
import { CopyCommand, setupCommands } from "./copy-command";

const SpatialAtlas = lazy(() => import("./spatial-atlas"));
class SceneBoundary extends Component<
  { children: ReactNode; onFailure: () => void },
  { failed: boolean }
> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  componentDidCatch() {
    this.props.onFailure();
  }
  render() {
    return this.state.failed ? null : this.props.children;
  }
}
export function Atlas() {
  const { t } = useTranslation();
  const [selected, setSelected] = useState(0);
  const [expanded, setExpanded] = useState(false);
  const [activeStage, setActiveStage] = useState(0);
  const [storyStage, setStoryStage] = useState(0);
  const [layers, setLayers] = useState<AtlasLayers>([true, true, true]);
  const separation = 1.45;
  const [rotation, setRotation] = useState(0.2);
  const [reset, setReset] = useState(0);
  const [cue, setCue] = useState<Cue>({ key: "idle", id: 0 });
  const [details, setDetails] = useState(false);
  const firstSummary = useRef<HTMLElement>(null);
  const [spatial, setSpatial] = useState(false);
  const [failed, setFailed] = useState(false);
  const [ready, setReady] = useState(false);
  const sceneReady = useCallback(() => setReady(true), []);
  const sceneFailure = useCallback(() => {
    setSpatial(false);
    setReady(false);
    setFailed(true);
  }, []);
  const [visible, setVisible] = useState(true);
  // Keep browser preferences out of the server and initial hydration render.
  const [reduced, setReduced] = useState(true);
  const root = useRef<HTMLDivElement>(null);
  const expandButton = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!expanded) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const keyboard = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        setExpanded(false);
        return;
      }
      if (event.key !== "Tab") return;
      const controls = Array.from(
        root.current?.querySelectorAll<HTMLElement>(
          'a[href], button:not(:disabled), input, summary, [tabindex="0"]',
        ) ?? [],
      ).filter(
        (element) =>
          element.getClientRects().length &&
          getComputedStyle(element).visibility !== "hidden",
      );
      const first = controls[0];
      const last = controls[controls.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    };
    expandButton.current?.focus();
    document.addEventListener("keydown", keyboard);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", keyboard);
      expandButton.current?.focus();
    };
  }, [expanded]);
  // One observer marks the stage crossing the middle of the dialog in full screen, or
  // the story stage crossing the middle of the viewport on the page.
  useEffect(() => {
    const atlas = root.current;
    if (!atlas) return;
    if (expanded) {
      setActiveStage(0);
      setDetails(false);
    }
    const setStage = expanded ? setActiveStage : setStoryStage;
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries)
          if (entry.isIntersecting)
            setStage(Number((entry.target as HTMLElement).dataset.stage));
      },
      { root: expanded ? atlas : null, rootMargin: "-45% 0px -50% 0px" },
    );
    atlas
      .querySelectorAll(expanded ? ".atlas-stage" : ".atlas-story-stage")
      .forEach((stage) => observer.observe(stage));
    return () => observer.disconnect();
  }, [expanded]);
  const tourStage = expanded ? tourStages[activeStage] : undefined;
  const story = storyStages[storyStage];
  const stage = tourStage ?? story;
  // A stage selects its symbol when it activates; leaving full screen keeps the
  // selection made there, because the story stage itself has not changed.
  useEffect(() => {
    if (tourStage?.symbol)
      setSelected(examples.findIndex(({ name }) => name === tourStage.symbol));
  }, [tourStage]);
  useEffect(() => {
    if (story.symbol)
      setSelected(examples.findIndex(({ name }) => name === story.symbol));
  }, [story]);
  // Each stage that reaches the middle plays its cue once.
  useEffect(() => {
    setCue(({ id }) => ({ key: stage.key, id: id + 1 }));
  }, [stage]);
  useEffect(() => {
    if (details) firstSummary.current?.focus();
  }, [details]);
  // The scene, not the whole atlas: the story makes the atlas much taller than its scene.
  const space = useRef<HTMLDivElement>(null);
  const inView = useInView(space);
  useEffect(() => {
    const motionPreference = matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(motionPreference.matches);
    update();
    motionPreference.addEventListener("change", update);
    const visibility = () => setVisible(!document.hidden);
    document.addEventListener("visibilitychange", visibility);
    return () => {
      motionPreference.removeEventListener("change", update);
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  // Load on approach, then retain the scene while demand rendering pauses offscreen.
  useEffect(() => {
    if (!inView || spatial || failed) return;
    try {
      const canvas = document.createElement("canvas");
      const gl = canvas.getContext("webgl2");
      if (!gl) {
        setFailed(true);
        return;
      }
      gl.getExtension("WEBGL_lose_context")?.loseContext();
      setSpatial(true);
    } catch {
      setFailed(true);
    }
  }, [inView, spatial, failed]);
  const controls = (
    <div className="spatial-controls">
      {ready && (
        <>
          <button
            type="button"
            onClick={() => setRotation((value) => value + Math.PI / 4)}
          >
            {t("rotate")} ↻
          </button>
          <button
            type="button"
            onClick={() => {
              setRotation(0.2);
              setReset((value) => value + 1);
            }}
          >
            {t("resetView")}
          </button>
        </>
      )}
      <button
        ref={expandButton}
        type="button"
        className="atlas-expand"
        onClick={() => setExpanded((value) => !value)}
        aria-label={t(expanded ? "exitFullscreen" : "fullscreen")}
      >
        {expanded ? (
          <Minimize2 size={16} aria-hidden="true" />
        ) : (
          <Maximize2 size={16} aria-hidden="true" />
        )}
        <span>{t(expanded ? "exitFullscreen" : "fullscreen")}</span>
      </button>
    </div>
  );
  return (
    <div
      className={`atlas${expanded ? " atlas-expanded" : ""}`}
      ref={root}
      data-scene={failed ? "failed" : ready ? "ready" : "loading"}
      data-story-stage={expanded ? undefined : storyStage}
      role={expanded ? "dialog" : undefined}
      aria-modal={expanded ? true : undefined}
      aria-label={expanded ? t("atlas") : undefined}
    >
      <div className="atlas-toolbar">
        <div
          className="atlas-layer-toggles"
          role="group"
          aria-label={t("visibleLayers")}
        >
          {layerKeys.map((key, i) => (
            <button
              key={key}
              type="button"
              aria-pressed={layers[i]}
              onClick={() =>
                setLayers((previous) => {
                  const next: AtlasLayers = [...previous];
                  if (previous[i] && previous.filter(Boolean).length === 1)
                    return previous;
                  next[i] = !previous[i];
                  return next;
                })
              }
            >
              <span>0{i + 1}</span> {t(key)}
            </button>
          ))}
        </div>
      </div>
      <div className="atlas-view">
        <div className="atlas-space" ref={space}>
          {!ready && !failed && (
            <p className="atlas-loading" role="status">
              {t("loading3d")}
            </p>
          )}
          {spatial && (
            <div
              className="spatial-layer"
              data-testid="spatial-layer"
              data-cue={cue.key}
            >
              <SceneBoundary onFailure={sceneFailure}>
                <Suspense fallback={null}>
                  <SpatialAtlas
                    selected={selected}
                    layers={layers}
                    focusLayer={stage.layer}
                    view={tourStage ? undefined : story.view}
                    separation={separation}
                    cue={cue}
                    rotation={rotation}
                    reset={reset}
                    onSelect={setSelected}
                    onReady={sceneReady}
                    active={(inView || expanded) && visible}
                    reduced={reduced}
                    onFailure={sceneFailure}
                  />
                </Suspense>
              </SceneBoundary>
            </div>
          )}
          {!failed && controls}
        </div>
        {failed && (
          <p className="atlas-fallback" role="status">
            {t("fallback")}
          </p>
        )}
        {/* .atlas-space hides beside the fallback, so the row follows it instead. */}
        {failed && controls}
        {/* Full screen has its own tour, so the story lives only on the page. */}
        {!expanded && (
          <ol className="atlas-story">
            {storyStages.map(({ key }, i) => (
              <li
                key={key}
                className="atlas-story-stage"
                data-stage={i}
                aria-current={storyStage === i ? "step" : undefined}
              >
                <span className="step-number mono">0{i + 1}</span>
                <h3>{t(`${key}Title`)}</h3>
                <p>{t(`${key}Text`)}</p>
              </li>
            ))}
          </ol>
        )}
        {expanded && (
          <div className="atlas-tour" data-active-stage={activeStage}>
            {tourStages.map(({ key, icon: Icon, methods, tools, docs }, i) => (
              <motion.section
                key={key}
                className="atlas-stage"
                data-stage={i}
                aria-labelledby={`${key}-title`}
                initial={reduced ? false : { opacity: 0, y: 12 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, root }}
              >
                <Icon size={20} aria-hidden="true" />
                <h3 id={`${key}-title`}>{t(`${key}Title`)}</h3>
                <p>{t(`${key}Text`)}</p>
                {methods && (
                  <ul className="atlas-tools">
                    {methods.map(({ name, at, link }) => (
                      <li key={name}>
                        <p className="atlas-tool-call">
                          <code>{name}</code> <span>{at}</span>
                        </p>
                        <p>{link}</p>
                      </li>
                    ))}
                  </ul>
                )}
                {tools && (
                  <ul className="atlas-tools">
                    {tools.map(({ name, params, replaces }) => (
                      <li key={name}>
                        <p className="atlas-tool-call">
                          <code>{name}</code> <span>{params}</span>
                        </p>
                        <p>{t(`ask_${name}`)}</p>
                        {replaces && (
                          <p className="atlas-tool-replaces">
                            {t("replaces")} <code>{replaces}</code>
                          </p>
                        )}
                      </li>
                    ))}
                  </ul>
                )}
                {docs && (
                  <>
                    <button
                      type="button"
                      className="atlas-details-toggle"
                      aria-expanded={details}
                      aria-controls="atlas-details"
                      onClick={() => setDetails((value) => !value)}
                    >
                      {t(details ? "hideSymbols" : "allSymbols")}
                    </button>
                    {/* Mounted only when open, so the FAQ keeps the page's first <details>. */}
                    {details && (
                      <section
                        id="atlas-details"
                        className="atlas-details"
                        aria-labelledby="atlas-details-title"
                      >
                        <h4 id="atlas-details-title">{t("allSymbolsTitle")}</h4>
                        {fileSymbols.map(({ file, symbols }, i) => (
                          // A shared name keeps one section open at a time.
                          <details key={file} name="atlas-files">
                            <summary ref={i === 0 ? firstSummary : undefined}>
                              {file} ·{" "}
                              {t("symbolCount", { count: symbols.length })}
                            </summary>
                            <ul>
                              {symbols.map(([line, name, kind, pub]) => (
                                <li key={line}>
                                  <code>{name}</code>
                                  <span>
                                    {pub ? "pub " : ""}
                                    {kind} · {line}
                                  </span>
                                </li>
                              ))}
                            </ul>
                          </details>
                        ))}
                      </section>
                    )}
                    <div className="command-panel">
                      {setupCommands.map(({ command, label }) => (
                        <CopyCommand
                          key={command}
                          command={command}
                          label={t(label)}
                        />
                      ))}
                    </div>
                    <Link href={docs} className="text-link">
                      {t("toolsReference")}
                      <ArrowUpRight size={16} aria-hidden="true" />
                    </Link>
                  </>
                )}
              </motion.section>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Combobox } from "@base-ui/react/combobox";
import { ArrowRight, ChevronDown } from "lucide-react";
import { useTranslation } from "react-i18next";

const source = `const currency = "EUR";
const taxRate = 0.21;
const paymentTerms = 30;

export function calculateTotal(price, quantity = 1) {
  const subtotal = price * quantity;
  const tax = subtotal * taxRate;
  return subtotal + tax;
}

export function formatPrice(price) {
  return new Intl.NumberFormat("en-IE", {
    style: "currency",
    currency,
  }).format(price);
}

export function invoiceLabel(id) {
  return \`Invoice #\${id}\`;
}

export function paymentDue(issuedAt) {
  const due = new Date(issuedAt);
  due.setDate(due.getDate() + paymentTerms);
  return due.toISOString().slice(0, 10);
}

export function customerDetails(customer) {
  return {
    name: customer.name,
    email: customer.email,
    address: customer.billingAddress,
  };
}

export function invoiceStatus(invoice) {
  if (invoice.paidAt) return "paid";
  const due = paymentDue(invoice.issuedAt);
  const today = new Date().toISOString().slice(0, 10);
  return due < today ? "overdue" : "pending";
}

export function createInvoice(id, customer, items) {
  return {
    id,
    customer: customerDetails(customer),
    items,
    issuedAt: new Date().toISOString(),
    paidAt: null,
  };
}`;

const sourceLines = source.split("\n");
// 0-based indexes of a top-level declaration: a `const` line or a whole function.
function declaration(name: string): number[] {
  const start = sourceLines.findIndex(
    (line) =>
      line.startsWith(`const ${name} `) ||
      line.startsWith(`export function ${name}(`),
  );
  const end = sourceLines[start].startsWith("const ")
    ? start
    : sourceLines.indexOf("}", start);
  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}
// Each query selects the declarations that answer it.
const queries = [
  ["taxRate", "calculateTotal"],
  ["paymentTerms", "paymentDue"],
  ["paymentTerms", "paymentDue", "invoiceStatus"],
  ["customerDetails", "createInvoice"],
  ["currency", "formatPrice"],
].map((names) => new Set(names.flatMap(declaration)));
const queryIds = queries.map((_, index) => String(index));

function buildLines(query: number) {
  return sourceLines.map((text, index) => ({
    text,
    number: index + 1,
    relevant: queries[query].has(index),
  }));
}

export function ContextDemo() {
  const { t } = useTranslation();
  const [focused, setFocused] = useState(false);
  const [query, setQuery] = useState("0");
  const lines = buildLines(Number(query));
  const selection = lines.filter((line) => line.relevant);
  const visible = focused ? selection : lines;

  return (
    <section className="context-demo" aria-labelledby="demo-title">
      <div className="demo-intro">
        <span className="demo-badge">{t("demoBadge")}</span>
        <h2 id="demo-title">{t("demoTitle")}</h2>
        <Combobox.Root
          items={queryIds}
          value={query}
          onValueChange={(next) => next && setQuery(next)}
          openOnInputClick
          itemToStringLabel={(id) => t(`demoQuery${id}`)}
        >
          <Combobox.Label className="demo-combo-label">
            {t("demoQueryLabel")}
          </Combobox.Label>
          <Combobox.InputGroup className="demo-combo">
            <Combobox.Input className="demo-combo-input" readOnly />
            <Combobox.Trigger
              className="demo-combo-trigger"
              aria-label={t("demoQueryLabel")}
            >
              <ChevronDown size={16} aria-hidden="true" />
            </Combobox.Trigger>
          </Combobox.InputGroup>
          <Combobox.Portal>
            <Combobox.Positioner sideOffset={6} className="demo-combo-layer">
              <Combobox.Popup className="demo-combo-popup">
                <Combobox.List>
                  {(id: string) => (
                    <Combobox.Item
                      key={id}
                      value={id}
                      className="demo-combo-item"
                    >
                      {t(`demoQuery${id}`)}
                    </Combobox.Item>
                  )}
                </Combobox.List>
              </Combobox.Popup>
            </Combobox.Positioner>
          </Combobox.Portal>
        </Combobox.Root>
        <div className="demo-count">
          <strong>{lines.length}</strong>
          <ArrowRight size={18} aria-hidden="true" />
          <strong>{selection.length}</strong>
          <span>{t("demoLines")}</span>
        </div>
        <div className="demo-controls" role="group" aria-label={t("demoView")}>
          {[false, true].map((mode) => (
            <button
              key={String(mode)}
              type="button"
              aria-pressed={focused === mode}
              aria-controls="demo-code"
              onClick={() => setFocused(mode)}
            >
              <span aria-hidden="true">{focused === mode ? "●" : "○"}</span>
              {t(mode ? "demoRelevant" : "demoFull")}
            </button>
          ))}
        </div>
      </div>
      <div className="demo-filebar">
        <span>invoice.js</span>
        <span>{t(focused ? "demoRelevant" : "demoFull")}</span>
      </div>
      <div className="demo-editor">
        <div
          id="demo-code"
          className="demo-code"
          tabIndex={0}
          role="region"
          aria-label={t("demoCode")}
          key={String(focused)}
        >
          <pre>
            <code>
              {visible.map((line) => (
                <span
                  key={line.number}
                  className={`demo-line${line.relevant ? " is-relevant" : ""}`}
                >
                  <span className="demo-line-number" aria-hidden="true">
                    {line.number}
                  </span>
                  <span>{line.text || " "}</span>
                  {"\n"}
                </span>
              ))}
            </code>
          </pre>
        </div>
        <div className="demo-minimap" aria-hidden="true">
          {lines.map((line) => (
            <span
              key={line.number}
              className={
                line.relevant ? "is-relevant" : focused ? "is-omitted" : ""
              }
            />
          ))}
        </div>
      </div>
      <div className="demo-summary">
        <p role="status">{t(focused ? "demoSelectionNote" : "demoFullNote")}</p>
      </div>
      <p className="demo-disclaimer">{t("demoDisclaimer")}</p>
    </section>
  );
}

